// Thread-local storage for the last input text value.
// Used by the static code path to pass input text from on_input callbacks
// to Component::on() handlers, since the generic message type M cannot carry String.
thread_local! {
    static INPUT_TEXT: std::cell::RefCell<String> = std::cell::RefCell::new(String::new());
}

// Plan 309 续篇 II: when true, interactive widgets are built WITHOUT their
// event handlers so they don't capture presses/hovers — letting the
// `wrap_debug` mouse_area capture inspect hover/click over EVERY element
// (buttons, inputs, sliders, …). Set once per view build at `dynamic_view`
// entry from `debug_mode && inspect_mode && !alt_held`. Read in `into_iced`
// (to gate handlers) and `wrap_debug` (to gate the capturing mouse_area).
thread_local! {
    static INSPECT_CAPTURE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

// Plan 453 T4c（裁定 M1 落地）：原 LAST_MODIFIERS thread-local 已删除——
// 修饰键唯一事实源为 `DesktopState.current_modifiers`：窗口事件订阅把
// `modifiers.bits()` 塞进 `__modifiers_changed` 消息载荷，update 既有臂解析
// 写回；view 直接读字段决定 INSPECT_CAPTURE（施工图 §4）。

/// Helper: is the inspect picker currently in "capture" mode (plain click =
/// inspect over all widgets)?
fn inspect_capture_active() -> bool {
    INSPECT_CAPTURE.with(|c| c.get())
}

/// Static storage for textarea editor contents.
/// Required because iced's `text_editor` widget needs `&'static Content<Renderer>`.
/// Each entry is a leaked Box that lives for the entire process lifetime.
/// We store `&'static mut` but only ever mutate under the Mutex, so the
/// shared references we hand out remain valid.
use std::sync::Mutex;
lazy_static::lazy_static! {
    static ref TEXTAREA_CONTENTS: Mutex<std::collections::HashMap<String, &'static mut text_editor::Content>> =
        Mutex::new(std::collections::HashMap::new());
    /// Plan 057 续(keydown 失焦修复):onkeydown.* 派发的 handler 消息键
    /// ("{widget}_{event}",如 PromptBar_AcceptGhost)→ 所属编辑器的 action key
    /// (如 PromptBar_OnInputComplete)。这些 handler 会改 input/ghost/suggestions,
    /// 重建时候选行显隐造成树位移丢焦点 —— update 据此映射触发重聚焦。
    static ref TEXTAREA_KEYDOWN_TO_EDITOR: Mutex<std::collections::HashMap<String, String>> =
        Mutex::new(std::collections::HashMap::new());
}

/// Plan 057 (ash-gui 光标可见): PlainText highlighter 的 to_format —— 把编辑器
/// 文字整体染透明(overlay 高亮层负责显示彩色文字),让 style.value 专职 caret 颜色。
fn text_editor_text_transparent(
    _highlight: &(),
    _theme: &iced::Theme,
) -> iced_widget::core::text::highlighter::Format<iced::Font> {
    iced_widget::core::text::highlighter::Format {
        color: Some(iced::Color::TRANSPARENT),
        font: None,
    }
}

/// Plan 057 续(Tab 补全):把 iced KeyPress 规范化为 .at onkeydown 的键名
/// ("tab"/"up"/"down"/"ctrl.r"/"ctrl.right"…)。修饰键前缀 ctrl./alt./shift.。
fn key_press_to_binding_name(kp: &text_editor::KeyPress) -> String {
    use iced::keyboard::{Key, key};
    let base = match &kp.key {
        Key::Named(n) => match n {
            key::Named::Tab => "tab".to_string(),
            key::Named::ArrowUp => "up".to_string(),
            key::Named::ArrowDown => "down".to_string(),
            key::Named::ArrowLeft => "left".to_string(),
            key::Named::ArrowRight => "right".to_string(),
            key::Named::Enter => "enter".to_string(),
            key::Named::Escape => "escape".to_string(),
            key::Named::Home => "home".to_string(),
            key::Named::End => "end".to_string(),
            key::Named::Delete => "delete".to_string(),
            key::Named::Backspace => "backspace".to_string(),
            key::Named::PageUp => "pageup".to_string(),
            key::Named::PageDown => "pagedown".to_string(),
            key::Named::Space => " ".to_string(),
            _ => String::new(),
        },
        Key::Character(c) => c.to_string(),
        _ => String::new(),
    };
    if base.is_empty() {
        return String::new();
    }
    let mut name = String::new();
    if kp.modifiers.control() { name.push_str("ctrl."); }
    if kp.modifiers.alt() { name.push_str("alt."); }
    if kp.modifiers.shift() && matches!(kp.key, Key::Named(_)) { name.push_str("shift."); }
    name + &base
}

// ═══ Plan 057 续(行内编辑 keymap):快捷键与功能分离 ═════════════════
// 三层架构:.at onkeydown.*(App 语义) → 模式键位表(emacs/vi-*) → iced
// 默认。纯编辑键(移动/词移/kill/yank/transpose)在渲染层直接执行
// (Content::perform 组合 + 合成 on_change 消息同步状态),不经 .at 往返;
// 语义键(Tab 补全/历史/ghost 接受/模式切换)派发 .at handler。

/// 独立 kill-ring(readline 语义:最近 16 条;不污染系统剪贴板)。
lazy_static::lazy_static! {
    static ref TEXTAREA_KILL_RING: Mutex<std::collections::VecDeque<String>> =
        Mutex::new(std::collections::VecDeque::new());
    /// echo 标志:update 检测到消息源自编辑器自身(编辑/光标动作)时置位;
    /// 下一次该 key 的 content 重建保持光标字节偏移(编辑点),而非钉到
    /// value 末尾 —— C-b 后继续打字光标不再被拽走(行内编辑地基)。
    static ref TEXTAREA_ECHO_KEYS: Mutex<std::collections::HashSet<String>> =
        Mutex::new(std::collections::HashSet::new());
}

/// 与键位无关的行编辑功能抽象。表条目按模式声明,执行统一走 le_execute。
#[derive(Debug, Clone)]
enum LineEditOp {
    /// 纯 iced 原生绑定(Move/Backspace/Enter…)—— 编辑器自己执行,保持
    /// 捕获/选区语义;on_action 照常回投(状态同步 + echo 光标保持)。
    Native(text_editor::Binding<IcedMessage>),
    /// kill 到指定方向(End=行尾 C-k / Home=行首到光标 C-u / Word* =词)。
    Kill(text_editor::Motion),
    /// C-y:kill-ring 末条粘贴。
    Yank,
    /// C-t:交换光标两侧字符(行尾时交换最后两个)。
    TransposeChars,
    /// C-d:空输入(剥离 ghost 后)派发 .at 退出 handler;否则前删一字符。
    DeleteCharOrExit,
    /// vi x:前删一字符;空输入无动作(不退出)。
    DeleteForward,
    /// 语义键派发 .at handler(onkeydown 表)。
    Handler,
    /// 切换编辑模式(合成 SetEditMode 派发,input_value = 目标模式)。
    SetMode(&'static str),
    /// 复合操作(vi:append = 切 insert + 右移)。
    Seq(Vec<LineEditOp>),
    /// vi-normal 的 d 前缀进入 pending(dd/dw/db)。
    BeginPending,
    /// 吞掉按键(捕获但不动作)—— vi-normal 未映射可打印字符的兜底。
    Swallow,
}

fn le_push_kill(text: String) {
    let mut ring = TEXTAREA_KILL_RING.lock().unwrap();
    if ring.back().map(|b| b == &text).unwrap_or(false) {
        return; // 连续 kill 合并(readline 语义)
    }
    ring.push_back(text);
    while ring.len() > 16 {
        ring.pop_front();
    }
}

/// Content 光标 → 全文字节偏移(列即行内字节偏移,cosmic-text 语义)。
fn le_cursor_offset(c: &text_editor::Content) -> usize {
    let cur = c.cursor();
    let mut off = 0usize;
    for (i, line) in c.lines().enumerate() {
        if i == cur.position.line {
            return off + cur.position.column.min(line.text.len());
        }
        off += line.text.len() + 1; // '\n'
    }
    off
}

/// 全文字节偏移 → move_to(单/多行,列按字节)。
fn le_move_to_offset(c: &mut text_editor::Content, text: &str, off: usize) {
    let pos = le_offset_to_pos(text, off);
    c.move_to(text_editor::Cursor {
        position: pos,
        selection: None,
    });
}

fn le_offset_to_pos(text: &str, off: usize) -> iced_widget::core::text::editor::Position {
    let off = off.min(text.len());
    let mut line = 0usize;
    let mut before = 0usize;
    for (i, l) in text.split('\n').enumerate() {
        if before + l.len() >= off {
            line = i;
            break;
        }
        before += l.len() + 1;
        line = i + 1;
    }
    iced_widget::core::text::editor::Position {
        line,
        column: off.saturating_sub(before),
    }
}

fn ch_len_at(s: &str, i: usize) -> usize {
    s[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1)
}

/// 在 key 的 Content 上删除显式字节范围 → 入 kill-ring。
/// 返回删除的文本(None = 范围空)。不用 cosmic 的 Select(motion)——其
/// 选区锚点会吸附词边界(实测起点 = 光标+1,跨空格错位);显式范围精确。
fn le_kill_range(key: &str, range: std::ops::Range<usize>) -> Option<String> {
    if range.start >= range.end {
        return None;
    }
    let mut map = TEXTAREA_CONTENTS.lock().unwrap();
    let content = map.get_mut(key)?;
    let text = content.text();
    let range = range.start.min(text.len())..range.end.min(text.len());
    if range.start >= range.end {
        return None;
    }
    let killed = text[range.clone()].to_string();
    // 不用 cosmic 选区删除 —— 显式选区 + Edit::Delete 的实测语义比设定
    // 范围多删一个字形起始(Affinity::Before)。改为手动拼接重建,光标
    // 落在删除起点(编辑点),完全确定性。
    let new_text = format!("{}{}", &text[..range.start], &text[range.end..]);
    **content = text_editor::Content::with_text(&new_text);
    le_move_to_offset(content, &new_text, range.start);
    Some(killed)
}

/// readline 语义的 kill 方向计算(基于当前光标,自算边界):
/// End = 光标→行尾;Home = 行首→光标;WordRight = 跳过空白再吃一个词;
/// WordLeft(unix-word-rubout)= 连空白带词向后吃。
fn le_kill_motion(key: &str, motion: text_editor::Motion) -> Option<String> {
    let (text, cur) = {
        let map = TEXTAREA_CONTENTS.lock().unwrap();
        let c = map.get(key)?;
        (c.text(), le_cursor_offset(c))
    };
    let line_start = text[..cur].rfind('\n').map(|i| i + 1).unwrap_or(0);
    let line_end = text[cur..].find('\n').map(|i| cur + i).unwrap_or(text.len());
    let range = match motion {
        text_editor::Motion::End => cur..line_end,
        text_editor::Motion::Home => line_start..cur,
        text_editor::Motion::DocumentEnd => cur..text.len(),
        text_editor::Motion::DocumentStart => 0..cur,
        text_editor::Motion::WordRight => {
            // 跳过空白,吃一个词(非空白连续段),停在词尾。
            let b = text.as_bytes();
            let mut i = cur;
            while i < b.len() && (b[i] as char).is_whitespace() {
                i += 1;
            }
            while i < b.len() && !(b[i] as char).is_whitespace() {
                i += 1;
            }
            cur..i
        }
        _ => {
            // WordLeft / 其他:向后连空白带词一起吃。
            let mut i = cur;
            let b = text.as_bytes();
            while i > 0 && (b[i - 1] as char).is_whitespace() {
                i -= 1;
            }
            while i > 0 && !(b[i - 1] as char).is_whitespace() {
                i -= 1;
            }
            i..cur
        }
    };
    le_kill_range(key, range)
}

/// 执行复合原生操作;文本变化时返回合成 on_change 消息(Custom 派发)。
fn le_execute(
    key: &str,
    op: LineEditOp,
    on_change: &IcedMessage,
) -> Option<text_editor::Binding<IcedMessage>> {
    use text_editor::Binding;
    let sync = |new_text: &str| -> Binding<IcedMessage> {
        Binding::Custom(IcedMessage {
            widget: on_change.widget.clone(),
            event: on_change.event.clone(),
            input_value: Some(strip_ghost_suffix(key, new_text)),
        })
    };
    let dispatch = |event: &str, val: &str| -> Binding<IcedMessage> {
        Binding::Custom(IcedMessage {
            widget: on_change.widget.clone(),
            event: event.to_string(),
            input_value: Some(val.to_string()),
        })
    };
    match op {
        LineEditOp::Native(b) => Some(b),
        LineEditOp::Swallow => Some(Binding::Sequence(vec![])),
        LineEditOp::Seq(ops) => {
            // 复合:依次执行,返回最后一个产生的绑定。
            let mut last = Binding::Sequence(vec![]);
            for sub in ops {
                if let Some(b) = le_execute(key, sub, on_change) {
                    last = b;
                }
            }
            Some(last)
        }
        LineEditOp::Kill(motion) => match le_kill_motion(key, motion) {
            Some(k) => {
                le_push_kill(k);
                let text = TEXTAREA_CONTENTS
                    .lock()
                    .unwrap()
                    .get(key)
                    .map(|c| c.text())
                    .unwrap_or_default();
                Some(sync(&text))
            }
            None => Some(Binding::Sequence(vec![])),
        },
        LineEditOp::Yank => {
            let yank_text = TEXTAREA_KILL_RING.lock().unwrap().back().cloned();
            match yank_text {
                Some(t) => {
                    let text = textarea_perform_action(
                        key,
                        text_editor::Action::Edit(text_editor::Edit::Paste(
                            std::sync::Arc::new(t),
                        )),
                    );
                    Some(sync(&text))
                }
                None => Some(Binding::Sequence(vec![])),
            }
        }
        LineEditOp::TransposeChars => {
            let mut map = TEXTAREA_CONTENTS.lock().unwrap();
            let content = map.get_mut(key)?;
            let text = content.text();
            if text.chars().count() < 2 {
                return Some(Binding::Sequence(vec![]));
            }
            let off = le_cursor_offset(content).min(text.len());
            // readline:光标在行尾时交换最后两个字符,否则交换光标前后字符。
            let (a, b, c1, c2) = if off >= text.len() {
                // 行尾:最后两个字符
                let mut idx = text.char_indices().collect::<Vec<_>>();
                idx.reverse();
                let last_start = idx.first().map(|(i, _)| *i).unwrap_or(0);
                let second_start = idx.get(1).map(|(i, _)| *i).unwrap_or(0);
                (
                    second_start,
                    text.len(),
                    text[second_start..last_start].chars().next().unwrap_or(' '),
                    text[last_start..].chars().next().unwrap_or(' '),
                )
            } else {
                let b_end = (off + ch_len_at(&text, off)).min(text.len());
                let mut a_start = 0;
                for (i, _) in text.char_indices() {
                    if i + ch_len_at(&text, i) >= off {
                        a_start = i;
                        break;
                    }
                }
                (
                    a_start,
                    b_end,
                    text[a_start..off].chars().last().unwrap_or(' '),
                    text[off..].chars().next().unwrap_or(' '),
                )
            };
            let _ = (a, b);
            // 选区 [a, b) → Delete → 按 c2、c1 顺序插入(净效果 = 交换)。
            content.move_to(text_editor::Cursor {
                position: le_offset_to_pos(&text, a),
                selection: Some(le_offset_to_pos(&text, b)),
            });
            content.perform(text_editor::Action::Edit(text_editor::Edit::Delete));
            content.perform(text_editor::Action::Edit(text_editor::Edit::Insert(c2)));
            content.perform(text_editor::Action::Edit(text_editor::Edit::Insert(c1)));
            let new_text = content.text();
            drop(map);
            Some(sync(&new_text))
        }
        LineEditOp::DeleteCharOrExit => {
            let mut map = TEXTAREA_CONTENTS.lock().unwrap();
            let content = map.get_mut(key)?;
            let stripped_len = strip_ghost_suffix(key, &content.text()).len();
            if stripped_len == 0 {
                drop(map);
                Some(dispatch("OnCtrlD", ""))
            } else {
                content.perform(text_editor::Action::Edit(text_editor::Edit::Delete));
                let t = content.text();
                drop(map);
                Some(sync(&t))
            }
        }
        LineEditOp::DeleteForward => {
            let mut map = TEXTAREA_CONTENTS.lock().unwrap();
            let content = map.get_mut(key)?;
            if content.text().is_empty() {
                return Some(Binding::Sequence(vec![]));
            }
            content.perform(text_editor::Action::Edit(text_editor::Edit::Delete));
            let t = content.text();
            drop(map);
            Some(sync(&t))
        }
        LineEditOp::SetMode(mode) => Some(dispatch("SetEditMode", mode)),
        LineEditOp::BeginPending => Some(Binding::Sequence(vec![])), // 闭包层处理
        LineEditOp::Handler => None, // 交由外层回落(.at 未声明则默认)
    }
}

/// 各模式键位表。键名与 key_press_to_binding_name 规范一致。
fn line_edit_keymap(mode: &str) -> std::collections::HashMap<String, LineEditOp> {
    use text_editor::{Binding, Motion};
    let nat = |b: Binding<IcedMessage>| LineEditOp::Native(b);
    let mut m: std::collections::HashMap<String, LineEditOp> = std::collections::HashMap::new();
    // ── Emacs(readline)全集 ──
    m.insert("ctrl.a".into(), nat(Binding::Move(Motion::Home)));
    m.insert("ctrl.b".into(), nat(Binding::Move(Motion::Left)));
    m.insert("ctrl.e".into(), nat(Binding::Move(Motion::End)));
    m.insert("ctrl.f".into(), nat(Binding::Move(Motion::Right)));
    m.insert("ctrl.h".into(), nat(Binding::Backspace));
    m.insert("alt.b".into(), nat(Binding::Move(Motion::WordLeft)));
    m.insert("alt.f".into(), nat(Binding::Move(Motion::WordRight)));
    m.insert("ctrl.k".into(), LineEditOp::Kill(Motion::End));
    m.insert("ctrl.u".into(), LineEditOp::Kill(Motion::Home));
    m.insert("alt.d".into(), LineEditOp::Kill(Motion::WordRight));
    m.insert("alt.backspace".into(), LineEditOp::Kill(Motion::WordLeft));
    m.insert("ctrl.w".into(), LineEditOp::Kill(Motion::WordLeft));
    m.insert("ctrl.y".into(), LineEditOp::Yank);
    m.insert("ctrl.t".into(), LineEditOp::TransposeChars);
    m.insert("ctrl.d".into(), LineEditOp::DeleteCharOrExit);
    m.insert("enter".into(), nat(Binding::Enter));
    match mode {
        "vi-insert" => {
            // insert 态 = Emacs 等价 + Esc 回 normal。
            m.insert("escape".into(), LineEditOp::SetMode("vi-normal"));
        }
        "vi-normal" => {
            m.clear();
            m.insert("h".into(), nat(Binding::Move(Motion::Left)));
            m.insert("l".into(), nat(Binding::Move(Motion::Right)));
            m.insert("0".into(), nat(Binding::Move(Motion::Home)));
            m.insert("^".into(), nat(Binding::Move(Motion::Home)));
            m.insert("$".into(), nat(Binding::Move(Motion::End)));
            m.insert("w".into(), nat(Binding::Move(Motion::WordRight)));
            m.insert("b".into(), nat(Binding::Move(Motion::WordLeft)));
            m.insert("e".into(), nat(Binding::Move(Motion::WordRight)));
            m.insert("G".into(), nat(Binding::Move(Motion::End)));
            m.insert("x".into(), LineEditOp::DeleteForward);
            m.insert("X".into(), nat(Binding::Backspace));
            m.insert("D".into(), LineEditOp::Kill(Motion::End));
            m.insert("d".into(), LineEditOp::BeginPending);
            m.insert("i".into(), LineEditOp::SetMode("vi-insert"));
            m.insert("I".into(), LineEditOp::Seq(vec![
                LineEditOp::SetMode("vi-insert"),
                LineEditOp::Native(Binding::Move(Motion::Home)),
            ]));
            m.insert("a".into(), LineEditOp::Seq(vec![
                LineEditOp::SetMode("vi-insert"),
                LineEditOp::Native(Binding::Move(Motion::Right)),
            ]));
            m.insert("A".into(), LineEditOp::Seq(vec![
                LineEditOp::SetMode("vi-insert"),
                LineEditOp::Native(Binding::Move(Motion::End)),
            ]));
            m.insert("enter".into(), nat(Binding::Enter));
        }
        _ => {}
    }
    m
}

/// Plan 057 续(Tab 补全):给编辑器挂 key_binding — 声明过的 onkeydown 键
/// 以 Binding::Custom 派发 handler(不落入编辑器默认行为,Tab 不再被静默
/// 丢弃、up/down 走历史导航);未声明的键回落 iced 默认(输入/Enter/退格…)。
fn with_textarea_keydown<H>(
    editor: iced::widget::TextEditor<'static, H, IcedMessage>,
    keydown: std::collections::HashMap<String, IcedMessage>,
    ta_key: &str,
    keymap_mode: &str,
    on_change: Option<IcedMessage>,
) -> iced::widget::TextEditor<'static, H, IcedMessage>
where
    H: iced_widget::core::text::Highlighter,
{
    if keydown.is_empty() && keymap_mode == "emacs" {
        return editor; // 纯默认路径(无声明且默认模式),保持零开销
    }
    if keydown.is_empty() {
        return editor;
    }
    // Plan 057 续(keydown 失焦修复):登记 事件键 → 编辑器 action key,
    // update 里据此为 keydown 派发的 handler 触发重聚焦。
    {
        let mut reg = TEXTAREA_KEYDOWN_TO_EDITOR.lock().unwrap();
        for msg in keydown.values() {
            reg.insert(format!("{}_{}", msg.widget, msg.event), ta_key.to_string());
        }
    }
    // Plan 057 续(行内编辑 keymap):派发优先级 .at onkeydown 声明(App
    // 语义,含 ghost 门控) → 模式键位表(emacs/vi-*) → vi-normal 吞可打印
    // → iced 默认。复合原生操作(kill/yank/transpose)经 le_execute 在
    // Content 上直接执行并合成 on_change 消息同步状态。
    let mode = keymap_mode.to_string();
    let action_key = ta_key.to_string();
    let pending: std::rc::Rc<std::cell::RefCell<Option<&'static str>>> =
        std::rc::Rc::new(std::cell::RefCell::new(None));
    let pending2 = pending.clone();
    editor.key_binding(move |kp| {
        let name = key_press_to_binding_name(&kp);
        // vi pending(d 前缀):dd/dw/db;其他键取消 pending。
        if let Some(pfx) = pending2.borrow_mut().take() {
            if pfx == "d" {
                let op = match name.as_str() {
                    "d" => Some(LineEditOp::Kill(text_editor::Motion::Home)),
                    "w" => Some(LineEditOp::Kill(text_editor::Motion::WordRight)),
                    "b" => Some(LineEditOp::Kill(text_editor::Motion::WordLeft)),
                    _ => None,
                };
                if pfx == "d" && name == "d" {
                    // dd = kill 整行:先 kill 到行首,再 kill 到行尾
                    if let Some(oc) = on_change.as_ref() {
                        let _ = le_execute(&action_key, LineEditOp::Kill(text_editor::Motion::Home), oc);
                        return le_execute(&action_key, LineEditOp::Kill(text_editor::Motion::End), oc);
                    }
                    return Some(text_editor::Binding::Sequence(vec![]));
                }
                if let Some(op) = op {
                    if let Some(oc) = on_change.as_ref() {
                        return le_execute(&action_key, op, oc);
                    }
                }
                return Some(text_editor::Binding::Sequence(vec![]));
            }
        }
        if !name.is_empty() {
            // 1. .at 声明优先
            if let Some(msg) = keydown.get(&name) {
                return Some(text_editor::Binding::Custom(msg.clone()));
            }
            // 2. 模式表
            if let Some(op) = line_edit_keymap(&mode).get(&name).cloned() {
                match op {
                    LineEditOp::Handler => {}
                    LineEditOp::BeginPending => {
                        *pending2.borrow_mut() = Some("d");
                        return Some(text_editor::Binding::Sequence(vec![]));
                    }
                    op => {
                        if let Some(oc) = on_change.as_ref() {
                            if let Some(b) = le_execute(&action_key, op, oc) {
                                return Some(b);
                            }
                        }
                    }
                }
            }
        }
        // 3. vi-normal 兜底:吞掉可打印字符
        if mode == "vi-normal" {
            if let Some(t) = kp.text.as_deref() {
                if t.chars().any(|c| !c.is_control()) {
                    return Some(text_editor::Binding::Sequence(vec![]));
                }
            }
        }
        // 4. iced 默认
        text_editor::Binding::from_key_press(kp)
    })
}

/// Plan 057 续(富文本输入):textarea 的 on_action 事件接线 — Enter 走
/// on_submit(onenter),其余走 on_change(oninput);input_value 经 ghost 剥离。
/// 泛型于 Highlighter,使 PlainText(存量)与 SpanHighlighter(富文本)共用。
fn wire_textarea_actions<H>(
    editor: iced::widget::TextEditor<'static, H, IcedMessage>,
    on_change: Option<IcedMessage>,
    on_submit: Option<IcedMessage>,
) -> iced::Element<'static, IcedMessage>
where
    H: iced_widget::core::text::Highlighter,
{
    // In inspect-capture mode, render read-only (no on_action) so
    // wrap_debug's mouse_area can capture hover/click.
    let on_change = if inspect_capture_active() { None } else { on_change };
    let on_submit = if inspect_capture_active() { None } else { on_submit };
    // Plan 053 M4: Enter fires the on_submit (onenter) handler instead of
    // on_change. Plan 057 续:ghost 嵌入内容,派发前剥离已知后缀。
    let is_enter = |action: &text_editor::Action| {
        matches!(action, text_editor::Action::Edit(text_editor::Edit::Enter))
    };
    if let Some(msg) = on_change {
        let msg_clone = msg.clone();
        let submit_clone = on_submit.clone();
        editor
            .on_action(move |action| {
                let action_key = format!("{}_{}", msg_clone.widget, msg_clone.event);
                if is_enter(&action) {
                    if let Some(sm) = submit_clone.clone() {
                        let text = strip_ghost_suffix(
                            &action_key,
                            &textarea_perform_action(&action_key, action),
                        );
                        IcedMessage {
                            widget: sm.widget.clone(),
                            event: sm.event.clone(),
                            input_value: Some(text),
                        }
                    } else {
                        let text = strip_ghost_suffix(
                            &action_key,
                            &textarea_perform_action(&action_key, action),
                        );
                        IcedMessage {
                            widget: msg_clone.widget.clone(),
                            event: msg_clone.event.clone(),
                            input_value: Some(text),
                        }
                    }
                } else {
                    let text = strip_ghost_suffix(
                        &action_key,
                        &textarea_perform_action(&action_key, action),
                    );
                    IcedMessage {
                        widget: msg_clone.widget.clone(),
                        event: msg_clone.event.clone(),
                        input_value: Some(text),
                    }
                }
            })
            .into()
    } else if let Some(sm) = on_submit {
        let sm_clone = sm.clone();
        let action_key = format!("{}_{}", sm.widget, sm.event);
        editor
            .on_action(move |action| {
                let enter = is_enter(&action);
                let text = strip_ghost_suffix(
                    &action_key,
                    &textarea_perform_action(&action_key, action),
                );
                if enter {
                    IcedMessage {
                        widget: sm_clone.widget.clone(),
                        event: sm_clone.event.clone(),
                        input_value: Some(text),
                    }
                } else {
                    IcedMessage {
                        widget: sm_clone.widget.clone(),
                        event: sm_clone.event.clone(),
                        input_value: Some(text),
                    }
                }
            })
            .into()
    } else {
        editor.into()
    }
}

// ── Plan 057 续(富文本输入):原生着色 textarea ────────────────────────
// 语法着色不再走「透明文字 + 叠加层」,而是 text_editor 原生 Highlighter:
// (text, kind) 连续段 + ghost 建议后缀 → 逐段颜色/字重直接落进编辑器文字。

/// 语义着色段类型 — 对齐 .at DoTokenize 的 kind,外加 Ghost(灰色建议)。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SpanKind {
    Command,
    ExternalCmd,
    String,
    Variable,
    Operator,
    Redirect,
    Comment,
    Flag,
    Whitespace,
    Arg,
    Ghost,
    /// PLAN-493: mention 命中段（textarea mentions 能力）——builder 期
    /// mention_segments 产出 kind "mention"。
    Mention,
    Plain,
}

fn parse_span_kind(kind: &str) -> SpanKind {
    match kind {
        "Command" => SpanKind::Command,
        "ExternalCmd" => SpanKind::ExternalCmd,
        "String" => SpanKind::String,
        "Variable" => SpanKind::Variable,
        "Operator" => SpanKind::Operator,
        "Redirect" => SpanKind::Redirect,
        "Comment" => SpanKind::Comment,
        "Flag" => SpanKind::Flag,
        "Whitespace" => SpanKind::Whitespace,
        "Arg" => SpanKind::Arg,
        "Ghost" => SpanKind::Ghost,
        "mention" => SpanKind::Mention,
        _ => SpanKind::Plain,
    }
}

/// 按行预切的着色段(字节范围已重定位到行内)。Highlighter 的 Settings。
pub type SpanLines = Vec<Vec<(std::ops::Range<usize>, SpanKind)>>;

/// 预计算着色的 Highlighter:lines 全量替换(update 时重置行游标,从行 0
/// 重着色 —— iced_highlighter 的 update 同款约定),highlight_line 顺序消费。
/// Plan 058(着色修复):Settings 携带完整文本参与相等比较。此前仅
/// SpanLines(范围+kind)时,"ls Cargo.toml" 与 "ls Cargo.lock" 的 spans
/// 完全相等(同长度同类型)→ iced settings-diff 判定无变化 → 不调
/// update()/不重置行游标 → cosmic 增量着色跳过变更行 → 残留旧属性
/// (Tab 轮换时 ls 时而普通色的根因)。文本入 Settings 后任何文本变化
/// 都触发 update + 重置,增量契约恢复。
#[derive(Debug, Clone, PartialEq)]
pub struct SpanSettings {
    pub text: String,
    pub lines: SpanLines,
}

pub struct SpanHighlighter {
    lines: SpanLines,
    line_idx: usize,
}

impl iced_widget::core::text::Highlighter for SpanHighlighter {
    type Settings = SpanSettings;
    type Highlight = SpanKind;
    type Iterator<'a> = std::vec::IntoIter<(std::ops::Range<usize>, SpanKind)>;

    fn new(settings: &Self::Settings) -> Self {
        Self { lines: settings.lines.clone(), line_idx: 0 }
    }

    fn update(&mut self, settings: &Self::Settings) {
        // 整体替换 → 重置游标,让增量 highlight 从行 0 重喂。
        self.lines = settings.lines.clone();
        self.line_idx = 0;
    }

    fn change_line(&mut self, line: usize) {
        self.line_idx = line;
    }

    fn highlight_line(&mut self, _line: &str) -> Self::Iterator<'_> {
        let idx = self.line_idx;
        self.line_idx += 1;
        self.lines.get(idx).cloned().unwrap_or_default().into_iter()
    }

    fn current_line(&self) -> usize {
        self.line_idx
    }
}

/// kind → Format(颜色/字重)。调色板对齐 .at 视图层原有的 Tailwind 语义
/// (emerald-400/sky-300/amber-300/red-400/pink-400/gray-400/purple-300)。
fn span_kind_to_format(
    highlight: &SpanKind,
    _theme: &iced::Theme,
) -> iced_widget::core::text::highlighter::Format<iced::Font> {
    let c = |r: u8, g: u8, b: u8| iced::Color::from_rgb8(r, g, b);
    let bold = iced::Font {
        weight: iced::font::Weight::Bold,
        ..iced::Font::DEFAULT
    };
    match highlight {
        SpanKind::Command => iced_widget::core::text::highlighter::Format {
            color: Some(c(52, 211, 153)),   // emerald-400
            font: Some(bold),
        },
        SpanKind::ExternalCmd => iced_widget::core::text::highlighter::Format {
            color: Some(c(125, 211, 252)),  // sky-300
            font: None,
        },
        SpanKind::String => iced_widget::core::text::highlighter::Format {
            color: Some(c(252, 211, 77)),   // amber-300
            font: None,
        },
        SpanKind::Variable => iced_widget::core::text::highlighter::Format {
            color: Some(c(248, 113, 113)),  // red-400
            font: None,
        },
        SpanKind::Operator => iced_widget::core::text::highlighter::Format {
            color: Some(c(244, 114, 182)),  // pink-400
            font: Some(bold),
        },
        SpanKind::Redirect | SpanKind::Comment => iced_widget::core::text::highlighter::Format {
            color: Some(c(156, 163, 175)),  // gray-400
            font: None,
        },
        SpanKind::Flag => iced_widget::core::text::highlighter::Format {
            color: Some(c(216, 180, 254)),  // purple-300
            font: None,
        },
        SpanKind::Ghost => iced_widget::core::text::highlighter::Format {
            // 低饱和半透明灰 — 对齐 vue 的 text-muted-foreground/35。
            color: Some(iced::Color::from_rgba(0.45, 0.48, 0.54, 0.45)),
            font: None,
        },
        SpanKind::Mention => iced_widget::core::text::highlighter::Format {
            // PLAN-493: mention 前景蓝 — 对齐 musk 的
            // text-[hsl(220_90%_56%)]（≈ blue-600）。iced Format 无 per-span
            // 背景，web 侧的 bg tint 不复刻（跨端差异登记）。
            color: Some(c(37, 99, 235)),
            font: None,
        },
        SpanKind::Whitespace | SpanKind::Arg | SpanKind::Plain => {
            iced_widget::core::text::highlighter::Format::default()
        }
    }
}

/// (text, kind) 连续段 + ghost → 按行预切的字节范围段。spans 必须无缝覆盖
/// value(DoTokenize 语义);不满足时返回空(不着色,防错位)。
fn build_span_lines(highlight: &[(String, String)], value: &str, ghost: &str) -> SpanSettings {
    let mut full: Vec<(std::ops::Range<usize>, SpanKind)> = Vec::new();
    let mut concat = String::new();
    let mut off = 0usize;
    for (text, kind) in highlight {
        concat.push_str(text);
        let end = off + text.len();
        if end > off {
            full.push((off..end, parse_span_kind(kind)));
        }
        off = end;
    }
    // 防线:段文本拼接必须恰为 value —— CJK 字节钳制等来源可能造成缺口/重叠。
    if concat != value {
        return SpanSettings { text: String::new(), lines: Vec::new() };
    }
    if !ghost.is_empty() {
        full.push((value.len()..value.len() + ghost.len(), SpanKind::Ghost));
    }
    let content = format!("{}{}", value, ghost);
    // 切行:段跨 \n 时拆成行内片段(Whitespace 段可含续行换行)。
    let mut lines: SpanLines = vec![Vec::new()];
    let mut line_start = 0usize;
    for (r, kind) in full {
        let mut s = r.start;
        while s < r.end {
            match content[s..r.end].find('\n') {
                Some(rel) => {
                    let nl = s + rel;
                    if nl > s {
                        lines.last_mut().unwrap().push((s - line_start..nl - line_start, kind));
                    }
                    lines.push(Vec::new());
                    line_start = nl + 1;
                    s = nl + 1;
                }
                None => {
                    lines.last_mut().unwrap().push((s - line_start..r.end - line_start, kind));
                    s = r.end;
                }
            }
        }
    }
    SpanSettings { text: content, lines }
}

/// Plan 446 批五 U3: textarea 超大内容降级门槛(字节)。
///
/// 现场机理(auto-os-config roles 详情态,§P/U3):sidecar 数据被转义翻倍
/// bug 损坏成 ~1.31M 连续反斜杠进入 textarea(iced `text_editor`)——
/// cosmic-text 对 `-`/`\` 等字形的整形/布局代价约为常观数字的百倍量级
/// (corpus 实测近似线性 ≈60µs/字符:5K≈0.3s / 80K≈5s / 320K≈20s /
/// 655K+ 每帧分钟级),iced 事件循环被单帧渲染永久占用 —— 截图通道 10s
/// 超时只是最显眼症状,实质是整个 UI 冻结。分行/零宽断行符均无效(代价
/// 按字符计,与段落结构无关,corpus `ta_lines`/ZWSP 变体实证)。
///
/// 处方:超过本门槛的 textarea 值不再进编辑器,降级为**只读预览**
/// (`oversized_textarea_preview`:提示行 + 截断快照)。无编辑器即无
/// onchange 回流 —— store 原值完整保留,不存在截断落盘风险;正常尺寸
/// (<64KB)的编辑路径零变化。阈值取 64KB:现场健康 sidecar 为 KB 量级,
/// 误伤面可忽略。
const TEXTAREA_INLINE_EDIT_CAP: usize = 64 * 1024;

/// 预览快照展示的头部长度(字符)。只读预览是"看",不是"编"——完整内容
/// 始终在 store,外部编辑器工作流不受影响。
const TEXTAREA_PREVIEW_HEAD_CHARS: usize = 32 * 1024;

/// 判定 textarea 值是否超过内联编辑门槛(降级只读预览)。
pub(crate) fn textarea_needs_preview(value: &str) -> bool {
    value.len() > TEXTAREA_INLINE_EDIT_CAP
}

/// 超大 textarea 值的只读预览:提示行 + 截断快照(Plan 446 批五 U3)。
/// 泛型于消息类型:纯展示元素,不携带任何事件。
pub(crate) fn oversized_textarea_preview<M: Clone + std::fmt::Debug + 'static>(
    value: &str,
) -> iced::Element<'static, M> {
    let total_chars = value.chars().count();
    let head: String = value.chars().take(TEXTAREA_PREVIEW_HEAD_CHARS).collect();
    let hint = format!(
        "(autoui) value too large for inline editing ({} chars / {} bytes) — read-only preview of the first {} chars; full value is preserved in state.",
        total_chars,
        value.len(),
        TEXTAREA_PREVIEW_HEAD_CHARS
    );
    // 预览文本必须 Fill 宽度:text 默认 Shrink,其 min 宽 = 最长不可断行
    // (病态数据即百万像素),会把宿主行整体挤出窗口(实测主区只剩标题)。
    iced::widget::column![
        iced::widget::text(hint).size(11).width(iced::Length::Fill),
        iced::widget::text(head).width(iced::Length::Fill),
    ]
    .width(iced::Length::Fill)
    .into()
}

/// Get or create a `&'static text_editor::Content` for the given key, synced to `value`.
fn get_textarea_content(key: &str, value: &str) -> &'static text_editor::Content {
    // Phase 1: ensure the entry exists (under lock)
    {
        let mut map = TEXTAREA_CONTENTS.lock().unwrap();
        map.entry(key.to_string()).or_insert_with(|| {
            Box::leak(Box::new(text_editor::Content::with_text(value)))
        });
    }
    // Phase 2: update content in-place (under lock) — ONLY when the text
    // actually changed. Unconditionally replacing on every render reset the
    // cursor to offset 0 each frame, so every freshly typed character was
    // inserted at the START of the line (typing "ls" showed "sl").
    // When the value did change (e.g. handler wrote state), rebuild and park
    // the caret at the document end — the sane default for programmatic sets.
    {
        let mut map = TEXTAREA_CONTENTS.lock().unwrap();
        if let Some(content) = map.get_mut(key) {
            if content.text() != value {
                **content = text_editor::Content::with_text(value);
                content.perform(text_editor::Action::Move(
                    text_editor::Motion::DocumentEnd,
                ));
            }
        }
    }
    // Phase 3: get a raw pointer under lock, return as &'static outside lock.
    // SAFETY: The Box is leaked so the allocation lives for 'static.
    // We only mutate under the Mutex. The raw pointer is derived from
    // a &'static mut that came from Box::leak, so it remains valid.
    let ptr: *const text_editor::Content;
    {
        let map = TEXTAREA_CONTENTS.lock().unwrap();
        ptr = map.get(key).map(|c| &**c as *const _).unwrap();
    }
    // SAFETY: ptr points to a leaked Box that lives for 'static.
    unsafe { &*ptr }
}

/// Perform an action on a textarea content and return the resulting text.
fn textarea_perform_action(key: &str, action: text_editor::Action) -> String {
    let mut map = TEXTAREA_CONTENTS.lock().unwrap();
    if let Some(content) = map.get_mut(key) {
        content.perform(action);
        content.text()
    } else {
        String::new()
    }
}

// ── Plan 057 续(富文本输入):ghost 嵌入内容 + 编辑事件剥离 ────────────

/// 每个 textarea key 当前嵌入的 ghost 后缀(渲染时写入,编辑派发时读)。
lazy_static::lazy_static! {
    static ref TEXTAREA_GHOSTS: Mutex<std::collections::HashMap<String, String>> =
        Mutex::new(std::collections::HashMap::new());
    /// Plan 057 续(Ctrl+F 光标修复):每个 key 上次渲染的 (value, ghost)。
    /// 拼接文本相同但 (value,ghost) 边界移动时(如 Ctrl+F 接受全部 ghost:
    /// "ec"+"ho…" → "echo…"+""),content 文本不变但光标必须重定位到新
    /// input 末尾 —— 树位移重置的编辑器状态也会被全量重建纠正。
    static ref TEXTAREA_LAST_INPUT: Mutex<std::collections::HashMap<String, (String, String)>> =
        Mutex::new(std::collections::HashMap::new());
}

/// 富文本版内容缓存:content = value + ghost(ghost 经 Highlighter 染灰)。
/// value 或 ghost 变化才重建;重建后光标置于 **value 末尾**(DocumentEnd 再
/// 回退 ghost 字符数),避免后续键入落到 ghost 之后。
fn get_textarea_content_rich(key: &str, value: &str, ghost: &str) -> &'static text_editor::Content {
    {
        let mut map = TEXTAREA_CONTENTS.lock().unwrap();
        map.entry(key.to_string())
            .or_insert_with(|| Box::leak(Box::new(text_editor::Content::with_text(value))));
    }
    {
        let mut ghosts = TEXTAREA_GHOSTS.lock().unwrap();
        ghosts.insert(key.to_string(), ghost.to_string());
    }
    {
        let mut map = TEXTAREA_CONTENTS.lock().unwrap();
        let want = format!("{}{}", value, ghost);
        // Plan 057 续(Ctrl+F 光标修复):重建条件从「拼接文本变化」放宽为
        // 「(value, ghost) 变化」。Ctrl+F 接受全部 ghost 后拼接文本不变,
        // 但 input/ghost 边界移动了 —— 不重建的话光标停在旧 input 末尾
        // (或树位移重置后的行首),而期望在完整 input 末尾。
        let boundary_moved = {
            let mut last = TEXTAREA_LAST_INPUT.lock().unwrap();
            let moved = last.get(key).map(|(v, g)| v != value || g != ghost).unwrap_or(true);
            last.insert(key.to_string(), (value.to_string(), ghost.to_string()));
            moved
        };
        if let Some(content) = map.get_mut(key) {
            if content.text() != want || boundary_moved {
                // Plan 057 续(行内编辑):echo 重建(编辑器自身编辑/移动引起)
                // 保持光标字节偏移(编辑点,钳回 value 区);外部变更(历史/
                // 补全/ghost 接受)维持 value 末尾 —— C-b 后打字不再被拽尾。
                let echo = TEXTAREA_ECHO_KEYS.lock().unwrap().remove(key);
                let preserve = if echo { Some(le_cursor_offset(content)) } else { None };
                **content = text_editor::Content::with_text(&want);
                match preserve {
                    Some(off) => {
                        le_move_to_offset(content, &want, off.min(value.len()));
                    }
                    None => {
                        content.perform(text_editor::Action::Move(
                            text_editor::Motion::DocumentEnd,
                        ));
                        for _ in 0..ghost.chars().count() {
                            content.perform(text_editor::Action::Move(
                                text_editor::Motion::Left,
                            ));
                        }
                    }
                }
            }
        }
    }
    let ptr: *const text_editor::Content;
    {
        let map = TEXTAREA_CONTENTS.lock().unwrap();
        ptr = map.get(key).map(|c| &**c as *const _).unwrap();
    }
    // SAFETY: 同 get_textarea_content —— Box::leak 的 'static 分配,仅锁内变更。
    unsafe { &*ptr }
}

/// 编辑事件剥离:新内容若以本编辑器已知 ghost 后缀结尾 → 剥掉;否则(用户
/// 改写/选中覆盖了 ghost)整段视为真实输入,ghost 由状态重算自愈。
fn strip_ghost_suffix(key: &str, text: &str) -> String {
    let ghosts = TEXTAREA_GHOSTS.lock().unwrap();
    if let Some(g) = ghosts.get(key) {
        if !g.is_empty() && text.len() >= g.len() && text.ends_with(g.as_str()) {
            return text[..text.len() - g.len()].to_string();
        }
    }
    text.to_string()
}

/// Retrieve the last input text value captured by an Input's on_input callback.
/// Called from generated Component::on() handlers to read user input.
pub fn last_input_text() -> String {
    INPUT_TEXT.with(|t| t.borrow().clone())
}

/// Trait for converting abstract View<M> into Iced Element
///
/// This trait enables rendering the abstract view tree using the Iced framework
/// with full style support through IcedStyle.
pub trait IntoIcedElement<M: Clone + Debug + 'static> {
    /// Convert abstract view into Iced Element
    fn into_iced(self) -> iced::Element<'static, M>;
}

/// Mutable class access for the style-carrying View variants — used by the
/// Row/Column dispatch points to apply axis-aware fixes BEFORE children
/// recurse into `into_iced`/`render_dynamic_view` (from_style has no parent
/// context, so the axis must be resolved at the dispatch site; see the
/// Row/Column arms). Variants not listed here keep the legacy behaviour.
fn view_classes_mut<M: Clone + Debug>(v: &mut AbstractView<M>) -> Option<&mut Vec<StyleClass>> {
    use AbstractView as V;
    match v {
        V::Row { style: Some(s), .. }
        | V::Column { style: Some(s), .. }
        | V::Text { style: Some(s), .. }
        | V::Button { style: Some(s), .. }
        | V::Input { style: Some(s), .. }
        | V::Textarea { style: Some(s), .. }
        | V::CodeEditor { style: Some(s), .. }
        | V::Image { style: Some(s), .. } => Some(&mut s.classes),
        _ => None,
    }
}

/// 横向主轴(Row 直接子)修正:剥 FlexCol,阻断 from_style 的"FlexCol→补
/// height=Fill"猜测(横向 Shrink row 里该 Fill 无界可填 → 整卡塌 0)。
pub(crate) fn axis_fix_row_child<M: Clone + Debug>(mut c: AbstractView<M>) -> AbstractView<M> {
    if let Some(classes) = view_classes_mut(&mut c) {
        classes.retain(|cl| !matches!(cl, StyleClass::FlexCol));
    }
    c
}

/// 纵向主轴(Column 直接子)修正:flex-1 是 CSS flex-grow 的主轴(纵向)
/// 语义 → 转写为显式 Height(Full);原先被误设的 width=Fill 一并撤除
/// (col 子项的 flex-1 本就不该撑宽)。
pub(crate) fn axis_fix_col_child<M: Clone + Debug>(mut c: AbstractView<M>) -> AbstractView<M> {
    if let Some(classes) = view_classes_mut(&mut c) {
        let mut has_grow = false;
        classes.retain(|cl| match cl {
            StyleClass::Flex1 | StyleClass::FlexAuto | StyleClass::Grow => {
                has_grow = true;
                false
            }
            _ => true,
        });
        if has_grow && !classes.iter().any(|cl| matches!(cl, StyleClass::Height(_))) {
            classes.push(StyleClass::Height(SizeValue::Full));
        }
    }
    c
}

/// Helper to compute effective spacing: style.gap takes priority, then legacy spacing.
/// Plan 412: axis-aware — Row consumes gap-x (axis-specific wins over bare gap),
/// Column consumes gap-y. The other axis is ignored, mirroring CSS grid/flex semantics.
fn effective_spacing(legacy: u16, style: Option<&Style>, horizontal: bool) -> f32 {
    if let Some(s) = style {
        let iced_style = IcedStyle::from_style(s);
        let axis = if horizontal { iced_style.gap_x } else { iced_style.gap_y };
        if let Some(g) = axis.or(iced_style.gap) {
            return g;
        }
    }
    legacy as f32
}

/// Compute iced Padding (per-axis) from style, falling back to legacy u16.
/// Handles px/py separately from uniform padding.
fn iced_padding_from_is(is: &IcedStyle, legacy: u16) -> iced::Padding {
    // Uniform padding
    if let Some(p) = is.padding {
        return iced::Padding::new(p);
    }
    // Per-axis or per-side padding
    let has_per_side = is.padding_top.is_some() || is.padding_bottom.is_some()
        || is.padding_left.is_some() || is.padding_right.is_some();
    if has_per_side || is.padding_x.is_some() || is.padding_y.is_some() {
        let px = is.padding_x.unwrap_or(0.0);
        let py = is.padding_y.unwrap_or(0.0);
        let top = is.padding_top.or(if py > 0.0 { Some(py) } else { None }).unwrap_or(0.0);
        let bottom = is.padding_bottom.or(if py > 0.0 { Some(py) } else { None }).unwrap_or(0.0);
        let left = is.padding_left.or(if px > 0.0 { Some(px) } else { None }).unwrap_or(0.0);
        let right = is.padding_right.or(if px > 0.0 { Some(px) } else { None }).unwrap_or(0.0);
        return iced::Padding {
            top,
            bottom,
            left,
            right,
        };
    }
    iced::Padding::new(legacy as f32)
}

fn iced_padding(legacy: u16, style: Option<&Style>) -> iced::Padding {
    if let Some(s) = style {
        let is = IcedStyle::from_style(s);
        return iced_padding_from_is(&is, legacy);
    }
    iced::Padding::new(legacy as f32)
}

/// Build an Iced container::Style from IcedStyle, covering background, border, shadow, text_color.
fn build_container_style(is: &IcedStyle) -> iced::widget::container::Style {
    use iced::Background;
    let has_radius = is.has_border_radius();
    let border = if is.rounded || is.border || has_radius || is.border_width.map_or(false, |w| w > 0.0) {
        let width = is.border_width.unwrap_or(if is.border { 1.0 } else { 0.0 });
        let color = is.border_color.unwrap_or_else(|| {
            let (r, g, b) = crate::ui::style::iced_adapter::resolve_border_rgb();
            iced::Color::from_rgb8(r, g, b)
        });
        iced::Border {
            color: if width > 0.0 { color } else { iced::Color::TRANSPARENT },
            width,
            radius: is.effective_border_radius(),
        }
    } else {
        iced::Border::default()
    };
    let shadow = if is.shadow {
        let (offset_y, blur) = match is.shadow_size {
            Some(IcedShadowSize::Sm) => (1.0, 2.0),
            Some(IcedShadowSize::Md) => (2.0, 4.0),
            Some(IcedShadowSize::Lg) => (4.0, 8.0),
            Some(IcedShadowSize::Xl) => (8.0, 16.0),
            Some(IcedShadowSize::Xxl) => (12.0, 24.0),
            _ => (2.0, 4.0),
        };
        iced::Shadow {
            // Plan 527 T4: shadow-{color} 彩色阴影 —— 保留默认阴影 alpha(0.15),
            // 只替换色相(对齐 Tailwind 彩色阴影 = color × 默认阴影透明度)。
            color: {
                let (sr, sg, sb) = is
                    .shadow_color
                    .map(|c| (c.r, c.g, c.b))
                    .unwrap_or((0.0, 0.0, 0.0));
                iced::Color::from_rgba(sr, sg, sb, 0.15)
            },
            offset: iced::Vector::new(0.0, offset_y),
            blur_radius: blur,
        }
    } else {
        iced::Shadow::default()
    };
    // Build background: use gradient if both from/to colors present, else solid
    let background = if is.gradient_from.is_some() && is.gradient_to.is_some() {
        let from = is.gradient_from.unwrap();
        let to = is.gradient_to.unwrap();
        let angle = match is.gradient_dir {
            Some(crate::ui::style::GradientDir::ToB) | None => 180.0_f32.to_radians(),
            Some(crate::ui::style::GradientDir::ToT) => 0.0,
            Some(crate::ui::style::GradientDir::ToR) => 90.0_f32.to_radians(),
            Some(crate::ui::style::GradientDir::ToL) => 270.0_f32.to_radians(),
            Some(crate::ui::style::GradientDir::ToBR) => 135.0_f32.to_radians(),
            Some(crate::ui::style::GradientDir::ToBL) => 225.0_f32.to_radians(),
            Some(crate::ui::style::GradientDir::ToTR) => 45.0_f32.to_radians(),
            Some(crate::ui::style::GradientDir::ToTL) => 315.0_f32.to_radians(),
        };
        use iced::gradient::Linear;
        // Plan 527 T4: from/via/to 多 stop + 位置百分比(默认 0/50/100)——
        // iced 0.14 Linear::add_stop 任意 offset,via 缺席时保持双 stop 旧观感。
        let mut lin = Linear::new(angle)
            .add_stop(is.gradient_from_pos.unwrap_or(0.0), from);
        if let Some(via) = is.gradient_via {
            lin = lin.add_stop(is.gradient_via_pos.unwrap_or(0.5), via);
        }
        Some(Background::Gradient(
            lin.add_stop(is.gradient_to_pos.unwrap_or(1.0), to).into()
        ))
    } else {
        is.background_color.map(Background::Color)
    };
    iced::widget::container::Style {
        background,
        text_color: is.text_color,
        border,
        shadow,
        ..Default::default()
    }
}

/// Build an Iced button::Style from IcedStyle.
/// Plan 409 §10 续 20: 简单代码语法高亮(auto/vue/bash 通用)→ 着色 Span 列表。
/// tokenizer:comment / string / number+boolean / keyword / function / operator / punct / ident。
///
/// 2026-08-22(show 下沉):扫描逻辑与色板移至 vm::shell_bridge::highlight_rgb
/// —— auto.shell.emit_show 的 Code payload 与本处 font-mono 自动高亮共用一份
/// 实现,避免两份漂移。None = 默认前景色(color_maybe)。
///
/// Plan 442 A6: a known lang (codeblock 的 lang-<token> class)改走 syntect
/// highlight-only API——与 code_editor 同引擎同主题(musk-038 T16 决策 (a));
/// 无 lang 的 mono 文本保持共享手写 tokenizer(shell show payload 等)。
fn highlight_code(code: &str, lang: Option<&str>) -> Vec<iced::widget::text::Span<'static, ()>> {
    use iced::widget::text::Span;
    let colored: Vec<(String, Option<(u8, u8, u8)>)> = match lang {
        Some(l) if !l.is_empty() => {
            let (dark, accent) = crate::ui::code_editor::theme::theme_source();
            crate::ui::code_editor::core::highlight::highlight_segments(l, code, dark, &accent)
        }
        _ => crate::vm::shell_bridge::highlight_rgb(code),
    };
    colored
        .into_iter()
        .map(|(text, rgb)| {
            let mut sp = Span::new(text);
            if let Some((r, g, b)) = rgb {
                sp = sp.color(iced::Color::from_rgb8(r, g, b));
            }
            sp
        })
        .collect()
}

/// Plan 411 P2-A④: 表头单元格样式——font-medium + text-muted-foreground
/// (vue 侧 `<th class="font-medium text-muted-foreground">`)。递归下钻到
/// Text 视图追加 class;表头可能是 Row/Container 包裹的复合内容。
fn apply_table_header_style<M: Clone + Debug>(v: &mut AbstractView<M>) {
    match v {
        AbstractView::Text { style, .. } => {
            let st = style.get_or_insert_with(Default::default);
            st.classes.push(StyleClass::FontMedium);
            st.classes.push(StyleClass::TextColor(Color::OnSurface));
        }
        AbstractView::Row { children, .. } | AbstractView::Column { children, .. } => {
            for c in children {
                apply_table_header_style(c);
            }
        }
        AbstractView::Container { child, .. } | AbstractView::Scrollable { child, .. } => {
            apply_table_header_style(child);
        }
        _ => {}
    }
}

/// Plan 411 P2-A④: 单元格 px-4/py-3 padding(vue `<td class="px-4 py-3">`)。
/// Plan 045 T2: `width` Some 时容器定宽（Fixed(w)）——列宽应用的落点；
/// None 维持 Shrink 自然宽（现状）。
fn table_cell_container<'a, M: 'static>(
    el: iced::Element<'a, M>,
    width: Option<f32>,
) -> iced::Element<'a, M> {
    let mut c = iced::widget::container(el).padding(iced::Padding {
        top: 12.0,
        bottom: 12.0,
        left: 16.0,
        right: 16.0,
    });
    if let Some(w) = width {
        c = c.width(iced::Length::Fixed(w));
    }
    c.into()
}

/// Plan 045 T2: 列宽两态分派纯函数——`col_widths` Some 且列号在范围内返回
/// 固定宽（px）；None 或长度不足的尾列返回 None（自然宽）。超列数的尾值
/// 无消费方（自然截断）。表头与体行走同一分派。
fn col_fixed_width(col_widths: Option<&[f32]>, col: usize) -> Option<f32> {
    col_widths.and_then(|ws| ws.get(col).copied())
}

/// Plan 411 P2-A④: 行 border-b——iced 容器边框是四边整圈,单侧下边线用
/// 1px 填充分隔条子元素模拟(vue `border-b border-border`)。
fn table_row_rule<M: 'static>() -> iced::Element<'static, M> {
    let (r, g, b) = crate::ui::style::iced_adapter::resolve_border_rgb();
    iced::widget::container(
        iced::widget::Space::new()
            .width(iced::Length::Shrink)
            .height(iced::Length::Fixed(0.0),
        ))
        .width(iced::Length::Fill)
        .height(iced::Length::Fixed(1.0))
        .style(move |_| iced::widget::container::Style {
            background: Some(iced::Background::Color(iced::Color::from_rgb8(r, g, b))),
            ..Default::default()
        })
        .into()
}

/// Plan-050 C1: content-subtree 按钮的内容对齐决策——web flex 语义到 iced
/// 容器对齐的最小映射（仅消费四界面布局用到的组合；未命中返回 None = 维持
/// iced Button 默认内容居中）。justify-content 优先于 text-align（前者是
/// 布局声明，后者是文本对齐兜底）。
fn plan050_content_align(
    is: Option<&IcedStyle>,
) -> (
    Option<iced::alignment::Horizontal>,
    Option<iced::alignment::Vertical>,
) {
    use iced::alignment::{Horizontal, Vertical};
    let Some(is) = is else { return (None, None) };
    let h = match is.justify_content {
        Some(crate::ui::style::iced_adapter::IcedJustify::Start) => Some(Horizontal::Left),
        Some(crate::ui::style::iced_adapter::IcedJustify::End) => Some(Horizontal::Right),
        Some(crate::ui::style::iced_adapter::IcedJustify::Center) => Some(Horizontal::Center),
        _ => is.text_align.map(|a| match a {
            crate::ui::style::iced_adapter::IcedTextAlign::Left => Horizontal::Left,
            crate::ui::style::iced_adapter::IcedTextAlign::Center => Horizontal::Center,
            crate::ui::style::iced_adapter::IcedTextAlign::Right => Horizontal::Right,
        }),
    };
    let v = is.align_items.map(|a| match a {
        crate::ui::style::iced_adapter::IcedAlign::Start => Vertical::Top,
        crate::ui::style::iced_adapter::IcedAlign::Center => Vertical::Center,
        crate::ui::style::iced_adapter::IcedAlign::End => Vertical::Bottom,
    });
    (h, v)
}

/// Plan 409/414 高度臂 × Plan-050 显式对齐类的让位规则:按钮带高度类时
/// 其内容容器默认双向居中(CSS button 语义);样式串携带显式对齐类
/// (text-left/justify-*、items-*)的轴以显式值为准——否则 050 的外层
/// 包装包不住已 Fill 的内层容器,nav-item(h-9 w-full text-left)内容
/// 恒居中而 web 轨左对齐,双端漂移。
fn plan414_content_alignment(
    p050_ax: Option<iced::alignment::Horizontal>,
    p050_ay: Option<iced::alignment::Vertical>,
) -> (iced::alignment::Horizontal, iced::alignment::Vertical) {
    use iced::alignment::{Horizontal, Vertical};
    (
        p050_ax.unwrap_or(Horizontal::Center),
        p050_ay.unwrap_or(Vertical::Center),
    )
}

/// PLAN-050 P2 #3: mt-auto（MarginTop(Auto)）在 iced 无 margin-auto 几何——
/// Column 发射时在该子项前方插一根 Fill 高度占位条，恢复 web 侧"推到底部"
/// 语义。判定独立成函数钉住契约：mt-auto 经 master 通用 mt-<size> 路径解析，
/// 曾有专用变体被通用路径打死的前科，此函数是回归防线。
fn plan050_mt_auto_spacer(classes: &[StyleClass]) -> bool {
    classes.iter().any(|x| matches!(x, StyleClass::MarginTop(SizeValue::Auto)))
}

fn build_button_style(is: &IcedStyle) -> iced::widget::button::Style {
    use iced::Background;
    let has_radius = is.has_border_radius();
    let border = if is.rounded || is.border || has_radius || is.border_width.map_or(false, |w| w > 0.0) {
        let width = is.border_width.unwrap_or(if is.border { 1.0 } else { 0.0 });
        let color = is.border_color.unwrap_or_else(|| {
            let (r, g, b) = crate::ui::style::iced_adapter::resolve_border_rgb();
            iced::Color::from_rgb8(r, g, b)
        });
        iced::Border {
            color: if width > 0.0 { color } else { iced::Color::TRANSPARENT },
            width,
            radius: is.effective_border_radius(),
        }
    } else {
        iced::Border::default()
    };
    let shadow = if is.shadow {
        let (offset_y, blur) = match is.shadow_size {
            Some(IcedShadowSize::Sm) => (1.0, 2.0),
            Some(IcedShadowSize::Md) => (2.0, 4.0),
            Some(IcedShadowSize::Lg) => (4.0, 8.0),
            Some(IcedShadowSize::Xl) => (8.0, 16.0),
            Some(IcedShadowSize::Xxl) => (12.0, 24.0),
            _ => (2.0, 4.0),
        };
        iced::Shadow {
            // Plan 527 T4: shadow-{color} 彩色阴影 —— 保留默认阴影 alpha(0.15),
            // 只替换色相(对齐 Tailwind 彩色阴影 = color × 默认阴影透明度)。
            color: {
                let (sr, sg, sb) = is
                    .shadow_color
                    .map(|c| (c.r, c.g, c.b))
                    .unwrap_or((0.0, 0.0, 0.0));
                iced::Color::from_rgba(sr, sg, sb, 0.15)
            },
            offset: iced::Vector::new(0.0, offset_y),
            blur_radius: blur,
        }
    } else {
        iced::Shadow::default()
    };
    // Plan 527 T6: opacity-{N} —— iced 无元素级 opacity 组,按钮面降级为
    // 背景/文字 alpha 乘以倍率(visible 而非静默;disabled:opacity-50 等
    // 变体类经 merged_with_variant 到此消费)。
    let opacity = is.opacity.unwrap_or(1.0);
    let fade = |c: iced::Color| iced::Color { a: c.a * opacity, ..c };
    iced::widget::button::Style {
        background: is.background_color.map(|c| Background::Color(fade(c))),
        text_color: fade(is.text_color.unwrap_or_else(|| {
            // Plan 408: dark-mode-aware default (equivalent to vue body text-foreground).
            crate::ui::style::iced_adapter::resolve_semantic_rgb(
                &crate::ui::style::Color::OnBackground,
            ).map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
             .unwrap_or(iced::Color::BLACK)
        })),
        border,
        shadow,
        ..Default::default()
    }
}

/// Check if an IcedStyle has visual properties that need container wrapping.
fn needs_visual_wrap(is: &IcedStyle) -> bool {
    is.background_color.is_some()
        || is.border
        || is.rounded
        || is.has_border_radius()
        || is.shadow
        || is.text_color.is_some()
}

/// Convert IcedFontWeight to iced::Font.
/// Plan 411 P1-C: Inter 字体内嵌——对齐 vue 栈字体族 `Inter, system-ui...`。
/// Inter 以 SIL OFL 1.1 发布(全文见 assets/INTER-OFL.txt),静态三字重
/// regular/medium/semibold 打进二进制;中文字形由 cosmic-text 回退系统字体。
pub const INTER_FONT_REGULAR: &[u8] = include_bytes!("assets/Inter-Regular.ttf");
pub const INTER_FONT_MEDIUM: &[u8] = include_bytes!("assets/Inter-Medium.ttf");
pub const INTER_FONT_SEMIBOLD: &[u8] = include_bytes!("assets/Inter-SemiBold.ttf");

/// Plan 518：随包内嵌默认壁纸(脚本自制,免授权——生成器 scratch/p518)。
/// `builtin:` 虚拟方案经 load_image_bytes 消费;ricepaper = 默认
/// (stella 权威图同款暖米宣纸底),inkwash = 宣纸+水墨远山可选项
/// (设置壁纸栏键入 `builtin:inkwash`)。深浅主题共用浅色——stella dark
/// 实证壁纸与主题解耦。
pub const WALLPAPER_RICEPAPER: &[u8] = include_bytes!("assets/wallpaper-ricepaper.jpg");
pub const WALLPAPER_INKWASH: &[u8] = include_bytes!("assets/wallpaper-inkwash.jpg");

/// Inter family 引用 —— application 的 `.default_font` 与带字重文本共用。
pub const INTER_FONT: iced::Font = iced::Font {
    family: iced::font::Family::Name("Inter"),
    ..iced::Font::DEFAULT
};

fn font_weight_to_iced(weight: &IcedFontWeight) -> iced::Font {
    // Plan 411 P1-C: 带字重的文本钉住 Inter family,内嵌三字重才会真正
    // 被选中(Medium 此前近似映射 Semibold,内嵌后恢复正身);bold/light
    // 超出内嵌字重由 cosmic-text 合成/回退。
    match weight {
        IcedFontWeight::Bold => iced::Font { family: INTER_FONT.family, weight: iced::font::Weight::Bold, ..Default::default() },
        IcedFontWeight::Medium => iced::Font { family: INTER_FONT.family, weight: iced::font::Weight::Medium, ..Default::default() },
        IcedFontWeight::Normal => INTER_FONT,
        IcedFontWeight::Light => iced::Font { family: INTER_FONT.family, weight: iced::font::Weight::Light, ..Default::default() },
        IcedFontWeight::ExtraLight => iced::Font { family: INTER_FONT.family, weight: iced::font::Weight::Thin, ..Default::default() },
        IcedFontWeight::SemiBold => iced::Font { family: INTER_FONT.family, weight: iced::font::Weight::Semibold, ..Default::default() },
        // Plan 527 T5: 全字重档拆分(thin/extrabold/black 正身)
        IcedFontWeight::Thin => iced::Font { family: INTER_FONT.family, weight: iced::font::Weight::Thin, ..Default::default() },
        IcedFontWeight::ExtraBold => iced::Font { family: INTER_FONT.family, weight: iced::font::Weight::ExtraBold, ..Default::default() },
        IcedFontWeight::Black => iced::Font { family: INTER_FONT.family, weight: iced::font::Weight::Black, ..Default::default() },
    }
}

/// Wrap an iced element with external spacing for margin simulation.
/// Handles:
/// - `margin_top` (mt-*): external top spacing via container padding
/// - `margin_bottom` (mb-*): external bottom spacing via container padding
///   (Plan 448 对齐批: 此前被静默丢弃,VM 标题 mb-6 不生效导致与 vue 间距分歧)
/// - `margin_left` (ml-*): external left spacing via container padding
/// - `margin_right` (mr-*): external right spacing via container padding
/// - `mx-auto` (both flags): container fills remaining width, content centered
/// - `ml-auto` alone: container fills remaining width, content pushed right
/// - `mr-auto` alone: container fills remaining width, content pushed left
fn wrap_with_margin<M: Clone + Debug + 'static>(
    el: iced::Element<'static, M>,
    is: &IcedStyle,
) -> iced::Element<'static, M> {
    use iced::widget::container;
    let top = is.margin_top.unwrap_or(0.0);
    let bottom = is.margin_bottom.unwrap_or(0.0);
    let left = is.margin_left.unwrap_or(0.0);
    let right = is.margin_right.unwrap_or(0.0);
    let needs_wrap = top != 0.0 || bottom != 0.0 || left != 0.0 || right != 0.0
        || is.margin_left_auto || is.margin_right_auto;
    if !needs_wrap {
        return el;
    }
    let mut cont = container(el);
    if top != 0.0 || bottom != 0.0 || left != 0.0 || right != 0.0 {
        cont = cont.padding(iced::Padding {
            top,
            right,
            bottom,
            left,
        });
    }
    if is.margin_left_auto && is.margin_right_auto {
        // mx-auto: center horizontally
        cont = cont.width(iced::Length::Fill).center_x(iced::Length::Fill);
    } else if is.margin_left_auto {
        // ml-auto: push content to the right
        cont = cont.width(iced::Length::Fill).align_x(iced::alignment::Horizontal::Right);
    } else if is.margin_right_auto {
        // mr-auto: push content to the left
        cont = cont.width(iced::Length::Fill).align_x(iced::alignment::Horizontal::Left);
    }
    cont.into()
}

// ============================================================================
// Shared style helpers for Column, Row, Container
// ============================================================================
// These functions unify the styling/container-wrapping logic that was previously
// duplicated between IntoIcedElement::into_iced() and render_dynamic_view().
// Both paths call these helpers after rendering children their own way.

/// Apply style properties to a Column widget and optionally wrap in a Container
/// for visual styles (background, border) or vertical alignment (justify).
///
/// Takes a column with spacing set and children already pushed.
/// Returns the final styled element (possibly wrapped in container).
fn apply_column_style<M: Clone + Debug + 'static>(
    col: iced::widget::Column<'static, M>,
    padding: u16,
    style: Option<&Style>,
    widget_id: Option<String>,
) -> iced::Element<'static, M> {
    let iced_style = style.map(|s| IcedStyle::from_style(s));
    let has_visual = iced_style.as_ref().map_or(false, |is| needs_visual_wrap(is));
    let pd = iced_padding(padding, style);

    // Apply width/height/alignment to column
    let mut justify_center = false;
    let mut justify_end = false;
    let mut col = col;
    if let Some(ref is) = iced_style {
        // Width
        if let Some(ref w) = is.width {
            col = col.width(iced_length(w));
        }
        if let Some(mw) = is.max_width {
            if is.width.is_none() {
                col = col.width(iced::Length::Fill);
            }
            col = col.max_width(mw);
        }
        // Height — skip when justify needs it on container instead
        let needs_v_align = matches!(is.justify_content, Some(IcedJustify::Center | IcedJustify::End));
        if !needs_v_align {
            if let Some(ref h) = is.height {
                col = col.height(iced_length(h));
            } else if let Some(mh) = is.min_height {
                // min-h-screen (marker 9999.0) → Fill; other px values → Fixed
                if mh >= 9999.0 {
                    col = col.height(iced::Length::Fill);
                } else {
                    col = col.height(iced::Length::Fixed(mh));
                }
            }
        }
        // Alignment
        if let Some(ref a) = is.align_items {
            col = col.align_x(iced_alignment_horizontal(*a));
        }
        // Justify tracking
        if let Some(ref j) = is.justify_content {
            match j {
                IcedJustify::Center => justify_center = true,
                IcedJustify::End => justify_end = true,
                _ => {}
            }
        }
    }

    let col_max_width = iced_style.as_ref().and_then(|is| is.max_width);
    let needs_wrap = justify_center || justify_end || has_visual;
    let mt = iced_style.as_ref().and_then(|is| is.margin_top).unwrap_or(0.0);
    let mb = iced_style.as_ref().and_then(|is| is.margin_bottom).unwrap_or(0.0);
    let ml = iced_style.as_ref().and_then(|is| is.margin_left).unwrap_or(0.0);
    let mr = iced_style.as_ref().and_then(|is| is.margin_right).unwrap_or(0.0);
    let needs_margin_wrap = mt != 0.0 || mb != 0.0 || ml != 0.0 || mr != 0.0
        || iced_style.as_ref().map_or(false, |is| is.margin_left_auto || is.margin_right_auto);

    let el = if needs_wrap {
        let mut cont = container(col);
        cont = cont.padding(pd);
        if justify_center {
            let col_w = if let Some(ref is) = iced_style {
                if let Some(ref w) = is.width {
                    iced_length(w)
                } else {
                    iced::Length::Fill
                }
            } else {
                iced::Length::Fill
            };
            let col_h = if let Some(ref is) = iced_style {
                if let Some(ref h) = is.height {
                    iced_length(h)
                } else {
                    iced::Length::Fill
                }
            } else {
                iced::Length::Fill
            };
            cont = cont.width(col_w).height(col_h).center_y(col_h);
        } else if justify_end {
            let col_w = if let Some(ref is) = iced_style {
                if let Some(ref w) = is.width {
                    iced_length(w)
                } else {
                    iced::Length::Fill
                }
            } else {
                iced::Length::Fill
            };
            let col_h = if let Some(ref is) = iced_style {
                if let Some(ref h) = is.height {
                    iced_length(h)
                } else {
                    iced::Length::Fill
                }
            } else {
                iced::Length::Fill
            };
            cont = cont.width(col_w).height(col_h).align_y(iced::alignment::Vertical::Bottom);
        } else {
            // Non-justify wrap: propagate column's width and height to container
            if let Some(ref is) = iced_style {
                // PLAN-055: self-end 列的视觉容器抱合——CSS 里 flex 子项
                // align-self:flex-end 时收缩到内容宽并靠交叉轴末端。此前
                // visual-wrap 容器无条件 Fill（块级语义），chat 气泡
                // （bg-primary + self-end）被拉成全宽紫条、右对齐失效。
                // End → Shrink+align_x(Right)；Start/Center 同理；
                // 无 align_self 维持块级 Fill（AI 消息 hairline 全宽不回归）。
                match is.align_self {
                    Some(crate::ui::style::iced_adapter::IcedAlign::End) => {
                        cont = cont.width(iced::Length::Shrink)
                            .align_x(iced::alignment::Horizontal::Right);
                    }
                    Some(crate::ui::style::iced_adapter::IcedAlign::Start) => {
                        cont = cont.width(iced::Length::Shrink)
                            .align_x(iced::alignment::Horizontal::Left);
                    }
                    Some(crate::ui::style::iced_adapter::IcedAlign::Center) => {
                        cont = cont.width(iced::Length::Shrink)
                            .align_x(iced::alignment::Horizontal::Center);
                    }
                    _ => {
                        let col_width_fill = matches!(is.width, Some(IcedSize::Full | IcedSize::FillPortion(_)))
                            || is.width.is_none();
                        if col_width_fill { cont = cont.width(iced::Length::Fill); }
                        let col_height_fill = matches!(is.height, Some(IcedSize::Full | IcedSize::FillPortion(_)))
                            || is.min_height.map_or(false, |mh| mh >= 9999.0);
                        if col_height_fill { cont = cont.height(iced::Length::Fill); }
                        if let Some(mw) = is.max_width { cont = cont.max_width(mw); }
                    }
                }
            }
        }
        // Apply visual styles (background, border, rounded, shadow)
        if let Some(ref is) = iced_style {
            if has_visual {
                let cs = build_container_style(is);
                cont = cont.style(move |_| cs);
            } else if let Some(bg) = is.background_color {
                cont = cont.style(move |_| container::Style {
                    background: Some(iced::Background::Color(bg)),
                    ..Default::default()
                });
            }
        }
        if let Some(id) = widget_id { cont = cont.id(id); }
        cont.into()
    } else if col_max_width.is_some() {
        let mut cont = container(col.padding(pd));
        if let Some(ref is) = iced_style {
            let col_width_fill = matches!(is.width, Some(IcedSize::Full | IcedSize::FillPortion(_)))
                || is.width.is_none();
            if col_width_fill { cont = cont.width(iced::Length::Fill); }
            let col_height_fill = matches!(is.height, Some(IcedSize::Full | IcedSize::FillPortion(_)))
                || is.min_height.map_or(false, |mh| mh >= 9999.0);
            if col_height_fill { cont = cont.height(iced::Length::Fill); }
        }
        if let Some(mw) = col_max_width { cont = cont.max_width(mw); }
        if let Some(id) = widget_id { cont = cont.id(id); }
        cont.into()
    } else if let Some(id) = widget_id {
        // G4e (411 P2-B #1): plain (unstyled) columns dropped the widget
        // id, so the layout collector never saw them. Wrap in a
        // layout-transparent container carrying the id (container()
        // with no modifiers is a pass-through in iced layout).
        container(col.padding(pd)).id(id).into()
    } else {
        col.padding(pd).into()
    };

    if needs_margin_wrap {
        let mut cont = container(el);
        if mt != 0.0 || mb != 0.0 || ml != 0.0 || mr != 0.0 {
            cont = cont.padding(iced::Padding { top: mt, right: mr, bottom: mb, left: ml });
        }
        // Handle mx-auto / ml-auto / mr-auto
        if let Some(ref is) = iced_style {
            if is.margin_left_auto && is.margin_right_auto {
                cont = cont.width(iced::Length::Fill).center_x(iced::Length::Fill);
            } else if is.margin_left_auto {
                cont = cont.width(iced::Length::Fill).align_x(iced::alignment::Horizontal::Right);
            } else if is.margin_right_auto {
                cont = cont.width(iced::Length::Fill).align_x(iced::alignment::Horizontal::Left);
            }
        }
        cont.into()
    } else {
        el
    }
}

/// Emulate CSS `justify-content` on an iced Row, which has no native main-axis
/// justification. Returns `(leading, between, trailing)` spacer weights telling
/// the row builder where to inject `Space`-with-FillPortion spacers. Layout is
/// left-to-right, so Fill spacers compete for — and split — the row's
/// remaining width by portion weight:
///   start   → none
///   end     → leading spacer pushes children to the right edge
///   center  → leading + trailing spacers flank the children (equal halves)
///   between → a spacer between each adjacent pair spreads them out
///   around  → edges get half a gap, pairs a full gap: lead/trail=1, between=2
///             (with n children the total weight is 2+2(n-1)=2n → each unit is
///             W/(2n) so lead = W/(2n) = d/2 and between = W/n = d — exactly
///             CSS space-around)
///   evenly  → n+1 equal spacers including both edges → each = W/(n+1) = d
///             (exactly CSS space-evenly)
fn row_justify_spacers(j: Option<IcedJustify>) -> (Option<u16>, Option<u16>, Option<u16>) {
    match j {
        Some(IcedJustify::Center) => (Some(1), None, Some(1)),
        Some(IcedJustify::End) => (Some(1), None, None),
        Some(IcedJustify::Between) => (None, Some(1), None),
        Some(IcedJustify::Around) => (Some(1), Some(2), Some(1)),
        Some(IcedJustify::Evenly) => (Some(1), Some(1), Some(1)),
        _ => (None, None, None), // Start / None
    }
}

/// Apply style properties to a Row widget and optionally wrap in a Container
/// for visual styles (background, border).
fn apply_row_style<M: Clone + Debug + 'static>(
    row: iced::widget::Row<'static, M>,
    padding: u16,
    style: Option<&Style>,
    widget_id: Option<String>,
) -> iced::Element<'static, M> {
    let iced_style = style.map(|s| IcedStyle::from_style(s));
    let has_visual = iced_style.as_ref().map_or(false, |is| needs_visual_wrap(is));
    let pd = iced_padding(padding, style);
    let row_max_width = iced_style.as_ref().and_then(|is| is.max_width);

    // Apply width and alignment to row
    let mut r = row;
    if let Some(ref is) = iced_style {
        if let Some(ref w) = is.width {
            r = r.width(iced_length(w));
        } else if is.justify_content.is_some() {
            // justify-content only has effect with a defined main-axis size;
            // the Fill-spacer emulation needs room to distribute.
            r = r.width(iced::Length::Fill);
        }
        if let Some(ref h) = is.height {
            r = r.height(iced_length(h));
        }
        if let Some(ref a) = is.align_items {
            r = r.align_y(iced_alignment_vertical(*a));
        }
    }

    let el = if has_visual {
        let mut cont = container(r);
        cont = cont.padding(pd);
        // Propagate row's width/height to wrapping container
        if let Some(ref is) = iced_style {
            let row_width_fill = matches!(is.width, Some(IcedSize::Full | IcedSize::FillPortion(_)));
            if row_width_fill { cont = cont.width(iced::Length::Fill); }
            let row_height_fill = matches!(is.height, Some(IcedSize::Full | IcedSize::FillPortion(_)));
            if row_height_fill { cont = cont.height(iced::Length::Fill); }
        }
        if let Some(mw) = row_max_width { cont = cont.max_width(mw); }
        if let Some(ref is) = iced_style {
            let cs = build_container_style(is);
            cont = cont.style(move |_| cs);
        }
        if let Some(id) = widget_id { cont = cont.id(id); }
        cont.into()
    } else if row_max_width.is_some() {
        r = r.padding(pd);
        let mut cont = container(r);
        // Propagate row's width/height to wrapping container
        if let Some(ref is) = iced_style {
            let row_width_fill = matches!(is.width, Some(IcedSize::Full | IcedSize::FillPortion(_)));
            if row_width_fill { cont = cont.width(iced::Length::Fill); }
            let row_height_fill = matches!(is.height, Some(IcedSize::Full | IcedSize::FillPortion(_)));
            if row_height_fill { cont = cont.height(iced::Length::Fill); }
        }
        if let Some(mw) = row_max_width { cont = cont.max_width(mw); }
        if let Some(id) = widget_id { cont = cont.id(id); }
        cont.into()
    } else if let Some(id) = widget_id {
        // G4e: same as apply_column_style — keep the id on plain rows.
        container(r.padding(pd)).id(id).into()
    } else {
        r.padding(pd).into()
    };

    // Apply external margin_top/margin_bottom and mx-auto/ml-auto/mr-auto
    let mt = iced_style.as_ref().and_then(|is| is.margin_top).unwrap_or(0.0);
    let mb = iced_style.as_ref().and_then(|is| is.margin_bottom).unwrap_or(0.0);
    let ml = iced_style.as_ref().and_then(|is| is.margin_left).unwrap_or(0.0);
    let mr = iced_style.as_ref().and_then(|is| is.margin_right).unwrap_or(0.0);
    let needs_margin_wrap = mt != 0.0 || mb != 0.0 || ml != 0.0 || mr != 0.0
        || iced_style.as_ref().map_or(false, |is| is.margin_left_auto || is.margin_right_auto);
    if needs_margin_wrap {
        let mut cont = container(el);
        if mt != 0.0 || mb != 0.0 || ml != 0.0 || mr != 0.0 {
            cont = cont.padding(iced::Padding { top: mt, right: mr, bottom: mb, left: ml });
        }
        if let Some(ref is) = iced_style {
            if is.margin_left_auto && is.margin_right_auto {
                cont = cont.width(iced::Length::Fill).center_x(iced::Length::Fill);
            } else if is.margin_left_auto {
                cont = cont.width(iced::Length::Fill).align_x(iced::alignment::Horizontal::Right);
            } else if is.margin_right_auto {
                cont = cont.width(iced::Length::Fill).align_x(iced::alignment::Horizontal::Left);
            }
        }
        cont.into()
    } else {
        el
    }
}

/// Apply style properties to a Container widget (width, height, centering, visual styles).
fn apply_container_style<M: Clone + Debug + 'static>(
    mut cont: iced::widget::Container<'static, M>,
    padding: u16,
    width: Option<u16>,
    height: Option<u16>,
    center_x: bool,
    center_y: bool,
    style: Option<&Style>,
    widget_id: Option<String>,
) -> iced::Element<'static, M> {
    cont = cont.padding(iced_padding(padding, style));

    if let Some(ref s) = style {
        let is = IcedStyle::from_style(s);

        if center_x || center_y {
            // When centering, the container must fill its parent so it has room
            // to center the content. We apply width/height from style to this
            // container directly (not to a nested inner container).
            if center_x {
                match is.width {
                    Some(ref ws) => { cont = cont.width(iced_length(ws)); }
                    None => { cont = cont.width(iced::Length::Fill); }
                }
                if let Some(mw) = is.max_width { cont = cont.max_width(mw); }
                cont = cont.align_x(iced::alignment::Horizontal::Center);
            } else {
                if let Some(ref ws) = is.width {
                    cont = cont.width(iced_length(ws));
                } else if let Some(w) = width {
                    if w > 0 { cont = cont.width(iced::Length::Fixed(w as f32)); }
                }
                if let Some(mw) = is.max_width { cont = cont.max_width(mw); }
            }

            if center_y {
                match is.height {
                    Some(ref h) => { cont = cont.height(iced_length(h)); }
                    None => { cont = cont.height(iced::Length::Fill); }
                }
                if let Some(mh) = is.max_height { cont = cont.max_height(mh); }
                cont = cont.align_y(iced::alignment::Vertical::Center);
            } else {
                match is.height {
                    Some(ref h) => { cont = cont.height(iced_length(h)); }
                    None => { if let Some(h) = height { if h > 0 { cont = cont.height(iced::Length::Fixed(h as f32)); } } }
                }
                if let Some(mh) = is.max_height { cont = cont.max_height(mh); }
            }
        } else {
            // Normal (non-centered) container
            if let Some(ref ws) = is.width {
                cont = cont.width(iced_length(ws));
            } else if let Some(w) = width {
                if w > 0 { cont = cont.width(iced::Length::Fixed(w as f32)); }
            } else if let Some(mw) = is.min_width {
                // PLAN-051 P2-④: min-w 消费（语义近似=Fixed 下限——内容更宽
                // 时 iced 不再撑大,自滚/截断场景正确;登记）。沿 Column 臂
                // 1524 同款：min-h-screen 哨兵(9999.0) → Fill。
                cont = cont.width(if mw >= 9999.0 {
                    iced::Length::Fill
                } else {
                    iced::Length::Fixed(mw)
                });
            }
            match is.height {
                Some(ref h) => { cont = cont.height(iced_length(h)); }
                None => {
                    if let Some(h) = height {
                        if h > 0 { cont = cont.height(iced::Length::Fixed(h as f32)); }
                    } else if let Some(mh) = is.min_height {
                        // PLAN-051 P2-④: min-h 消费——musk input-compose 的
                        // min-h-20 此前被丢 → 输入框容器高度塌 0。
                        cont = cont.height(if mh >= 9999.0 {
                            iced::Length::Fill
                        } else {
                            iced::Length::Fixed(mh)
                        });
                    }
                }
            }
            if let Some(mw) = is.max_width { cont = cont.max_width(mw); }
            if let Some(mh) = is.max_height { cont = cont.max_height(mh); }
        }

        // Visual styles (background, border, rounded, shadow)
        if needs_visual_wrap(&is) {
            let cs = build_container_style(&is);
            cont = cont.style(move |_| cs);
        }
    } else {
        if let Some(w) = width { if w > 0 { cont = cont.width(iced::Length::Fixed(w as f32)); } }
        if let Some(h) = height { if h > 0 { cont = cont.height(iced::Length::Fixed(h as f32)); } }

        // No style but centering requested — fill parent and align center
        if center_x { cont = cont.width(iced::Length::Fill).align_x(iced::alignment::Horizontal::Center); }
        if center_y { cont = cont.height(iced::Length::Fill).align_y(iced::alignment::Vertical::Center); }
    }

    if let Some(id) = widget_id {
        cont.id(id).into()
    } else {
        cont.into()
    }
}

// ─────────────────────────────────────────────────────────────────────────
// Shared generic widget builders (Plan 319 — unify VM/Rust rendering).
//
// These sit one layer above the `apply_*_style` helpers: they take
// **already-built** child `Element`s and own the widget *shape* — spacing,
// padding, justify-spacers, width/height, children loop. Both converters
// (`into_iced`, generic `M`, rust mode; `render_dynamic_view`, IcedMessage,
// VM mode) call the *same* builder, so the shape can never drift between
// modes again. The converters differ only in HOW they produce the child
// elements: `into_iced` recurses via `child.into_iced()`, while
// `render_dynamic_view` recurses via itself (to give each child its own
// `wrap_debug` instrumentation + VM text capture). The builder is agnostic
// to that — it just arranges whatever children it's handed.
// ─────────────────────────────────────────────────────────────────────────

/// Build a Row from pre-built child elements, applying justify-spacers and
/// the shared `apply_row_style` (width/height/margin/visual wrap + id).
/// Plan 412: flex-row-reverse flips children; items-stretch wraps each child
/// in a height-Fill container (iced has no cross-axis stretch alignment).
/// Plan-050 T4/C2: 单侧边框的 1px 填充条模拟——推广 table_row_rule 先例
/// （iced 容器边框四边整圈,无法单侧;按类串 border-b/t/l/r 在对应方向拼一条
/// border-border 色 1px 线）。无单侧边框类时原样返回。
fn apply_side_borders<M: Clone + Debug + 'static>(
    el: iced::Element<'static, M>,
    is: Option<&IcedStyle>,
) -> iced::Element<'static, M> {
    let Some(is) = is else { return el };
    if !(is.border_bottom || is.border_top || is.border_left || is.border_right) {
        return el;
    }
    let border_col = is.border_color.unwrap_or_else(|| {
        let (r, g, b) = crate::ui::style::iced_adapter::resolve_border_rgb();
        iced::Color::from_rgb8(r, g, b)
    });
    let border_w = is.border_width.unwrap_or(1.0);
    let line_style = move |_: &_| iced::widget::container::Style {
        background: Some(iced::Background::Color(border_col)),
        ..Default::default()
    };
    let hline = move || -> iced::Element<'static, M> {
        iced::widget::container(
            iced::widget::Space::new()
                .width(iced::Length::Fill)
                .height(iced::Length::Fixed(0.0)),
        )
        .width(iced::Length::Fill)
        .height(iced::Length::Fixed(border_w))
        .style(line_style)
        .into()
    };
    let vline = move || -> iced::Element<'static, M> {
        iced::widget::container(
            iced::widget::Space::new()
                .width(iced::Length::Fixed(0.0))
                .height(iced::Length::Fill),
        )
        .width(iced::Length::Fixed(border_w))
        .height(iced::Length::Fill)
        .style(line_style)
        .into()
    };
    let mut el = el;
    if is.border_top {
        el = iced::widget::Column::with_children(vec![hline(), el])
            .width(iced::Length::Fill)
            .into();
    }
    if is.border_bottom {
        el = iced::widget::Column::with_children(vec![el, hline()])
            .width(iced::Length::Fill)
            .into();
    }
    if is.border_left {
        el = iced::widget::Row::with_children(vec![vline(), el])
            .height(iced::Length::Fill)
            .into();
    }
    if is.border_right {
        el = iced::widget::Row::with_children(vec![el, vline()])
            .height(iced::Length::Fill)
            .into();
    }
    el
}

fn build_row<M: Clone + Debug + 'static>(
    mut children: Vec<iced::Element<'static, M>>,
    spacing: u16,
    padding: u16,
    style: Option<&Style>,
    widget_id: Option<String>,
) -> iced::Element<'static, M> {
    let eff_spacing = effective_spacing(spacing, style, true);
    let iced_style = style.map(|s| IcedStyle::from_style(s));
    let justify = iced_style.as_ref().and_then(|is| is.justify_content);
    if iced_style.as_ref().map_or(false, |is| is.row_reverse) {
        children.reverse();
    }
    let (lead, between, trail) = row_justify_spacers(justify);
    let spacer = |portion: u16| {
        iced::widget::Space::new()
                            .width(iced::Length::FillPortion(portion))
    };
    let mut row_widget = row([]).spacing(eff_spacing);
    if let Some(p) = lead {
        row_widget = row_widget.push(spacer(p));
    }
    let stretch = iced_style.as_ref().map_or(false, |is| is.items_stretch);
    let mut first = true;
    for child in children {
        if let Some(p) = between {
            if !first {
                row_widget = row_widget.push(spacer(p));
            }
        }
        first = false;
        let child = if stretch {
            container(child).height(iced::Length::Fill).into()
        } else {
            child
        };
        row_widget = row_widget.push(child);
    }
    if let Some(p) = trail {
        row_widget = row_widget.push(spacer(p));
    }
    apply_side_borders(apply_row_style(row_widget, padding, style, widget_id), iced_style.as_ref())
}

/// Build a Column from pre-built child elements + shared `apply_column_style`.
/// Plan 412: flex-col-reverse flips children; items-stretch wraps each child
/// in a width-Fill container; justify-between/around/evenly get vertical
/// Fill spacers (mirroring build_row's spacer emulation; Center/End keep the
/// container-wrap path inside apply_column_style).
fn build_column<M: Clone + Debug + 'static>(
    mut children: Vec<iced::Element<'static, M>>,
    spacing: u16,
    padding: u16,
    style: Option<&Style>,
    widget_id: Option<String>,
) -> iced::Element<'static, M> {
    let eff_spacing = effective_spacing(spacing, style, false);
    let iced_style = style.map(|s| IcedStyle::from_style(s));
    if iced_style.as_ref().map_or(false, |is| is.col_reverse) {
        children.reverse();
    }
    let justify = iced_style.as_ref().and_then(|is| is.justify_content);
    let distributed = matches!(
        justify,
        Some(IcedJustify::Between | IcedJustify::Around | IcedJustify::Evenly)
    );
    let stretch = iced_style.as_ref().map_or(false, |is| is.items_stretch);
    // PLAN-054 T4 (A6): items-end —— 列交叉轴(横向)右对齐:每个子项包进
    // Fill+align_x(End) 容器(iced 列无子项对齐;musk 用户消息列
    // `items-end` 此前被静默丢弃,气泡与 header 贴左)。仅 End 臂新增,
    // Start/Center 维持既有(忽略)行为,零回归面。
    let align_end = iced_style
        .as_ref()
        .map_or(false, |is| is.align_items == Some(crate::ui::style::iced_adapter::IcedAlign::End));
    let spacer = |portion: u16| {
        iced::widget::Space::new()
                            .height(iced::Length::FillPortion(portion))
    };
    let mut col_widget = column([]).spacing(eff_spacing);
    let mut first = true;
    for child in children {
        if distributed {
            if let Some(p) = match justify {
                Some(IcedJustify::Between) if !first => Some(1),
                Some(IcedJustify::Around) => Some(if first { 1 } else { 2 }),
                Some(IcedJustify::Evenly) => Some(1),
                _ => None,
            } {
                col_widget = col_widget.push(spacer(p));
            }
        }
        first = false;
        let child = if stretch {
            container(child).width(iced::Length::Fill).into()
        } else if align_end {
            container(child)
                .width(iced::Length::Fill)
                .align_x(iced::alignment::Horizontal::Right)
                .into()
        } else {
            child
        };
        col_widget = col_widget.push(child);
    }
    if distributed {
        // Trailing spacer for around (half gap) and evenly (full gap);
        // between has no edge spacers.
        match justify {
            Some(IcedJustify::Around) | Some(IcedJustify::Evenly) => {
                col_widget = col_widget.push(spacer(1));
            }
            _ => {}
        }
    }
    // Plan 057 续(块高度修复):删除 build_column 尾部的 max-h → Fixed(N) 限高
    // Scrollable 包裹。它曾让短内容也占满 N 高(用户反馈的"空 block 半页空白"),
    // 且与 view builder 的 needs_scroll(overflow-y-auto → View::Scrollable →
    // build_scrollable 的 Shrink + Container::max_height 封顶)形成双重包裹:
    // 内层 col 同样携带 max-h 样式,此处再包 Fixed(N) 把 intrinsic 钉死在 N,
    // 外层 Shrink 解析为 min(N, N) = N,Shrink 封顶完全失效。max-h 现在统一由
    // build_scrollable 的 cap 分支处理(CSS max-height 语义)。
    apply_side_borders(apply_column_style(col_widget, padding, style, widget_id), iced_style.as_ref())
}

/// Build a Container around a single pre-built child + shared
/// `apply_container_style`.
fn build_container<M: Clone + Debug + 'static>(
    child: iced::Element<'static, M>,
    padding: u16,
    width: Option<u16>,
    height: Option<u16>,
    center_x: bool,
    center_y: bool,
    style: Option<&Style>,
    widget_id: Option<String>,
) -> iced::Element<'static, M> {
    let cont = container(child);
    let iced_style = style.map(IcedStyle::from_style);
    apply_side_borders(
        apply_container_style(cont, padding, width, height, center_x, center_y, style, widget_id),
        iced_style.as_ref(),
    )
}

/// Plan 043 T1: Scrollable offset 绑定写入的 pending 队列。
///
/// build 面（view→element）无法返回 iced Task，写入请求先在此登记，
/// update 面（`update_inner` 尾部）排空并发射 `operation::scroll_to`——
/// devtools.pending_scroll_to_center 同款「pending + update 排空」先例。
/// 去抖：仅当绑定值与该 id 上次请求值之差超 0.5px 才入队，同帧重复 build /
/// 无变化重渲染不重复触发。键 = scrollable widget id（写入要求稳定 id）。
struct PendingScrollOffsetEntry {
    last_requested: (f32, f32),
    pending: Option<(f32, f32)>,
}

fn pending_scroll_offsets() -> &'static std::sync::Mutex<std::collections::HashMap<String, PendingScrollOffsetEntry>> {
    static REG: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<String, PendingScrollOffsetEntry>>> =
        std::sync::OnceLock::new();
    REG.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

/// build 面登记：绑定值变化（>0.5px）才入队。
pub(crate) fn note_scroll_offset(id: &str, offset: (f32, f32)) {
    let mut reg = pending_scroll_offsets().lock().unwrap();
    let entry = reg.entry(id.to_string()).or_insert(PendingScrollOffsetEntry {
        last_requested: offset,
        pending: Some(offset),
    });
    let (dx, dy) = (offset.0 - entry.last_requested.0, offset.1 - entry.last_requested.1);
    if dx.abs() > 0.5 || dy.abs() > 0.5 {
        entry.last_requested = offset;
        entry.pending = Some(offset);
    }
}

/// update 面排空：取走全部待写入项（id → 绝对像素偏移）。
pub(crate) fn drain_pending_scroll_offsets() -> Vec<(String, (f32, f32))> {
    let mut reg = pending_scroll_offsets().lock().unwrap();
    reg.iter_mut()
        .filter_map(|(id, e)| e.pending.take().map(|off| (id.clone(), off)))
        .collect()
}

/// Build a Scrollable around a single pre-built child. Width/height come
/// from style (preferred) or the legacy numeric fields; id is set when the
/// caller supplies one (VM path injects the aura id for bounds collection).
/// Plan 043 T1: offset/on_scroll 为滚动位置写入/读出双臂——写入经 pending
/// 队列（要求 widget_id 稳定），读出经 iced on_scroll 事件回调。
fn build_scrollable<M: Clone + Debug + 'static>(
    child: iced::Element<'static, M>,
    width: Option<u16>,
    height: Option<u16>,
    style: Option<&Style>,
    widget_id: Option<String>,
    offset: Option<(f32, f32)>,
    on_scroll: Option<crate::ui::view::ScrollCallback<M>>,
) -> iced::Element<'static, M> {
    if let (Some(id), Some(off)) = (&widget_id, offset) {
        if std::env::var("P043_DEBUG").is_ok() {
            eprintln!("[P043-NOTE] id={id} off={off:?}");
        }
        note_scroll_offset(id, off);
    }
    let mut cap: Option<f32> = None;
    let mut s = scrollable(child);
    if let Some(cb) = on_scroll {
        // Viewport 六测量 → ScrollMetrics → 宿主消息（DSL 侧三测量
        // scrollTop/scrollHeight/clientHeight 对应 offset_y/content_h/viewport_h）。
        s = s.on_scroll(move |vp: scrollable::Viewport| {
            let abs = vp.absolute_offset();
            let b = vp.bounds();
            let cbounds = vp.content_bounds();
            cb.call(crate::ui::view::ScrollMetrics {
                offset_x: abs.x,
                offset_y: abs.y,
                viewport_w: b.width,
                viewport_h: b.height,
                content_w: cbounds.width,
                content_h: cbounds.height,
            })
        });
    }
    if let Some(ref st) = style {
        let is = IcedStyle::from_style(st);
        // 2026-08-22(max-h 封顶修复):cap 判定从 is.height 的 None 分支
        // 提出,与 height 推断解耦 —— from_style 对 `w-full + overflow-y`
        // 会推断 height=Fill("竖向填充意图"),旧逻辑只在没有 height 时才
        // 封顶,于是 max-h-[400px] 的代码块长到内容高(实测 3058px)、内部
        // 滚动永不出现。CSS max-height 语义:有 cap 一律 Shrink +
        // Container::max_height 封顶(短内容收缩、长内容滚动),显式
        // h-*/Fill 让位。
        if let Some(mh) = is.max_height {
            if mh > 0.0 {
                cap = Some(mh);
            }
        }
        if let Some(ref ws) = is.width {
            match ws {
                IcedSize::Fixed(f) => s = s.width(iced::Length::Fixed(*f as f32)),
                IcedSize::Full => s = s.width(iced::Length::Fill),
                IcedSize::FillPortion(n) => s = s.width(iced::Length::FillPortion(*n)),
            }
        } else if let Some(w) = width {
            if w > 0 { s = s.width(iced::Length::Fixed(w as f32)); }
        }
        match is.height {
            Some(IcedSize::Fixed(f)) => {
                if cap.is_none() { s = s.height(iced::Length::Fixed(f as f32)); }
            }
            Some(IcedSize::Full) => {
                if cap.is_none() { s = s.height(iced::Length::Fill); }
            }
            Some(IcedSize::FillPortion(n)) => {
                if cap.is_none() { s = s.height(iced::Length::FillPortion(n)); }
            }
            None => {
                if cap.is_none() {
                    if let Some(h) = height {
                        if h > 0 { s = s.height(iced::Length::Fixed(h as f32)); }
                    }
                }
            }
        }
    } else {
        if let Some(w) = width { if w > 0 { s = s.width(iced::Length::Fixed(w as f32)); } }
        if let Some(h) = height { if h > 0 { s = s.height(iced::Length::Fixed(h as f32)); } }
    }
    // Plan 409 §10 续 4: 半透明悬浮滚动条(接近 vue:thumb 半透明、track 透明、细)。
    s = s.style(|_theme: &iced::Theme, _status: scrollable::Status| scrollbar_style());
    if let Some(id) = widget_id {
        s = s.id(id);
    }
    if let Some(max_h) = cap {
        let shrink = s.height(iced::Length::Shrink);
        return iced::widget::container(shrink)
            .max_height(max_h)
            .width(iced::Length::Fill)
            .into();
    }
    s.into()
}

/// Plan 409 §10 续 4: vue 风格滚动条 — thumb 半透明、track 透明、细圆角。
fn scrollbar_style() -> scrollable::Style {
    let border = iced::Border {
        width: 0.0,
        radius: iced::border::Radius::new(3.0),
        color: iced::Color::TRANSPARENT,
    };
    let thumb = iced::Background::Color(iced::Color::from_rgba(0.9, 0.9, 0.9, 0.3));
    let rail = scrollable::Rail {
        background: None,
        border,
        scroller: scrollable::Scroller { background: thumb, border },
    };
    scrollable::Style {
        container: container::Style::default(),
        vertical_rail: rail,
        horizontal_rail: rail,
        gap: None,
        auto_scroll: scrollable::AutoScroll {
            background: iced::Background::Color(iced::Color::TRANSPARENT),
            border,
            shadow: iced::Shadow::default(),
            icon: iced::Color::TRANSPARENT,
        },
    }
}

/// Plan 483: text_input 的稳定唯一 Id 派生。主键 = on_change 的
/// widget+event(`.at` 单一真源中静态稳定、跨重建不变、同参输入亦互异);
/// 无主键时退 placeholder+width+password 三元组(泛型路径,与旧行为持平)。
/// 取代「全窗固定 prompt_input」——iced `Focus` operation 对**所有**同 Id
/// 的 focusable 逐个置焦(focusable.rs),共享 Id 即一次聚焦全置焦:
/// 未捕获 Tab→__focus_prompt / __focus_input / refocus 等路径任一触发,
/// 多 input 视图即双焦点+键盘双投递(上游 auto-musk 011)。
fn derive_input_id(
    primary: Option<(&str, &str)>,
    placeholder: &str,
    width: Option<u16>,
    password: bool,
) -> iced::widget::Id {
    match primary {
        Some((widget, event)) => format!("auto_input_{}_{}", widget, event).into(),
        None => format!("auto_input_{}_{}_{}", placeholder, width.unwrap_or(0), password).into(),
    }
}

/// Build a `TextInput` shape: placeholder, value, and width. The width logic
/// follows the (formerly VM-mode) `render_dynamic_view` semantics as the
/// canonical single source — style width wins (Full→Fill, Fixed→Fixed), else
/// the legacy numeric `width`, else Shrink. The caller still wires
/// `on_input`/`on_submit`, since text-capture wiring is inherently mode-
/// specific (generic `M` vs `IcedMessage`).
fn build_input_shape<M: Clone + Debug + 'static>(
    placeholder: &str,
    value: &str,
    width: Option<u16>,
    password: bool,
    style: Option<&Style>,
) -> iced::widget::TextInput<'static, M> {
    let mut input_widget = text_input(placeholder, value);
    // PLAN-050/483: 无显式 Id 的 text_input 在同视图多输入场景共享编辑器
    // 状态。泛型路径(无 widget+event 主键可取)以 placeholder+width+
    // password 三元组派生稳定 Id;VM 主路径在 render_dynamic_view 以
    // widget+event 主键再派生(见 derive_input_id)。
    input_widget = input_widget.id(derive_input_id(None, placeholder, width, password));
    if password {
        input_widget = input_widget.secure(true);
    }
    let default_style = Style::parse("border rounded-md px-3 py-2 text-sm").ok();
    let effective_style = style.or(default_style.as_ref());
    if let Some(s) = effective_style {
        let iced_style = IcedStyle::from_style(s);
        let effective_width = iced_style.width
            .map(|w| match w {
                IcedSize::Fixed(f) => Some(f as u16),
                IcedSize::Full => None,
                IcedSize::FillPortion(_) => None,
            })
            .unwrap_or(width);
        if let Some(w) = effective_width {
            if w > 0 {
                input_widget = input_widget.width(iced::Length::Fixed(w as f32));
            }
        }
        if let Some(ref w) = iced_style.width {
            if matches!(w, IcedSize::Full) && width.is_none() {
                input_widget = input_widget.width(iced::Length::Fill);
            }
        }
        // Size / typography
        if let Some(fs) = effective_font_size(&iced_style) {
            input_widget = input_widget.size(fs);
        } else {
            input_widget = input_widget.size(14.0);
        }
        // Padding
        if let Some(pad) = iced_style.padding {
            input_widget = input_widget.padding(pad);
        } else if iced_style.padding_x.is_some() || iced_style.padding_y.is_some() {
            let px = iced_style.padding_x.unwrap_or(12.0);
            let py = iced_style.padding_y.unwrap_or(8.0);
            input_widget = input_widget.padding(iced::Padding {
                top: py,
                right: px,
                bottom: py,
                left: px,
            });
        } else {
            input_widget = input_widget.padding(iced::Padding {
                top: 8.0,
                right: 12.0,
                bottom: 8.0,
                left: 12.0,
            });
        }

        let bg = iced_style.background_color.unwrap_or(iced::Color::TRANSPARENT);
        let border_color = iced_style.border_color.unwrap_or_else(|| {
            let (r, g, b) = crate::ui::style::iced_adapter::resolve_border_rgb();
            iced::Color::from_rgb8(r, g, b)
        });
        let border_width = iced_style.border_width.unwrap_or(if iced_style.border { 1.0 } else { 1.0 });
        let radius = iced_style.border_radius.unwrap_or(6.0);
        let value_color = iced_style.text_color.unwrap_or_else(|| {
            crate::ui::style::iced_adapter::resolve_semantic_rgb(
                &crate::ui::style::Color::OnBackground,
            ).map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
             .unwrap_or(iced::Color::WHITE)
        });
        let placeholder_color = crate::ui::style::iced_adapter::resolve_semantic_rgb(
            &crate::ui::style::Color::OnSurface,
        ).map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
         .unwrap_or(iced::Color::from_rgba(0.6, 0.6, 0.6, 0.7));

        let focus_border_color = crate::ui::style::iced_adapter::resolve_semantic_rgb(
            &crate::ui::style::Color::Primary,
        ).map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
         .unwrap_or(iced::Color::from_rgb8(59, 130, 246));
        let focus_border_width = (border_width + 1.0).max(2.0);

        input_widget = input_widget.style(move |_theme, status| {
            let is_focused = matches!(status, iced::widget::text_input::Status::Focused { .. });
            let active_border_color = if is_focused {
                focus_border_color
            } else if border_width > 0.0 {
                border_color
            } else {
                iced::Color::TRANSPARENT
            };
            let active_border_width = if is_focused {
                focus_border_width
            } else {
                border_width
            };
            iced::widget::text_input::Style {
                background: iced::Background::Color(bg),
                border: iced::Border {
                    color: active_border_color,
                    width: active_border_width,
                    radius: radius.into(),
                },
                icon: iced::Color::TRANSPARENT,
                placeholder: placeholder_color,
                value: value_color,
                selection: iced::Color::from_rgba(0.3, 0.5, 0.9, 0.4),
            }
        });
    } else if let Some(w) = width {
        if w > 0 {
            input_widget = input_widget.width(iced::Length::Fixed(w as f32));
        }
    }
    input_widget
}

/// Plan 409 §10 续 5: Overlay 浮层定位 —— Fill 宽 + 水平对齐(right/left)+
/// top spacer(top offset)。content 自带 style(bg-popover/border/shadow)。
fn build_floating_layer<M: Clone + Debug + 'static>(
    content: iced::Element<'static, M>,
    position: crate::ui::view::OverlayPosition,
) -> iced::Element<'static, M> {
    let mut col = iced::widget::Column::<M>::with_capacity(2);
    if let Some(top) = position.top {
        if top > 0.0 {
            col = col.push(iced::widget::Space::new().height(iced::Length::Fixed(top)));
        }
    }
    let mut cont = container(content);
    if let Some(right) = position.right {
        cont = cont
            .width(iced::Length::Fill)
            .align_x(iced::alignment::Horizontal::Right)
            .padding(iced::Padding { top: 0.0, right, bottom: 0.0, left: 0.0 });
    } else if let Some(left) = position.left {
        cont = cont
            .width(iced::Length::Fill)
            .align_x(iced::alignment::Horizontal::Left)
            .padding(iced::Padding { top: 0.0, right: 0.0, bottom: 0.0, left });
    } else {
        cont = cont.width(iced::Length::Fill).align_x(iced::alignment::Horizontal::Right);
    }
    col = col.push(cont);
    col.into()
}

/// Plan 412 F2: per-cell metadata the grid builder needs but can't recover
/// from an already-built `iced::Element`. Callers extract these from the cell
/// `View`'s style before converting it: `col-span-N` → span, any `w-*` width
/// class → the cell opts the whole grid into compact (content-width) tracks.
#[derive(Debug, Clone, Copy, Default)]
pub struct GridCellSpec {
    pub span: usize,
    pub explicit_width: bool,
}

/// Extract `(span, explicit_width)` from a grid cell `View`'s style.
fn grid_cell_spec<M: Clone + std::fmt::Debug>(view: &AbstractView<M>) -> GridCellSpec {
    let style = extract_view_style(view);
    let mut spec = GridCellSpec { span: 1, explicit_width: false };
    if let Some(s) = style {
        for c in &s.classes {
            match c {
                StyleClass::ColSpan(n) => spec.span = (*n as usize).max(1),
                // Only a *fixed* width (w-8/w-[30px]) opts the grid into compact
                // content-width tracks. w-full is the CSS grid default (item
                // stretches to its track) and stays in equal-track mode.
                StyleClass::Width(
                    crate::ui::style::SizeValue::Fixed(_) | crate::ui::style::SizeValue::Pixels(_),
                ) => {
                    spec.explicit_width = true;
                }
                _ => {}
            }
        }
    }
    spec
}

/// Plan 412 F2: CSS grid auto-placement(简化版)。按源码顺序填充,当前列 +
/// span 超出 `cols` 则换行;span > cols 钳制到 cols。返回每行的
/// `(cell_idx, start_col, span)` 列表(纯函数,便于单测分配器边界:尾行填充、
/// span 钳制、整行 span)。row-span 不做(降级为 col-span,Plan 412 §5)。
fn grid_row_placements(spans: &[usize], cols: usize) -> Vec<Vec<(usize, usize, usize)>> {
    let cols = cols.max(1);
    let mut placements: Vec<Vec<(usize, usize, usize)>> = Vec::new();
    let mut current: Vec<(usize, usize, usize)> = Vec::new();
    let mut cur_col = 0usize;
    for (i, &raw_span) in spans.iter().enumerate() {
        let span = raw_span.clamp(1, cols);
        if cur_col + span > cols {
            placements.push(std::mem::take(&mut current));
            cur_col = 0;
        }
        current.push((i, cur_col, span));
        cur_col += span;
    }
    if !current.is_empty() {
        placements.push(current);
    }
    placements
}

/// Build a CSS-Grid-like layout from pre-built cell elements. Two track modes
/// (Plan 412 F2):
///
/// **equal tracks** (default — no cell carries an explicit `w-*` class):
/// CSS `grid-cols-N` means N equal tracks filling the grid width. Emulated by
/// giving every row `width(Fill)` + `spacing(0)` and placing each cell in a
/// `FillPortion(span)` container whose horizontal padding is the slot's share
/// of the gap. With all rows summing to exactly `cols` portions every slot is
/// `W/cols` wide, and cell `i` (starting column `c`, span `s`) renders at
/// `c·g/cols` from its slot's left edge with width `s·W/cols − (cols−s)·g/cols`
/// — pixel-exact CSS grid geometry (`span cell = s tracks + (s−1) gaps`),
/// including col-span via the CSS auto-placement simplification (fill
/// sequentially, wrap when `col + span > cols`). row-span degrades to
/// col-span (documented in Plan 412 §5).
///
/// **compact tracks** (any cell has `w-*`, e.g. the colour-picker's `w-8 h-8`
/// swatches): the previous behaviour — cells pushed directly (Shrink), rows
/// Shrink-width so the grid hugs its content; keeps the Plan 402 §13.10
/// sizing semantics and the Plan 411 colour-picker parity.
///
/// This is the SINGLE source of truth for grid decomposition (Plan 319).
fn build_grid<M: Clone + Debug + 'static>(
    cols: usize,
    gap: u16,
    cells: Vec<(iced::Element<'static, M>, GridCellSpec)>,
    style: Option<&Style>,
    widget_id: Option<String>,
) -> iced::Element<'static, M> {
    let cols = cols.max(1);
    if cells.is_empty() {
        return apply_column_style(column([]), 0, style, widget_id);
    }

    let equal_tracks = !cells.iter().any(|(_, spec)| spec.explicit_width);

    if !equal_tracks {
        // Compact mode: legacy path — direct cells, final row padded with
        // empty Fill cells, Shrink rows stacked in a gap-spaced column.
        let mut els: Vec<iced::Element<'static, M>> = cells.into_iter().map(|(el, _)| el).collect();
        let pad = cols - (els.len() % cols);
        if pad != cols {
            for _ in 0..pad {
                els.push(text("").width(iced::Length::Fill).into());
            }
        }
        let mut iter = els.into_iter();
        let mut rows: Vec<iced::Element<'static, M>> = Vec::new();
        loop {
            let mut row_b = row([]).spacing(gap as f32);
            let mut count = 0;
            for _ in 0..cols {
                match iter.next() {
                    Some(cell) => {
                        row_b = row_b.push(cell);
                        count += 1;
                    }
                    None => break,
                }
            }
            if count == 0 {
                break;
            }
            rows.push(row_b.into());
        }
        let col_widget = column(rows).spacing(gap as f32).align_x(iced::Alignment::Center);
        return apply_column_style(col_widget, 0, style, widget_id);
    }

    // Equal-track mode: CSS auto-placement via the shared pure placer.
    let spans: Vec<usize> = cells.iter().map(|(_, spec)| spec.span).collect();
    let placements = grid_row_placements(&spans, cols);

    let gap_f = gap as f32;
    let cols_f = cols as f32;
    // Placement order is ascending cell index, so a sequential iterator over
    // `cells` lines up with `placements` exactly.
    let mut iter = cells.into_iter();
    let mut rows: Vec<iced::Element<'static, M>> = Vec::with_capacity(placements.len());
    for row_places in placements {
        let mut row_b = row([]).spacing(0.0).width(iced::Length::Fill);
        let mut occupied = 0usize;
        for (_idx, start, span) in row_places {
            let (el, _spec) = iter.next().expect("placement count matches cells");
            // Inner Fill wrapper stretches the cell to its track (CSS grid
            // default: items fill the track), so cell backgrounds/borders and
            // centered content line up with the vue rendering.
            let stretched = container(el).width(iced::Length::Fill);
            let cell = container(stretched)
                .width(iced::Length::FillPortion(span as u16))
                .padding(iced::Padding {
                    top: 0.0,
                    bottom: 0.0,
                    left: start as f32 * gap_f / cols_f,
                    right: (cols - start - span) as f32 * gap_f / cols_f,
                });
            row_b = row_b.push(cell);
            occupied += span;
        }
        // Pad the trailing run so every row totals `cols` portions — without
        // this the final row's cells would stretch into the empty tracks.
        if occupied < cols {
            row_b = row_b.push(
                iced::widget::Space::new().width(iced::Length::FillPortion((cols - occupied) as u16)),
            );
        }
        rows.push(row_b.into());
    }
    let col_widget = column(rows).spacing(gap_f).align_x(iced::Alignment::Center);
    apply_column_style(col_widget, 0, style, widget_id)
}

// NOTE: Textarea shape is NOT extracted into a shared builder. iced's
// `TextEditor` carries a generic `Highlighter` type parameter, so a clean
// shared return type would leak iced internals into the signature. The
// textarea "shape" is also trivial (a height ternary) and its `on_action`
// handler is inherently mode-specific, so each converter keeps its own
// inline construction — see the `Textarea` arms in `into_iced` and
// `render_dynamic_view`.

/// # Unification rule for new widgets (Plan 319 — read before extending)
///
/// VM mode and Rust mode convert the *same* `AbstractView<M>` tree to iced via
/// **two** entry points: this generic `into_iced<M>` (Rust mode) and the
/// `IcedMessage`-specific `render_dynamic_view` (VM mode, adds DevTools
/// instrumentation). To keep them from drifting, follow this rule:
///
/// 1. **A new widget gets exactly ONE arm here, in `into_iced`.** If it has
///    styled/iterated children, factor the shape into a shared generic
///    `build_<widget><M>` helper (see `build_row` / `build_column` /
///    `build_container` / `build_scrollable` / `build_grid` / `build_input_shape`)
///    and call it with `widget_id = None`.
/// 2. **`render_dynamic_view` NEVER reimplements widget shape.** Its same-named
///    arm only: (a) recurse into each child to attach per-node instrumentation,
///    (b) call the *same* `build_*` helper (passing the instrumented children +
///    the `widget_id` from the debug id map), (c) `wrap_debug` the result.
/// 3. **No third copy.** A widget's spacing/padding/width/children-loop lives in
///    exactly one place — its `build_*` helper. Both converters delegate to it.
///
/// The grid "tower" bug (VM rendered fine, Rust collapsed to a vertical stack)
/// was caused by exactly the drift this rule forbids: the layout lived in two
/// `build_*`-less copies that diverged. `View::Grid` + `build_grid` exists so
/// that cannot recur — grid decomposition is now a single source of truth.
/// Plan 490 G4：布局件（row/col/div=Container）点击包装——有 onclick 时
/// 以 mouse_area 包装、on_release 发射声明消息（402 右键 / 484 hover 两
/// mouse_area 先例同 API 形态）；检视捕获模式不包（inspect mouse_area 需
/// 独占命中，同按钮右键守卫）；None = 原样直出零开销。
fn wrap_layout_onclick<'a, M: Clone + 'static>(
    el: iced::Element<'a, M>,
    onclick: Option<M>,
) -> iced::Element<'a, M> {
    match onclick {
        Some(msg) if !inspect_capture_active() => mouse_area(el).on_release(msg).into(),
        _ => el,
    }
}

impl<M: Clone + Debug + 'static> IntoIcedElement<M> for AbstractView<M> {
    fn into_iced(self) -> iced::Element<'static, M> {
        match self {
            AbstractView::Empty => {
                // Plan 370 (Issue 1): render Empty as a zero-height Space
                // instead of text(""). A text("") still reserves one line of
                // vertical height in iced, so stacking several Empty views
                // (from false `if` branches / non-matching `for` iterations)
                // produced large blank gaps. A zero-height Space collapses.
                iced::widget::Space::new()
                    .width(iced::Length::Shrink)
                    .height(iced::Length::Fixed(0.0))
                    .into()
            }

            AbstractView::Text { content, style, selectable, .. } => {
                // Plan 409 §10 续 20: font-mono 的 Text 当代码 → Rich 语法高亮。
                let is_code = style.as_ref()
                    .map(|s| IcedStyle::from_style(s).font_family.as_deref() == Some("mono"))
                    .unwrap_or(false);
                if is_code {
                    // Plan 442 A6: codeblock 携带的 lang-<token> class 决定
                    // syntect 语法选择(见 aura_view_builder codeblock 分支)。
                    let lang = style.as_ref().and_then(|s| {
                        s.classes.iter().find_map(|c| match c {
                            StyleClass::CodeLang(l) => Some(l.clone()),
                            _ => None,
                        })
                    });
                    let spans = highlight_code(&content, lang.as_deref());
                    let mut rich = iced::widget::text::Rich::<(), M>::with_spans(spans)
                        .font(iced::Font { family: iced::font::Family::Monospace, ..iced::Font::DEFAULT });
                    if let Some(ref s) = style {
                        if let Some(fs) = effective_font_size(&IcedStyle::from_style(s)) {
                            rich = rich.size(fs);
                        }
                    }
                    let el: iced::Element<'static, M> = rich.into();
                    if let Some(ref s) = style {
                        wrap_with_margin(el, &IcedStyle::from_style(s))
                    } else {
                        el
                    }
                } else if selectable {
                    // Plan 481: SelectableText 分流 —— 与下方 text 构造链同参
                    // 镜像(缺省 false 路径零改动,I3 配置差异形态)。label 无
                    // 独立 View 变体(aura_view_builder 折叠为 Text),此臂即
                    // text/label 共用分流点。
                    use crate::ui::iced::selectable_text::SelectableText;
                    let mut st = SelectableText::new(content.clone());

                    if let Some(ref s) = style {
                        let iced_style = IcedStyle::from_style(s);

                        if let Some(fs) = effective_font_size(&iced_style) {
                            st = st.size(fs);
                        }
                        if let Some(color) = iced_style.text_color {
                            st = st.color(color);
                        } else if let Some((r, g, b)) =
                            crate::ui::style::iced_adapter::resolve_semantic_rgb(
                                &crate::ui::style::Color::OnBackground,
                            )
                        {
                            st = st.color(iced::Color::from_rgb8(r, g, b));
                        }
                        if let Some(ref weight) = iced_style.font_weight {
                            st = st.font(font_weight_to_iced(weight));
                        }
                        if let Some(ref family) = iced_style.font_family {
                            let fam = match family.as_str() {
                                "serif" => iced::font::Family::Serif,
                                "mono" => iced::font::Family::Monospace,
                                _ => iced::font::Family::SansSerif,
                            };
                            let weight = iced_style
                                .font_weight
                                .as_ref()
                                .map(font_weight_to_iced)
                                .unwrap_or(iced::Font::DEFAULT);
                            st = st.font(iced::Font {
                                family: fam,
                                weight: weight.weight,
                                stretch: weight.stretch,
                                style: weight.style,
                            });
                        }
                        if let Some(ref w) = iced_style.width {
                            st = st.width(iced_length(w));
                        }
                        if let Some(ref align) = iced_style.text_align {
                            use crate::ui::style::iced_adapter::IcedTextAlign;
                            if iced_style.width.is_none() {
                                st = st.width(iced::Length::Fill);
                            }
                            match align {
                                IcedTextAlign::Center => {
                                    st = st.align_x(iced::alignment::Horizontal::Center);
                                }
                                IcedTextAlign::Right => {
                                    st = st.align_x(iced::alignment::Horizontal::Right);
                                }
                                IcedTextAlign::Left => {}
                            }
                        }
                    }

                    let el: iced::Element<'static, M> = st.into();
                    if let Some(ref s) = style {
                        wrap_with_margin(el, &IcedStyle::from_style(s))
                    } else {
                        el
                    }
                } else if style.as_ref().map_or(false, |s| {
                    let is = IcedStyle::from_style(s);
                    is.line_through || is.underline
                }) {
                    let iced_style = IcedStyle::from_style(style.as_ref().unwrap());
                    let mut span = iced::widget::text::Span::new(content);
                    if iced_style.line_through {
                        span = span.strikethrough(true);
                    }
                    if iced_style.underline {
                        span = span.underline(true);
                    }
                    if let Some(fs) = effective_font_size(&iced_style) {
                        span = span.size(fs);
                    }
                    if let Some(color) = iced_style.text_color {
                        span = span.color(color);
                    } else if let Some((r, g, b)) = crate::ui::style::iced_adapter::resolve_semantic_rgb(
                        &crate::ui::style::Color::OnBackground,
                    ) {
                        span = span.color(iced::Color::from_rgb8(r, g, b));
                    }
                    if let Some(ref weight) = iced_style.font_weight {
                        span = span.font(font_weight_to_iced(weight));
                    }
                    if let Some(ref family) = iced_style.font_family {
                        let fam = match family.as_str() {
                            "serif" => iced::font::Family::Serif,
                            "mono" => iced::font::Family::Monospace,
                            _ => iced::font::Family::SansSerif,
                        };
                        let weight = iced_style.font_weight.as_ref().map(font_weight_to_iced).unwrap_or(iced::Font::DEFAULT);
                        span = span.font(iced::Font {
                            family: fam,
                            weight: weight.weight,
                            stretch: weight.stretch,
                            style: weight.style,
                        });
                    }
                    let mut rich = iced::widget::text::Rich::<(), M>::with_spans(vec![span]);
                    if let Some(ref w) = iced_style.width {
                        rich = rich.width(iced_length(w));
                    }
                    if let Some(ref align) = iced_style.text_align {
                        use crate::ui::style::iced_adapter::IcedTextAlign;
                        if iced_style.width.is_none() {
                            rich = rich.width(iced::Length::Fill);
                        }
                        match align {
                            IcedTextAlign::Center => {
                                rich = rich.align_x(iced::alignment::Horizontal::Center);
                            }
                            IcedTextAlign::Right => {
                                rich = rich.align_x(iced::alignment::Horizontal::Right);
                            }
                            IcedTextAlign::Left => {}
                        }
                    }
                    let el: iced::Element<'static, M> = rich.into();
                    wrap_with_margin(el, &iced_style)
                } else {
                let mut text_widget = text(content);

                if let Some(ref s) = style {
                    let iced_style = IcedStyle::from_style(s);

                    if let Some(fs) = effective_font_size(&iced_style) {
                        text_widget = text_widget.size(fs);
                    }
                    if let Some(color) = iced_style.text_color {
                        text_widget = text_widget.color(color);
                    } else {
                        // Plan 408: no explicit text color → apply dark-mode-aware
                        // default (equivalent to vue's body { text-foreground }
                        // inheritance). Without this, iced defaults to BLACK which
                        // is invisible on dark backgrounds.
                        if let Some((r, g, b)) = crate::ui::style::iced_adapter::resolve_semantic_rgb(
                            &crate::ui::style::Color::OnBackground,
                        ) {
                            text_widget = text_widget.color(iced::Color::from_rgb8(r, g, b));
                        }
                    }
                    if let Some(ref weight) = iced_style.font_weight {
                        text_widget = text_widget.font(font_weight_to_iced(weight));
                    }
                    // Apply font family (font-serif/sans/mono)
                    if let Some(ref family) = iced_style.font_family {
                        let fam = match family.as_str() {
                            "serif" => iced::font::Family::Serif,
                            "mono" => iced::font::Family::Monospace,
                            _ => iced::font::Family::SansSerif,
                        };
                        let weight = iced_style.font_weight.as_ref().map(font_weight_to_iced).unwrap_or(iced::Font::DEFAULT);
                        text_widget = text_widget.font(iced::Font {
                            family: fam,
                            weight: weight.weight,
                            stretch: weight.stretch,
                            style: weight.style,
                        });
                    }
                    // Plan 527 T5: 行高 —— 绝对档(leading-3..10)优先,相对倍率次之
                    if let Some(px) = iced_style.line_height_px {
                        text_widget = text_widget
                            .line_height(iced::widget::text::LineHeight::Absolute(iced::Pixels(px)));
                    } else if let Some(lh) = iced_style.line_height {
                        text_widget =
                            text_widget.line_height(iced::widget::text::LineHeight::Relative(lh));
                    }
                    // Apply width (e.g., from flex-1)
                    if let Some(ref w) = iced_style.width {
                        text_widget = text_widget.width(iced_length(w));
                    }
                    if let Some(ref align) = iced_style.text_align {
                        use crate::ui::style::iced_adapter::IcedTextAlign;
                        if iced_style.width.is_none() {
                            text_widget = text_widget.width(iced::Length::Fill);
                        }
                        match align {
                            IcedTextAlign::Center => {
                                text_widget = text_widget.align_x(iced::alignment::Horizontal::Center);
                            }
                            IcedTextAlign::Right => {
                                text_widget = text_widget.align_x(iced::alignment::Horizontal::Right);
                            }
                            IcedTextAlign::Left => {}
                        }
                    }
                }

                // 2026-08-22(侧栏描述换行治理):truncate/whitespace-nowrap →
                // 单行(Wrapping::None)+ clip 容器裁横向溢出,对齐 CSS truncate。
                let wrap_none = style.as_ref()
                    .map(|s| IcedStyle::from_style(s).wrap_none)
                    .unwrap_or(false);
                if wrap_none {
                    text_widget = text_widget
                        .wrapping(iced::widget::text::Wrapping::None)
                        .width(iced::Length::Fill);
                }
                let el: iced::Element<'static, M> = if wrap_none {
                    iced::widget::container(text_widget)
                        .width(iced::Length::Fill)
                        .clip(true)
                        .into()
                } else if let Some(ref s) = style {
                    let iced_style = IcedStyle::from_style(s);
                    let has_box_style = iced_style.background_color.is_some()
                        || iced_style.border
                        || iced_style.has_border_radius()
                        || iced_style.border_width.map_or(false, |w| w > 0.0)
                        || iced_style.padding.is_some()
                        || iced_style.padding_x.is_some()
                        || iced_style.padding_y.is_some()
                        || iced_style.padding_top.is_some()
                        || iced_style.padding_bottom.is_some()
                        || iced_style.padding_left.is_some()
                        || iced_style.padding_right.is_some()
                        || iced_style.max_width.is_some()
                        || iced_style.max_height.is_some()
                        || iced_style.shadow;

                    if has_box_style {
                        let pad = iced_padding_from_is(&iced_style, 0);
                        let cs = build_container_style(&iced_style);
                        let mut cont = iced::widget::container(text_widget)
                            .padding(pad)
                            .style(move |_| cs);
                        if let Some(mw) = iced_style.max_width {
                            cont = cont.max_width(mw);
                        }
                        if let Some(mh) = iced_style.max_height {
                            cont = cont.max_height(mh);
                        }
                        cont.into()
                    } else {
                        text_widget.into()
                    }
                } else {
                    text_widget.into()
                };
                if let Some(ref s) = style {
                    let iced_style = IcedStyle::from_style(s);
                    wrap_with_margin(el, &iced_style)
                } else {
                    el
                }
                }
            }

            AbstractView::Button { label, content, onclick, style, on_right_click, disabled } => {
                // Plan 418 P2-3 续: EE03 PUA marker carries an icon-button
                // tooltip (synthesized toolbar buttons embed the action title
                // there — the label itself stays icon-only so the resting
                // render is a bare svg). Stripped here; wrapped around the
                // final element at the arm's end.
                let (label, pua_tooltip): (String, Option<String>) =
                    match label.find('\u{EE03}') {
                        Some(i) => (
                            label[..i].to_string(),
                            Some(label[i + '\u{EE03}'.len_utf8()..].to_string()),
                        ),
                        None => (label, None),
                    };
                let iced_style = style.as_ref().map(|s| IcedStyle::from_style(s));

                // Plan 409 §6: if the button carries a content subtree (a `link`
                // with children — `link (to:) { text/row/icon ... }`), render it
                // directly as the button content. The label is kept for the
                // snapshot builder / accessibility.
                // Plan 409 §8: inherit the button's own text color into the
                // content subtree — Text children without an explicit color
                // (e.g. `link (to: "/") { text "Docs" }`) become theme-colored
                // instead of falling back to the body default (vue parity).
                let inherit_color = style.as_ref().and_then(|s| {
                    // PLAN-055: 取最后一个 TextColor（与 IcedStyle::from_style
                    // "后类胜"语义一致）——此前 find_map 取首个，preset 的
                    // `text-primary-foreground` 恒压过用户后置的
                    // `text-muted-foreground`：图标继承 OnPrimary（深藏青）
                    // 落深底不可见，按钮文字却是浅色——图文两色。
                    s.classes.iter().rev().find_map(|c| match c {
                        StyleClass::TextColor(color) => Some(*color),
                        _ => None,
                    })
                });
                // Plan 057 (ash-gui VM 修复): icon-button 形态 —— style 同时带固定
                // 宽和高(如 block 头部 `h-6 w-6` 的 chevron/copy 按钮)。这类按钮的
                // variant/size preset 会前置 `px-4`(16px),用户 class 只有 w/h 时
                // 16px×2 的水平内边距超过按钮宽度,iced 的内容区收敛到 ≤0,icon/文字
                // 一律不绘制(块头操作按钮全空白的根因)。CSS 侧这些按钮靠
                // `flex items-center justify-center` 居中,iced 无 flex——此处对
                // 双固定尺寸按钮:内边距清零 + 内容在盒内双向居中,复现 CSS 语义。
                let fixed_both = matches!(
                    (iced_style.as_ref().and_then(|is| is.width), iced_style.as_ref().and_then(|is| is.height)),
                    (
                        Some(crate::ui::style::iced_adapter::IcedSize::Fixed(_)),
                        Some(crate::ui::style::iced_adapter::IcedSize::Fixed(_))
                    )
                );
                let button_content: iced::Element<'static, M> = if let Some(mut content_view) = content {
                    if let Some(color) = inherit_color {
                        inherit_text_color(&mut content_view, color);
                    }
                    (*content_view).into_iced()
                } else if label.starts_with('\u{EE01}') {
                    let end = label.find('\u{EE02}').unwrap_or(label.len());
                    let icon_name = &label[3..end.min(label.len())];
                    let text_label = &label[end.saturating_add(3).min(label.len())..];
                    // Plan 515 D1：hicon:<slot> = native 真图标（raster——
                    // 486 占位清偿；14px 与邻位 lucide 图标同档）。
                    if let Some(icon) = crate::ui::iced::native_icon::parse_field(icon_name) {
                        let handle = iced::widget::image::Handle::from_rgba(
                            icon.w, icon.h, icon.rgba,
                        );
                        // PLAN-526 T9：图标盒跟随按钮字号（text-lg → 18px），
                        // 回退 14px（462 档）——大框小图实测反馈闭环。
                        let icon_px = iced_style
                            .as_ref()
                            .and_then(|is| is.font_size.as_ref())
                            .map(font_size_to_f32)
                            .unwrap_or(14.0);
                        let icon_el = iced::widget::image(handle)
                            .width(iced::Length::Fixed(icon_px))
                            .height(iced::Length::Fixed(icon_px));
                        if text_label.is_empty() {
                            icon_el.into()
                        } else {
                            let mut tw = text(text_label.to_string());
                            if let Some(ref is) = iced_style {
                                if let Some(ref fs) = is.font_size { tw = tw.size(font_size_to_f32(fs)); }
                                if let Some(c) = is.text_color { tw = tw.color(c); }
                            }
                            iced::widget::row!(icon_el, tw)
                                .spacing(6)
                                .align_y(iced::alignment::Vertical::Center)
                                .into()
                        }
                    } else if let Some(svg_str) = lucide_svg_doc(icon_name) {
                        // Plan 409 §10 续: PUA icon(button label 内嵌的 nav-link
                        // 图标)与文字同色 —— button 的 text_color,无则 OnBackground
                        // (renderer §3.4,避免 resvg 把 currentColor 画成黑色)。
                        // 2026-08-21 方案 A:改画时着色(svg::Style.color);悬停色取
                        // 按钮自身 hover:text-*(浏览器里 button:hover 的 color 经
                        // 继承级联到内联 SVG,此处以 svg 自身 Hovered 状态近似 ——
                        // 命中区为图标盒而非整个按钮,图标贴文本时差异可忽略)。
                        let text_color = iced_style.as_ref().and_then(|is| is.text_color)
                            .or_else(|| {
                                crate::ui::style::iced_adapter::resolve_semantic_rgb(
                                    &crate::ui::style::Color::OnBackground,
                                ).map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
                            });
                        let hover_color = style.as_ref().and_then(|s| {
                            s.hover_classes.iter().find_map(|c| match c {
                                StyleClass::TextColor(color) => {
                                    Some(crate::ui::style::iced_adapter::convert_color(color))
                                }
                                _ => None,
                            })
                        });
                        let base = text_color.unwrap_or(iced::Color::BLACK);
                        let handle = get_or_create_svg_handle(
                            &format!("lucide:{}", icon_name),
                            svg_str.as_bytes().to_vec(),
                        );
                        // PLAN-526 T9：图标盒跟随按钮字号（text-lg → 18px），
                        // 回退 14px——与 hicon 臂同口径。
                        let icon_px = iced_style
                            .as_ref()
                            .and_then(|is| is.font_size.as_ref())
                            .map(font_size_to_f32)
                            .unwrap_or(14.0);
                        let icon_el = iced::widget::svg(handle)
                            .style(move |_, status| {
                                let color = match status {
                                    iced::widget::svg::Status::Hovered => {
                                        hover_color.unwrap_or(base)
                                    }
                                    _ => base,
                                };
                                iced::widget::svg::Style { color: Some(color) }
                            })
                            .width(iced::Length::Fixed(icon_px))
                            .height(iced::Length::Fixed(icon_px));
                        let mut tw = text(text_label.to_string());
                        if let Some(ref is) = iced_style {
                            if let Some(ref fs) = is.font_size { tw = tw.size(font_size_to_f32(fs)); }
                            if let Some(c) = is.text_color { tw = tw.color(c); }
                        }
                        // Icon-only (no text part): return the bare svg - the row with its
                        // spacing(6) adds trailing space after the icon, skewing it ~3px
                        // left of center inside square buttons (Plan 414 R14).
                        if text_label.is_empty() {
                            icon_el.into()
                        } else {
                            iced::widget::row!(icon_el, tw)
                                .spacing(6)
                                .align_y(iced::alignment::Vertical::Center)
                                .into()
                        }
                    } else {
                        // Unknown icon: fall back to plain text label
                        text(text_label.to_string()).into()
                    }
                } else if label.contains('\n') {
                    let lines: Vec<&str> = label.split('\n').collect();
                    let mut col = iced::widget::Column::<M>::with_capacity(lines.len());
                    let default_size = font_size_to_f32(&IcedFontSize::Sm);
                    let default_weight = font_weight_to_iced(&IcedFontWeight::Medium);
                    for (i, line) in lines.iter().enumerate() {
                        let mut tw = text(line.to_string());
                        // Apply the button's own text styles to the first line (title).
                        if i == 0 {
                            if let Some(ref is) = iced_style {
                                tw = tw.size(is.font_size.as_ref().map_or(default_size, font_size_to_f32));
                                if let Some(color) = is.text_color {
                                    tw = tw.color(color);
                                }
                                tw = tw.font(is.font_weight.as_ref().map_or(default_weight, font_weight_to_iced));
                            } else {
                                tw = tw.size(default_size).font(default_weight);
                            }
                        } else {
                            // Metadata lines: smaller (12px) + muted gray.
                            tw = tw.size(12.0).color([0.5, 0.5, 0.5, 1.0]);
                        }
                        col = col.push(tw);
                    }
                    col.into()
                } else if let Some(ref is) = iced_style {
                    let default_size = font_size_to_f32(&IcedFontSize::Sm);
                    let default_weight = font_weight_to_iced(&IcedFontWeight::Medium);
                    if is.line_through || is.underline {
                        let mut span = iced::widget::text::Span::new(label.clone());
                        if is.line_through {
                            span = span.strikethrough(true);
                        }
                        if is.underline {
                            span = span.underline(true);
                        }
                        span = span.size(is.font_size.as_ref().map_or(default_size, font_size_to_f32));
                        if let Some(color) = is.text_color {
                            span = span.color(color);
                        }
                        span = span.font(is.font_weight.as_ref().map_or(default_weight, font_weight_to_iced));
                        let mut rich = iced::widget::text::Rich::<(), M>::with_spans(vec![span]);
                        if let Some(ref align) = is.text_align {
                            let _ = align;
                            rich = rich.width(iced::Length::Fill);
                            match align {
                                crate::ui::style::iced_adapter::IcedTextAlign::Center => {
                                    rich = rich.align_x(iced::alignment::Horizontal::Center);
                                }
                                crate::ui::style::iced_adapter::IcedTextAlign::Right => {
                                    rich = rich.align_x(iced::alignment::Horizontal::Right);
                                }
                                crate::ui::style::iced_adapter::IcedTextAlign::Left => {}
                            }
                        }
                        rich.into()
                    } else {
                        let mut text_widget = text(label.clone());
                        text_widget = text_widget.size(is.font_size.as_ref().map_or(default_size, font_size_to_f32));
                        if let Some(color) = is.text_color {
                            text_widget = text_widget.color(color);
                        }
                        text_widget = text_widget.font(is.font_weight.as_ref().map_or(default_weight, font_weight_to_iced));
                        // Plan 411: text-center/left/right on button labels — wide
                        // buttons (e.g. preview-card tabs) need horizontal alignment.
                        // Unlike the Text arm, ALWAYS Fill the label: is.width is the
                        // BUTTON's width class (w-full here), not the text's, so the
                        // is_none() guard would skip Fill and align_x would no-op.
                        if let Some(ref align) = is.text_align {
                            let _ = align;
                            text_widget = text_widget.width(iced::Length::Fill);
                            match align {
                                crate::ui::style::iced_adapter::IcedTextAlign::Center => {
                                    text_widget = text_widget.align_x(iced::alignment::Horizontal::Center);
                                }
                                crate::ui::style::iced_adapter::IcedTextAlign::Right => {
                                    text_widget = text_widget.align_x(iced::alignment::Horizontal::Right);
                                }
                                crate::ui::style::iced_adapter::IcedTextAlign::Left => {}
                            }
                        }
                        text_widget.into()
                    }
                } else {
                    let text_widget = text(label.clone())
                        .size(font_size_to_f32(&IcedFontSize::Sm))
                        .font(font_weight_to_iced(&IcedFontWeight::Medium));
                    text_widget.into()
                };

                // Plan 309 续篇 II: in inspect-capture mode, render the button
                // WITHOUT on_press so it doesn't capture the press — the
                // `wrap_debug` mouse_area then captures inspect hover/click over
                // it. The button keeps its custom `move |_, _| bs` style below,
                // so it still renders normally (status is ignored). Alt (capture
                // off) restores the native onclick.
                // Plan 409 §10 续 21: Fixed-height button 的 content 垂直居中
                // (iced button padded 默认 content 顶部对齐,h-9/h-10/h-11 会偏上)。
                // 包一层 Fill+center_y 容器让文字纵向居中。
                // Plan 057 (ash-gui VM 修复): 双固定尺寸 icon-button 走双向居中
                // (见上方 fixed_both 注释),复现 `flex items-center justify-center`。
                // Plan 414 R12: fixed-size buttons center their content HORIZONTALLY
                // too - iced button content hugs the left edge, so a fixed-width
                // button holding a 16px icon (toolbar w-8) sat left-of-center and
                // the gaps next to a sep read uneven (user-verified via debug
                // borders). CSS buttons center by default; shrink-width buttons
                // are unaffected (content width = button width).
                // Fill-width ONLY for buttons with an explicit width class: a Fill
                // content wrapper also makes height-only buttons (menus, tabs)
                // claim the whole row and stretch equally - regression fixed by
                // scoping center_x to width-classed buttons.
                // Plan-050 C1: content-subtree 按钮消费 .at 的宽度/对齐类——
                // w-full 已由 is.width→btn.width(Fill) 承接;此处补内容对齐
                // (justify-start/text-left→水平,items-start→垂直),Fill 容器
                // 承载对齐;未命中维持 iced 默认居中。
                // 先于 409/414 分支计算:高度臂的默认居中必须给显式对齐类
                // 让位(iced 容器默认居中,外层 050 包装包不住内层 center_x
                // ——nav-item(h-9 w-full text-left)内容恒居中的根因)。
                let (p050_ax, p050_ay) = plan050_content_align(iced_style.as_ref());
                let button_content: iced::Element<'static, M> = if fixed_both {
                    iced::widget::container(button_content)
                        .width(iced::Length::Fill)
                        .height(iced::Length::Fill)
                        .center_x(iced::Length::Fill)
                        .center_y(iced::Length::Fill)
                        .into()
                } else if iced_style
                    .as_ref()
                    .map_or(false, |is| is.height.is_some())
                {
                    let has_width = iced_style.as_ref().map_or(false, |is| is.width.is_some());
                    let (ax, ay) = plan414_content_alignment(p050_ax, p050_ay);
                    let mut cont = iced::widget::container(button_content)
                        .height(iced::Length::Fill)
                        .align_y(ay);
                    if has_width {
                        cont = cont.width(iced::Length::Fill).align_x(ax);
                    }
                    cont.into()
                } else {
                    button_content
                };
                let button_content: iced::Element<'static, M> =
                    if p050_ax.is_some() || p050_ay.is_some() {
                        let mut c = iced::widget::container(button_content)
                            .width(iced::Length::Fill);
                        if let Some(ax) = p050_ax { c = c.align_x(ax); }
                        if let Some(ay) = p050_ay { c = c.align_y(ay); }
                        c.into()
                    } else {
                        button_content
                    };
                let mut btn = button(button_content);
                // Plan 423 P3: disabled 态 —— 不挂 on_press(点击无消息);
                // inspect 捕获模式同样不挂(原语义)。灰样式在下方 style 段追加。
                if !inspect_capture_active() && !disabled {
                    btn = btn.on_press(onclick);
                }

                // Apply visual styling to button. Always apply a class-driven
                // style: build_button_style yields a chromeless (transparent)
                // button when no background/border class is present, so a
                // text-only button (e.g. `button(variant: "text")` or any button
                // with only text classes) renders as text instead of iced's
                // default Primary (blue).
                if let Some(ref is) = iced_style {
                    let bs = build_button_style(is);
                    // `hover:` utilities: build a hovered variant with the
                    // hover classes applied on top of the base classes
                    // (later application wins, so hover:bg-* overrides the
                    // base background). iced re-invokes this closure on
                    // status changes — native hover feedback without a view
                    // rebuild (e.g. block header icon buttons light up via
                    // hover:bg-white/10). hover:text-* here only reaches the
                    // button's own label/text_color — icons recolor through
                    // their own svg Status styling (see Image lucide arm /
                    // PUA icon arm, 2026-08-21 方案 A), other pre-built child
                    // content is unaffected.
                                   // Plan 527 T6: 变体管道泛化 —— base+变体合并构建各状态样式(变体后应用
                    // 胜出,`hover:` 先例同构);无声明时等价 base。iced 状态
                    // 回调面:Hovered→hover、Pressed→active(缺 active 声明时
                    // 回 hover,保持 legacy 行为)、Focused→focus、
                    // Disabled→disabled。focus: iced 0.14 button Status 无
                    // Focused 档(上限),类可声明可合并(IcedStyle::
                    // merged_with_variant),按钮回调面登记 parsed-only(KNOWN-DEBT)。
                    let bs_hover = match style.as_ref() {
                        Some(s) if s.has_variant(crate::ui::style::Variant::Hover) => {
                            build_button_style(&IcedStyle::merged_with_variant(
                                s,
                                crate::ui::style::Variant::Hover,
                            ))
                        }
                        _ => bs,
                    };
                    let bs_active = match style.as_ref() {
                        Some(s) if s.has_variant(crate::ui::style::Variant::Active) => {
                            build_button_style(&IcedStyle::merged_with_variant(
                                s,
                                crate::ui::style::Variant::Active,
                            ))
                        }
                        _ => bs_hover,
                    };
                    let bs_disabled = match style.as_ref() {
                        Some(s) if s.has_variant(crate::ui::style::Variant::Disabled) => {
                            build_button_style(&IcedStyle::merged_with_variant(
                                s,
                                crate::ui::style::Variant::Disabled,
                            ))
                        }
                        _ => bs,
                    };
                    // Plan 423 P3: disabled 灰态 —— 文本色压成 zinc-500(全部
                    // 状态压灰,禁用不应有可点提示)。
                    let (mut bs, mut bs_hover, mut bs_active, mut bs_disabled) =
                        (bs, bs_hover, bs_active, bs_disabled);
                    if disabled {
                        let gray = iced::Color::from_rgb8(113, 113, 122); // zinc-500
                        bs.text_color = gray;
                        bs_hover.text_color = gray;
                        bs_active.text_color = gray;
                        bs_disabled.text_color = gray;
                    }
                    btn = btn.style(move |_, status| match status {
                        iced::widget::button::Status::Hovered => bs_hover,
                        iced::widget::button::Status::Pressed => bs_active,
                        iced::widget::button::Status::Disabled => bs_disabled,
                        _ => bs,
                    });
                    if fixed_both {
                        // Plan 057 (ash-gui VM 修复): 双固定尺寸按钮内边距清零
                        // (preset 的 px-4=16px×2 会把 w-6=24px 的内容区压到 ≤0,
                        // icon 不绘制);内容居中由上方 wrapper 负责。
                        btn = btn.padding(0.0);
                    } else if let Some(px) = is.padding {
                        btn = btn.padding(px);
                    } else if is.padding_x.is_some() || is.padding_y.is_some() {
                        let px_x = is.padding_x.unwrap_or(8.0);
                        let px_y = is.padding_y.unwrap_or(4.0);
                        btn = btn.padding([px_y, px_x]);
                    } else {
                        // Plan 402: default padding so tiny-content buttons
                        // (e.g. a minesweeper cell with " ") have a clickable
                        // size instead of collapsing to ~0.
                        btn = btn.padding(8.0);
                    }
                    if let Some(ref w) = is.width { btn = btn.width(iced_length(w)); }
                    if let Some(ref h) = is.height { btn = btn.height(iced_length(h)); }
                } else {
                    // No style prop at all: chromeless instead of iced Primary.
                    // Plan 408: chromeless + dark-mode-aware text color.
                    let default_text = crate::ui::style::iced_adapter::resolve_semantic_rgb(
                        &crate::ui::style::Color::OnBackground,
                    ).map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
                     .unwrap_or(iced::Color::WHITE);
                    btn = btn.style(move |_, _| iced::widget::button::Style {
                        background: None,
                        text_color: default_text,
                        ..Default::default()
                    });
                }

                // Plan 409 §10 续 14/17: button 支持 width/flex-1 + height(让
                // component-card 等宽、button size sm/lg 区分高度)。
                // flex-1 在 iced_adapter 里设 is.width=Fill,这里统一用 is.width/height。
                if let Some(ref is) = iced_style {
                    if let Some(ref w) = is.width {
                        btn = btn.width(iced_length(w));
                    }
                    if let Some(ref h) = is.height {
                        btn = btn.height(iced_length(h));
                    }
                }

                // Plan 402: wrap button in mouse_area for right-click (contextmenu)
                // support. iced's button has no native right-click event; mouse_area's
                // on_right_press fires on right mouse button press.
                let el: iced::Element<'static, M> = btn.into();
                let el: iced::Element<'static, M> = if let Some(right_msg) = on_right_click {
                    if !inspect_capture_active() {
                        mouse_area(el)
                            .on_right_press(right_msg)
                            .into()
                    } else {
                        el
                    }
                } else {
                    el
                };
                // Wrap in container if margin_top (from mt-*) needs to be applied
                let el: iced::Element<'static, M> = if let Some(ref is) = iced_style {
                    wrap_with_margin(el, is)
                } else {
                    el
                };
                // Plan 418 P2-3 续: EE03 tooltip — icon-only toolbar buttons
                // show their action title in a small dark rounded bubble
                // below the icon while hovered (menu-panel palette).
                if let Some(tip) = pua_tooltip {
                    iced::widget::tooltip(
                        el,
                        iced::widget::text(tip).size(12.0),
                        iced::widget::tooltip::Position::Bottom,
                    )
                    .gap(6.0)
                    // 300ms delay: iced Tooltip opens with invalidate_layout
                    // at delay=ZERO — a hover instantly rebuilds the tree and
                    // kills any in-flight button press (toolbar icons became
                    // unclickable). Resting hover still shows the bubble.
                    .delay(std::time::Duration::from_millis(300))
                    .style(|_| iced::widget::container::Style {
                        background: Some(iced::Background::Color(iced::Color::from_rgb8(
                            0x16, 0x17, 0x1B,
                        ))),
                        border: iced::Border {
                            color: iced::Color::from_rgb8(0x3F, 0x3F, 0x46),
                            width: 1.0,
                            radius: 6.0.into(),
                        },
                        text_color: Some(iced::Color::from_rgb8(0xE4, 0xE4, 0xE7)),
                        ..Default::default()
                    })
                    .into()
                } else {
                    el
                }
            }

            AbstractView::Row { children, spacing, padding, style, onclick } => {
                // 轴向修正(概要页对拍,EDGE-16 家族):见 axis_fix_row_child。
                let els: Vec<iced::Element<'static, M>> =
                    children.into_iter().map(axis_fix_row_child).map(|c| c.into_iced()).collect();
                // Plan 490 G4：布局件点击（row/col/div onclick parity）。
                wrap_layout_onclick(build_row(els, spacing, padding, style.as_ref(), None), onclick)
            }

            AbstractView::Column { children, spacing, padding, style, onclick } => {
                // 轴向修正:flex-1 主轴语义转写,见 axis_fix_col_child。
                // PLAN-050 P2 #3: mt-auto → 列内弹性占位——此前 margin 系静默
                // 跳过,`mt-auto` 工具行（rail 底部工具栏）失去贴底语义。
                // PLAN-054 T4 (A6): 子项 self-end/start/center → 交叉轴(横向)
                // Fill+align 包裹——iced 列无 per-child 对齐,消息行
                // `self-end` 右对齐此前被静默丢弃。
                let mut els: Vec<iced::Element<'static, M>> = Vec::new();
                for c in children {
                    let mt_auto = extract_view_style(&c)
                        .map_or(false, |s| plan050_mt_auto_spacer(&s.classes));
                    if mt_auto {
                        els.push(iced::widget::Space::new().height(iced::Length::Fill).into());
                    }
                    let align_self = extract_view_style(&c)
                        .and_then(|s| crate::ui::style::iced_adapter::IcedStyle::from_style(s).align_self);
                    let el = axis_fix_col_child(c).into_iced();
                    let el = match align_self
                    {
                        Some(crate::ui::style::iced_adapter::IcedAlign::End) => {
                            iced::widget::container(el)
                                .width(iced::Length::Fill)
                                .align_x(iced::alignment::Horizontal::Right)
                                .into()
                        }
                        Some(crate::ui::style::iced_adapter::IcedAlign::Start) => {
                            iced::widget::container(el)
                                .width(iced::Length::Fill)
                                .align_x(iced::alignment::Horizontal::Left)
                                .into()
                        }
                        Some(crate::ui::style::iced_adapter::IcedAlign::Center) => {
                            iced::widget::container(el)
                                .width(iced::Length::Fill)
                                .align_x(iced::alignment::Horizontal::Center)
                                .into()
                        }
                        _ => el,
                    };
                    els.push(el);
                }
                // Plan 490 G4：同 Row。
                wrap_layout_onclick(build_column(els, spacing, padding, style.as_ref(), None), onclick)
            }

            AbstractView::Input {
                placeholder,
                value,
                on_change,
                on_submit,
                width,
                password,
                style,
            } => {
                let mut input_widget = build_input_shape(&placeholder, &value, width, password, style.as_ref());

                // Wire on_input for text change tracking
                if let Some(msg) = on_change {
                    input_widget = input_widget.on_input(move |text| {
                        INPUT_TEXT.with(|t| *t.borrow_mut() = text.to_string());
                        msg.clone()
                    });
                }

                // Wire on_submit for Enter key press
                if let Some(msg) = on_submit {
                    input_widget = input_widget.on_submit(msg);
                }

                let el: iced::Element<'static, M> = input_widget.into();
                if let Some(ref s) = style {
                    let iced_style = IcedStyle::from_style(s);
                    wrap_with_margin(el, &iced_style)
                } else {
                    el
                }
            }

            AbstractView::Textarea { placeholder, value, on_change, on_submit, height, style, keymap, .. } => {
                // Plan 446 批五 U3:超大内容降级只读预览(rust 模式同款守卫,
                // 机理见 TEXTAREA_INLINE_EDIT_CAP)。
                if textarea_needs_preview(&value) {
                    let el = oversized_textarea_preview(&value);
                    if let Some(ref s) = style {
                        let is = IcedStyle::from_style(s);
                        wrap_with_margin(el, &is)
                    } else {
                        el
                    }
                } else {
                let key = format!("__textarea_{}", placeholder.len());

                let content = get_textarea_content(&key, &value);
                let ph: &'static str = Box::leak(placeholder.clone().into_boxed_str());
                let mut editor = text_editor(content).placeholder(ph);
                // PLAN-051 P2: 稳定 Id——iced text_editor 点击聚焦的前提
                  // (update 内 state.focus(id) 仅在 id 存在时执行;无 Id 则点
                  // 击永不聚焦=无光标无法输入,composer 命中区修复后仍复现
                  // 的最后缺口)。镜像 ash-gui 臂的 textarea_{key} 派生。
                editor = editor
                    .id(iced::widget::Id::from(format!("textarea_{}", key)))
                    // 此前不消费,可见容器内可点区只有顶部 30px 条(composer 命中区)。
                    .height(textarea_editor_height(height, style.as_ref()));

                // Plan 053 后续(ash-gui VM): apply class-driven text styling.
                // Previously the whole style prop was ignored (`style: _`), so the
                // Vue transparent-textarea + colored-overlay technique rendered the
                // typed text TWICE — once in the editor's default color, once in
                // the overlay spans. Applying text_color makes `text-transparent`
                // hide the editor copy (caret rides the same color), leaving only
                // the overlay; the placeholder stays a visible muted gray.
                if let Some(ref s) = style {
                    let is = IcedStyle::from_style(s);
                    if let Some(fs) = effective_font_size(&is) {
                        editor = editor.size(fs);
                    }
                    if is.text_color.is_some() {
                        let mut value_color = is.text_color.unwrap();
                        // PLAN-051 P2: 全透明 value 色(如 musk composer 的
                        // text-transparent+backdrop 叠加技法)在 VM 侧回退为可见
                        // 前景——VM 无 backdrop 渲染层,透明即"输入成功但不可视"。
                        // Vue 轨自渲染其 textarea,不受此臂影响。
                        if value_color.a <= 0.001 {
                            value_color = crate::ui::style::theme::resolve_semantic_rgb(
                                &crate::ui::style::Color::OnBackground,
                            )
                            .map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
                            .unwrap_or(iced::Color::WHITE);
                        }
                        let value_color = value_color;
                        editor = editor.style(move |_theme, _status| {
                            iced::widget::text_editor::Style {
                                background: iced::Background::Color(iced::Color::TRANSPARENT),
                                border: iced::Border::default(),
                                placeholder: iced::Color::from_rgba(0.55, 0.58, 0.65, 0.7),
                                value: value_color,
                                selection: iced::Color::from_rgba(0.3, 0.5, 0.9, 0.35),
                            }
                        });
                    }
                }

                // Plan 053 M4: Enter fires on_submit (onenter) — the newline is
                // already inserted by content.perform; input_value carries the
                // post-Enter content so the handler's bound field picks it up.
                let is_enter = |action: &text_editor::Action| {
                    matches!(action, text_editor::Action::Edit(text_editor::Edit::Enter))
                };
                let el: iced::Element<'static, M> = if let Some(msg) = on_change {
                    let action_key = key.clone();
                    let submit_clone = on_submit.clone();
                    editor.on_action(move |action| {
                        if is_enter(&action) {
                            if let Some(sm) = submit_clone.clone() {
                                let text = textarea_perform_action(&action_key, action);
                                INPUT_TEXT.with(|t| *t.borrow_mut() = text);
                                return sm.clone();
                            }
                        }
                        let text = textarea_perform_action(&action_key, action);
                        INPUT_TEXT.with(|t| *t.borrow_mut() = text);
                        msg.clone()
                    }).into()
                } else {
                    editor.into()
                };
                if let Some(ref s) = style {
                    let is = IcedStyle::from_style(s);
                    wrap_with_margin(el, &is)
                } else {
                    el
                }
                }
            }

            AbstractView::CodeEditor { key, value, lang, line_numbers, wrap, vi, highlight_current_line, tab_width, font_size, on_change, on_cursor, on_context_menu, search, style: _ } => {
                build_code_editor_generic(
                    &key, &value, &lang, line_numbers, wrap, vi,
                    highlight_current_line, tab_width, font_size, &search,
                    on_change, on_cursor, on_context_menu,
                )
            }

            AbstractView::AutodownEditor { key, value, is_final, on_change, on_focus, style: _ } => {
                build_autodown_editor_generic(&key, &value, is_final, on_change, on_focus)
            }

            AbstractView::Checkbox { is_checked, label, on_toggle, style } => {
                let iced_style = style.as_ref().map(IcedStyle::from_style);

                let cb_size = iced_style.as_ref().and_then(|is| {
                    match (&is.width, &is.height) {
                        (Some(IcedSize::Fixed(w)), Some(IcedSize::Fixed(h))) => Some(w.min(*h)),
                        (Some(IcedSize::Fixed(w)), None) => Some(*w),
                        (None, Some(IcedSize::Fixed(h))) => Some(*h),
                        _ => None,
                    }
                }).unwrap_or(20.0);

                let primary_color = iced_style.as_ref()
                    .and_then(|is| is.text_color)
                    .unwrap_or(iced::Color::from_rgb8(59, 130, 246)); // blue-500 or text-{color}
                let border_radius = iced_style.as_ref()
                    .map(|is| is.effective_border_radius())
                    .unwrap_or(4.0.into());
                let custom_border_color = iced_style.as_ref().and_then(|is| is.border_color);

                let mut checkbox_widget = checkbox(is_checked).size(cb_size);

                checkbox_widget = checkbox_widget.style(move |_theme, status| {
                    let is_checked = match status {
                        iced::widget::checkbox::Status::Active { is_checked }
                        | iced::widget::checkbox::Status::Hovered { is_checked }
                        | iced::widget::checkbox::Status::Disabled { is_checked } => is_checked,
                    };
                    let is_hovered = matches!(status, iced::widget::checkbox::Status::Hovered { .. });

                    let border_color = if is_checked {
                        primary_color
                    } else if is_hovered {
                        custom_border_color.unwrap_or(iced::Color::from_rgb8(156, 163, 175)) // gray-400
                    } else {
                        custom_border_color.unwrap_or(iced::Color::from_rgb8(209, 213, 219)) // gray-300
                    };

                    let background = if is_checked {
                        iced::Background::Color(primary_color)
                    } else {
                        iced::Background::Color(iced::Color::TRANSPARENT)
                    };

                    let icon_color = if is_checked {
                        iced::Color::WHITE
                    } else {
                        iced::Color::TRANSPARENT
                    };

                    iced::widget::checkbox::Style {
                        background,
                        icon_color,
                        border: iced::Border {
                            color: border_color,
                            width: 1.5,
                            radius: border_radius,
                        },
                        text_color: None,
                    }
                });

                // Plan 309 续篇 II: drop the handler in inspect-capture mode so
                // the checkbox is non-interactive (wrap_debug mouse_area picks).
                let handler = if inspect_capture_active() { None } else { on_toggle };
                let checkbox_with_handler = if let Some(msg) = handler {
                    checkbox_widget.on_toggle(move |_| msg.clone())
                } else {
                    checkbox_widget
                };

                // Apply text style to label
                let mut label_widget = text(label.clone());
                if let Some(ref is) = iced_style {
                    if let Some(fs) = effective_font_size(is) {
                        label_widget = label_widget.size(fs);
                    }
                    if let Some(color) = is.text_color {
                        label_widget = label_widget.color(color);
                    }
                }

                let el: iced::Element<'static, M> = if label.is_empty() {
                    let mut cont = container(checkbox_with_handler)
                        .align_x(iced::alignment::Horizontal::Center)
                        .align_y(iced::alignment::Vertical::Center);
                    if let Some(ref is) = iced_style {
                        if let Some(ref w) = is.width {
                            cont = cont.width(iced_length(w));
                        }
                        if let Some(ref h) = is.height {
                            cont = cont.height(iced_length(h));
                        }
                    }
                    cont.into()
                } else {
                    let mut row_widget = row![checkbox_with_handler, label_widget]
                        .align_y(iced::alignment::Vertical::Center)
                        .spacing(4);
                    if let Some(ref is) = iced_style {
                        if let Some(ref w) = is.width {
                            row_widget = row_widget.width(iced_length(w));
                        }
                        if let Some(ref h) = is.height {
                            row_widget = row_widget.height(iced_length(h));
                        }
                    }
                    row_widget.into()
                };

                if let Some(ref is) = iced_style {
                    wrap_with_margin(el, is)
                } else {
                    el
                }
            }

            AbstractView::Container {
                child,
                padding,
                width,
                height,
                center_x,
                center_y,
                style,
                onclick,
            } => {
                // Plan 490 G4：div/Container 点击（musk specs 树形态消费面）。
                wrap_layout_onclick(
                    build_container(
                        child.into_iced(),
                        padding,
                        width,
                        height,
                        center_x,
                        center_y,
                        style.as_ref(),
                        None,
                    ),
                    onclick,
                )
            }

            AbstractView::Scrollable { child, width, height, style, auto_scroll, offset, on_scroll } => {
                // Plan 049 → 057 续:仅 `auto_scroll` 标记的主列表挂固定 Id
                // (snap_to_end 目标)。此前所有 Scrollable 共享该 Id,块内 max-h
                // 滚动区会抢先命中 snap/scroll 操作 → 自动滚动失灵。
                // Plan 043 T1:offset 写入要求稳定 id——auto_scroll 标记自带
                // blocklist_scroll;其余 offset 绑定由调用面(aura_view_builder
                // scroll_sync 臂)传入显式 id,无 id 的 offset 静默不写入。
                let scroll_id = if auto_scroll {
                    Some("blocklist_scroll".to_string())
                } else {
                    None
                };
                build_scrollable(child.into_iced(), width, height, style.as_ref(), scroll_id, offset, on_scroll)
            }

            AbstractView::Grid { cols, gap, cells, style } => {
                let els: Vec<(iced::Element<'static, M>, GridCellSpec)> = cells
                    .into_iter()
                    .map(|c| {
                        let spec = grid_cell_spec(&c);
                        (c.into_iced(), spec)
                    })
                    .collect();
                build_grid(cols, gap, els, style.as_ref(), None)
            }

            // Plan 409 §10 续 5: Overlay = iced Stack 分层。base 在底,content 浮
            // 在上层(按 position 定位),不挤压 base 布局。opaque 吃点击穿透。
            AbstractView::Overlay { base, content, position } => {
                let base_el = base.into_iced();
                let content_el = build_floating_layer(content.into_iced(), position);
                iced::widget::stack![base_el, iced::widget::opaque(content_el)].into()
            }

            // Plan 484: hover 命中区 —— iced mouse_area 透明包裹,仅转发
            // enter/exit 消息(通用事件分发)。style(尺寸/定位类)经
            // build_container 承载——命中区必须定宽高,空内容才有可命中面积。
            // Plan 499 M2: 带 on_move 时再包 PointerArea——坐标换算(bounds
            // px → coords 逻辑幅面)+ ≤30Hz 限频 + 量化去重;不带 on_move
            // 的存量 mouse-area 映射零改动。
            AbstractView::MouseArea { content, on_enter, on_exit, on_double_click, on_click, on_context_menu, on_release, on_move, logical_extent, style } => {
                let mut ma = mouse_area(content.into_iced());
                if let Some(msg) = on_enter {
                    ma = ma.on_enter(msg);
                }
                if let Some(msg) = on_exit {
                    ma = ma.on_exit(msg);
                }
                // Plan 496 M5: ondblclick → iced mouse_area on_double_click
                //（桌面图标双击启动原语；inspect 捕获态丢臂与其余 handler 同规则）。
                if !inspect_capture_active() {
                    if let Some(msg) = on_double_click {
                        ma = ma.on_double_click(msg);
                    }
                    // Plan 498 M0: onclick → iced mouse_area on_press(chart
                    // legend 点击切换显隐;同 inspect 捕获态丢臂规则)。
                    // PLAN-043 T9: on_click 槽由 aura 臂按 onmousedown 优先
                    // 填充（真按下语义）；onmouseup → on_release（拖拽收尾）。
                    if let Some(msg) = on_click {
                        ma = ma.on_press(msg);
                    }
                    // PLAN-526 T10: oncontextmenu → iced on_right_press
                    //（桌面空白/任务栏右键菜单；同 inspect 捕获态丢臂规则）。
                    if let Some(msg) = on_context_menu {
                        ma = ma.on_right_press(msg);
                    }
                    if let Some(msg) = on_release {
                        ma = ma.on_release(msg);
                    }
                }
                let inner: iced::Element<'static, M> = ma.into();
                let wrapped: iced::Element<'static, M> =
                    if let Some(handler) = on_move.filter(|_| !inspect_capture_active()) {
                        let mut pa = crate::ui::iced::pointer_area::PointerArea::new(inner);
                        if let Some((w, h)) = logical_extent {
                            pa = pa.extent(w, h);
                        }
                        let f = std::sync::Arc::new(
                            move |x: f32, y: f32| handler.call(x, y),
                        );
                        pa.on_move(f).into()
                    } else {
                        inner
                    };
                build_container(
                    wrapped,
                    0,
                    None,
                    None,
                    false,
                    false,
                    style.as_ref(),
                    None,
                )
            }

            // Plan 422: 锚定弹层 —— wrapper widget(Tooltip 同型),open 时
            // 经 iced overlay 机制置顶;chrome 由 content 自带。inspect 捕获
            // 模式下丢 on_dismiss(与其余 handler 同规则)。
            AbstractView::Popover { anchor, content, placement, open, on_dismiss } => {
                use crate::ui::iced::popover::Popover as PopoverWidget;
                use crate::ui::view::PopoverAnchor;
                let (anchor_point, anchor_el): (Option<(f32, f32)>, iced::Element<'static, M>) =
                    match anchor {
                        PopoverAnchor::Widget(w) => (None, w.into_iced()),
                        // 坐标锚:零尺寸占位(anchor 轨道不影响布局),
                        // 面板定位由 at_point 决定。
                        PopoverAnchor::Point { x, y } => {
                            (Some((x, y)), iced::widget::Space::new().into())
                        }
                    };
                let mut p = PopoverWidget::new(anchor_el, content.into_iced())
                    .placement(placement)
                    .open(open);
                if let Some((x, y)) = anchor_point {
                    p = p.at_point(x, y);
                }
                let handler = if inspect_capture_active() { None } else { on_dismiss };
                if let Some(msg) = handler {
                    p = p.on_dismiss(msg);
                }
                p.into()
            }

            AbstractView::Radio {
                label,
                is_selected,
                on_select,
                style,
            } => {
                let checkbox_widget = checkbox(is_selected);

                // Plan 309 续篇 II: drop the handler in inspect-capture mode.
                let handler = if inspect_capture_active() { None } else { on_select };
                let checkbox_with_handler = if let Some(msg) = handler {
                    checkbox_widget.on_toggle(move |_| msg.clone())
                } else {
                    checkbox_widget
                };

                // Apply text style to label
                let mut label_widget = text(label.clone());
                if let Some(ref s) = style {
                    let iced_style = IcedStyle::from_style(s);
                    if let Some(fs) = effective_font_size(&iced_style) {
                        label_widget = label_widget.size(fs);
                    }
                    if let Some(color) = iced_style.text_color {
                        label_widget = label_widget.color(color);
                    }
                }

                row![checkbox_with_handler, label_widget]
                    .spacing(4)
                    .into()
            }

            AbstractView::Select {
                options,
                selected_index,
                on_select,
                style: _,
            } => {
                let selected_value = selected_index.and_then(|i| options.get(i).cloned());

                // Plan 309 续篇 II: in inspect-capture mode, render as static
                // text (the None branch) so it doesn't capture the press.
                let on_select = if inspect_capture_active() { None } else { on_select };
                match on_select {
                    Some(callback) => {
                        let options_clone = options.clone();
                        let picklist_widget = pick_list(options, selected_value, move |selected_string| {
                            let index = options_clone.iter()
                                .position(|s| *s == selected_string)
                                .unwrap_or(0);
                            callback.call(index, selected_string.as_str())
                        });
                        picklist_widget.into()
                    }
                    None => {
                        let display_text = selected_value
                            .unwrap_or_else(|| options.first().cloned().unwrap_or_default());
                        text(display_text).into()
                    }
                }
            }

            AbstractView::List { items, spacing, style } => {
                let eff_spacing = effective_spacing(spacing, style.as_ref(), false);
                let eff_padding = if let Some(ref s) = style {
                    let iced_style = IcedStyle::from_style(s);
                    iced_style.padding.unwrap_or(0.0)
                } else {
                    0.0
                };

                let mut col_widget = column([]);
                col_widget = col_widget.spacing(eff_spacing);
                if eff_padding > 0.0 {
                    col_widget = col_widget.padding(eff_padding);
                }

                for item in items {
                    col_widget = col_widget.push(item.into_iced());
                }

                col_widget.into()
            }

            AbstractView::Table {
                headers,
                rows,
                spacing: _,
                col_spacing,
                style: _,
                table_key: _,
                col_widths,
                on_col_resize,
            } => {
                // Plan 045 T3: 拖拽表格分派——on_col_resize Some 走 TableResize
                // widget（自持网格布局 + Drag 临时宽实时重排 + 松手 publish）；
                // None 走既有 lowering（零回归）。
                if let Some(cb) = on_col_resize {
                    let header_cells: Vec<_> = headers
                        .into_iter()
                        .map(|mut h| {
                            apply_table_header_style(&mut h);
                            h.into_iced()
                        })
                        .collect();
                    let body_rows: Vec<Vec<_>> = rows
                        .into_iter()
                        .map(|r| r.into_iter().map(|c| c.into_iced()).collect())
                        .collect();
                    return crate::ui::iced::table_resize::table_resize(
                        header_cells,
                        body_rows,
                        col_spacing as f32,
                        col_widths,
                        cb,
                    )
                    .into();
                }
                // Plan 411 P2-A④: vue 表格细节——表头 font-medium +
                // text-muted-foreground、行 border-b、单元格 px-4/py-3。
                // 行距改由 py-3 padding 提供(规则线与行贴合才是 border-b 语义),
                // 原 spacing 参数被 padding 取代。
                let mut table_widget = column([]);
                table_widget = table_widget.spacing(0.0);

                let mut header_row_widget = row([]);
                header_row_widget = header_row_widget.spacing(col_spacing as f32);
                for (ci, header) in headers.into_iter().enumerate() {
                    let mut h = header;
                    apply_table_header_style(&mut h);
                    // Plan 045 T2: 固定列宽应用——有值列 Fixed(w)，无值列
                    //（col_widths None 或长度不足的尾列）维持自然宽；超长
                    // 尾值无消费方自然截断。表头与体列同源（同一分派函数）。
                    let w = col_fixed_width(col_widths.as_deref(), ci);
                    header_row_widget =
                        header_row_widget.push(table_cell_container(h.into_iced(), w));
                }
                table_widget = table_widget.push(header_row_widget);
                table_widget = table_widget.push(table_row_rule());

                for row_data in rows {
                    let mut row_widget = row([]);
                    row_widget = row_widget.spacing(col_spacing as f32);
                    for (ci, cell) in row_data.into_iter().enumerate() {
                        let w = col_fixed_width(col_widths.as_deref(), ci);
                        row_widget = row_widget.push(table_cell_container(cell.into_iced(), w));
                    }
                    table_widget = table_widget.push(row_widget);
                    table_widget = table_widget.push(table_row_rule());
                }

                table_widget.into()
            }

            AbstractView::Slider {
                min,
                max,
                value,
                on_change,
                step,
                style: _,
            } => {
                // Plan 309 续篇 II: in inspect-capture mode render a static
                // read-out instead of the interactive slider (iced's slider
                // requires a callback). Cosmetic-only; 015-notes has no sliders.
                if inspect_capture_active() {
                    text(format!("{}", value)).into()
                } else {
                    use iced::widget::slider;
                    let mut slider_widget = slider(min..=max, value, on_change);

                    if let Some(step_value) = step {
                        slider_widget = slider_widget.step(step_value);
                    }

                    slider_widget.into()
                }
            }

            AbstractView::ProgressBar { progress, style } => {
                use iced::widget::progress_bar;
                let (is, height, width, radius) = if let Some(ref s) = style {
                    let is = IcedStyle::from_style(s);
                    let h = is.height.as_ref().map(iced_length).unwrap_or(iced::Length::Fixed(8.0));
                    let w = is.width.as_ref().map(iced_length).unwrap_or(iced::Length::Fill);
                    let r = if is.has_border_radius() || is.rounded {
                        is.effective_border_radius()
                    } else {
                        iced::border::Radius::from(9999.0)
                    };
                    (Some(is), h, w, r)
                } else {
                    (None, iced::Length::Fixed(8.0), iced::Length::Fill, iced::border::Radius::from(9999.0))
                };

                let (pr_r, pr_g, pr_b) = crate::ui::style::theme::resolve_semantic_rgb(&crate::ui::style::Color::Primary)
                    .unwrap_or((99, 102, 241));
                let bar_color = is.as_ref().and_then(|i| i.text_color.or(i.background_color))
                    .unwrap_or_else(|| iced::Color::from_rgb8(pr_r, pr_g, pr_b));
                let (bg_r, bg_g, bg_b) = crate::ui::style::theme::resolve_semantic_rgb(&crate::ui::style::Color::Secondary)
                    .unwrap_or((226, 232, 240));
                let bg_color = iced::Color::from_rgb8(bg_r, bg_g, bg_b);

                let pb = progress_bar(0.0..=1.0, progress)
                    .length(width)
                    .style(move |_theme| progress_bar::Style {
                        background: iced::Background::Color(bg_color),
                        bar: iced::Background::Color(bar_color),
                        border: iced::Border {
                            radius,
                            ..Default::default()
                        },
                    });

                let cont = container(pb).width(width).height(height);
                if let Some(ref is_ref) = is {
                    wrap_with_margin(cont.into(), is_ref)
                } else {
                    cont.into()
                }
            }

            // Plan 010: Unified Navigation Components

            AbstractView::Accordion {
                items,
                allow_multiple: _,
                on_toggle,
                style: _,
            } => {
                use iced::widget::container;

                let mut accordion_widget = column([]);

                for (idx, item) in items.into_iter().enumerate() {
                    let header_text = if let Some(icon) = item.icon {
                        format!("{} {}", icon, item.title)
                    } else {
                        item.title.clone()
                    };

                    let header_button = if let Some(callback) = &on_toggle {
                        let callback_clone = callback.clone();
                        button(text(header_text))
                            .on_press(callback_clone.call(idx, !item.expanded))
                    } else {
                        button(text(header_text))
                    };

                    let children_view: iced::Element<M> = if item.expanded && !item.children.is_empty() {
                        let mut children_col = column([]);
                        for child in item.children {
                            children_col = children_col.push(child.into_iced());
                        }
                        children_col.into()
                    } else {
                        text("").into()
                    };

                    let section = container(column![header_button, children_view].spacing(4));
                    accordion_widget = accordion_widget.push(section);
                }

                container(accordion_widget).padding(10).into()
            }

            AbstractView::Sidebar {
                content,
                width,
                collapsible: _,
                position: _,
                style: _,
            } => {
                use iced::widget::container;
                use iced::Length;

                let sidebar_container = container(content.into_iced())
                    .width(Length::Fixed(width))
                    .height(Length::Fill);

                sidebar_container.into()
            }

            AbstractView::Tabs {
                labels,
                contents,
                selected,
                position: _,
                on_select: _,
                style: _,
            } => {
                use iced::widget::container;

                let mut tabs_widget = column([]);

                let mut tab_buttons_row = row([]);
                for (idx, label) in labels.iter().enumerate() {
                    let is_selected = idx == selected;
                    let label_text = if is_selected {
                        format!("[{}]", label)
                    } else {
                        label.clone()
                    };

                    let tab_button = button(text(label_text));
                    tab_buttons_row = tab_buttons_row.push(tab_button);
                }

                tabs_widget = tabs_widget.push(tab_buttons_row);

                if let Some(content) = contents.get(selected) {
                    tabs_widget = tabs_widget.push(container(content.clone().into_iced()).padding(20));
                }

                container(tabs_widget).into()
            }

            AbstractView::NavigationRail {
                items,
                selected: _,
                width,
                show_labels,
                on_select: _,
                style: _,
            } => {
                use iced::widget::container;
                use iced::Length;

                let mut rail_widget = column([]);

                for item in items {
                    let item_text = if show_labels {
                        format!("{}  {}", item.icon, item.label)
                    } else {
                        item.icon.to_string()
                    };

                    let item_text_with_badge = if let Some(badge) = &item.badge {
                        format!("{} ({})", item_text, badge)
                    } else {
                        item_text
                    };

                    let nav_button = button(text(item_text_with_badge));
                    rail_widget = rail_widget.push(nav_button);
                }

                container(rail_widget)
                    .width(Length::Fixed(width))
                    .height(Length::Fill)
                    .padding(10)
                    .into()
            }

            // Plan 497: 每窗口真缩略渲染臂——T1 定案裁剪式整窗快照的
            // 消费端。命中进程级快照缓存 → image(Handle::from_rgba) 直绘
            // 降采样像素；miss → 标记异步抓取（宿主 update 排空
            // take_capture_requests，一次整窗 screenshot 服务全部请求）+
            // 本帧 fallback lucide 图标（复用 Image 臂路径，含 native wid
            // "N<slot>" parse 失败天然走 fallback——待澄清②）。
            AbstractView::WindowThumbnail { wid, fallback_icon, style } => {
                let is = style.as_ref().map(|s| IcedStyle::from_style(s));
                let eff_w = is.as_ref().and_then(|is| is.width.as_ref().map(iced_length));
                let eff_h = is.as_ref().and_then(|is| is.height.as_ref().map(iced_length));
                let snap = wid
                    .parse::<u64>()
                    .ok()
                    .map(crate::ui::session::Wid)
                    .and_then(crate::ui::iced::snapshot::snapshot_window);
                if let Some(snap) = snap {
                    let handle =
                        iced::widget::image::Handle::from_rgba(snap.w, snap.h, snap.rgba);
                    let mut img = iced::widget::image(handle)
                        .filter_method(iced::widget::image::FilterMethod::Nearest);
                    if let Some(w) = eff_w {
                        img = img.width(w);
                    }
                    if let Some(h) = eff_h {
                        img = img.height(h);
                    }
                    // 缩略 chrome：消费面 style 类（border/rounded/bg）落在
                    // 包裹 container 上（与 Image 臂 container 约束同型）。
                    let border_radius =
                        is.as_ref().and_then(|is| is.border_radius).unwrap_or(0.0);
                    let border_width =
                        is.as_ref().and_then(|is| is.border_width).unwrap_or(0.0);
                    let border_color = is
                        .as_ref()
                        .and_then(|is| is.border_color)
                        .unwrap_or(iced::Color::TRANSPARENT);
                    let bg = is
                        .as_ref()
                        .and_then(|is| is.background_color)
                        .map(iced::Background::Color);
                    let mut cont = container(img).style(move |_t| container::Style {
                        border: iced::Border {
                            color: border_color,
                            width: border_width,
                            radius: border_radius.min(9999.0).into(),
                        },
                        background: bg,
                        ..Default::default()
                    });
                    if let Some(w) = eff_w {
                        cont = cont.width(w);
                    }
                    if let Some(h) = eff_h {
                        cont = cont.height(h);
                    }
                    cont.into()
                } else {
                    if let Some(w) = wid.parse::<u64>().ok() {
                        crate::ui::iced::snapshot::request_capture(crate::ui::session::Wid(w));
                    }
                    let icon = if fallback_icon.is_empty() {
                        "app-window".to_string()
                    } else {
                        fallback_icon.clone()
                    };
                    AbstractView::Image {
                        src: format!("lucide:{icon}"),
                        style: style.clone(),
                    }
                    .into_iced()
                }
            }

            AbstractView::Image { src, style } => {
                // Plan 515 D1：hicon:<slot> = native 真图标 raster
                //（window_thumbnail 的 fallback_icon / image 直挂两消费面）。
                if let Some(icon) = crate::ui::iced::native_icon::parse_field(&src) {
                    let handle =
                        iced::widget::image::Handle::from_rgba(icon.w, icon.h, icon.rgba);
                    let is = style.as_ref().map(|s| IcedStyle::from_style(s));
                    let mut img = iced::widget::image(handle);
                    if let Some(ref is) = is {
                        if let Some(ref w) = is.width {
                            img = img.width(iced_length(w));
                        }
                        if let Some(ref h) = is.height {
                            img = img.height(iced_length(h));
                        }
                    }
                    return img.into();
                }
                // Plan 408: lucide: icon prefix → render bundled SVG glyph.
                if src.starts_with("lucide:") {
                    let icon_name = &src[7..];
                    let is = style.as_ref().map(|s| IcedStyle::from_style(s));
                    let w = is.as_ref().and_then(|is| is.width.as_ref().map(iced_length));
                    let h = is.as_ref().and_then(|is| is.height.as_ref().map(iced_length));
                    // Plan 518 G4②:大尺寸细线——固定宽或高 ≥48px 的独立图标
                    // 用 stroke-width 1.5（stella 线性观感）;PUA 按钮内嵌路径
                    // 尺寸随字号（<48px）保持默认 2。
                    let large = [&w, &h].into_iter().flatten().any(|len| {
                        matches!(len, iced::Length::Fixed(v) if *v >= 48.0)
                    });
                    let sw = if large { 1.5 } else { 2.0 };
                    if let Some(svg_str) = lucide_svg_doc_with(icon_name, sw) {
                        // Plan 409 §10 组 C → 2026-08-21 方案 A(ash-gui hover):
                        // 画时着色 —— svg::Style.color 由 iced 光栅化器把不透明
                        // 像素的 RGB 整体替换(按 (handle,size,color) 缓存,引擎
                        // 级 currentColor),取代旧的"颜色烘焙进 SVG 字节"(view
                        // 构建时定死,悬停无法变化)。基础色:自身 text-*(按钮内
                        // 经 inherit_text_color 已继承按钮色),回落 OnBackground
                        // (resvg 会把 currentColor 画成黑色)。悬停色:图标自己的
                        // hover:text-* —— svg::Status::Hovered 命中区即图标包围
                        // 盒,与 CSS 元素级 :hover 语义一致(hover:text 写在 icon
                        // 上,浏览器里也只在图标盒内触发,而非整个按钮)。
                        // 注:wgpu tint 只替换 RGB、忽略 Color.a —— 颜色自带透明
                        // 度(如 text-red-400/80)经 .opacity() 补偿;悬停色 alpha
                        // 忽略(opacity 构建期恒定)。
                        let base_color = is
                            .as_ref()
                            .and_then(|is| is.text_color)
                            .or_else(|| {
                                crate::ui::style::iced_adapter::resolve_semantic_rgb(
                                    &crate::ui::style::Color::OnBackground,
                                )
                                .map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
                            })
                            .unwrap_or(iced::Color::BLACK);
                        let hover_color = style.as_ref().and_then(|s| {
                            s.hover_classes.iter().find_map(|c| match c {
                                StyleClass::TextColor(color) => {
                                    Some(crate::ui::style::iced_adapter::convert_color(color))
                                }
                                _ => None,
                            })
                        });
                        let handle =
                            get_or_create_svg_handle(&src, svg_str.as_bytes().to_vec());
                        let mut svg_widget =
                            iced::widget::svg(handle).style(move |_, status| {
                                let color = match status {
                                    iced::widget::svg::Status::Hovered => {
                                        hover_color.unwrap_or(base_color)
                                    }
                                    _ => base_color,
                                };
                                iced::widget::svg::Style { color: Some(color) }
                            });
                        if base_color.a < 1.0 {
                            svg_widget = svg_widget.opacity(base_color.a);
                        }
                        svg_widget = svg_widget.width(w.unwrap_or(iced::Length::Fixed(16.0)));
                        svg_widget = svg_widget.height(h.unwrap_or(iced::Length::Fixed(16.0)));
                        // PLAN-054 T4 (A11): margin 系(ml-auto 贴行右端)在图标
                        // 出口消费——此前 container 直接返回,ml-auto 静默丢失。
                        if let Some(ref is) = is {
                            if is.margin_left_auto || is.margin_right_auto
                                || is.margin_left.unwrap_or(0.0) != 0.0
                                || is.margin_right.unwrap_or(0.0) != 0.0
                                || is.margin_top.unwrap_or(0.0) != 0.0
                                || is.margin_bottom.unwrap_or(0.0) != 0.0
                            {
                                return wrap_with_margin(container(svg_widget).into(), is);
                            }
                        }
                        return container(svg_widget).into();
                    }
                    // Unknown icon name: render empty placeholder
                    return container(iced::widget::text("")).into();
                }
                // Plan 442 A4: 内联 SVG 文档(view builder 序列化的 svg 元素
                // 子树)→ 复用缓存 svg::Handle 渲染。单色文档(以 currentColor
                // 描述填色/描边,如 musk 038 52-icon 数据层)走 lucide 同款
                // 画时着色(resvg 把 currentColor 画成黑,tint 整体替换不透明
                // 像素 RGB);多彩文档保持原色(tint 会毁掉配色)。
                if let Some(doc) = src.strip_prefix("svgdoc:") {
                    let is = style.as_ref().map(|s| IcedStyle::from_style(s));
                    let w = is.as_ref().and_then(|is| is.width.as_ref().map(iced_length));
                    let h = is.as_ref().and_then(|is| is.height.as_ref().map(iced_length));
                    // 混合色文档(静态色 + currentColor,如 donut 的灰底环 +
                    // accent 主弧)不能用整体 tint:tint 栅格化后全像素替换,
                    // 静态色环也被涂成主色(概要页 Memory donut 全黑的根因)。
                    // 改为构建期把 currentColor 字面量内联替换成实际色值——
                    // 文档不再含 currentColor,多彩路径保持各像素原色。
                    let (doc, tint) = if doc.contains("currentColor") {
                        let base_color = is
                            .as_ref()
                            .and_then(|is| is.text_color)
                            .or_else(|| {
                                crate::ui::style::iced_adapter::resolve_semantic_rgb(
                                    &crate::ui::style::Color::OnBackground,
                                )
                                .map(|(r, g, b)| iced::Color::from_rgb8(r, g, b))
                            })
                            .unwrap_or(iced::Color::BLACK);
                        let css = format!(
                            "#{:02x}{:02x}{:02x}",
                            (base_color.r * 255.0).round() as u8,
                            (base_color.g * 255.0).round() as u8,
                            (base_color.b * 255.0).round() as u8,
                        );
                        (doc.replace("currentColor", &css), base_color.a < 1.0)
                    } else {
                        (doc.to_string(), false)
                    };
                    let handle = get_or_create_svg_handle(&src, doc.as_bytes().to_vec());
                    let mut svg_widget = svg(handle);
                    if tint {
                        let base_color = is
                            .as_ref()
                            .and_then(|is| is.text_color)
                            .unwrap_or(iced::Color::BLACK);
                        svg_widget = svg_widget.style(move |_, _| iced::widget::svg::Style {
                            color: Some(base_color),
                        });
                        if base_color.a < 1.0 {
                            svg_widget = svg_widget.opacity(base_color.a);
                        }
                    }
                    if let Some(w) = w {
                        svg_widget = svg_widget.width(w);
                    }
                    if let Some(h) = h {
                        svg_widget = svg_widget.height(h);
                    }
                    // 尺寸必须同时约束外层 container:iced 0.14 Container::new
                    // 取 size_hint().fluid(),Svg 的 size_hint 默认 Fill → 无
                    // 约束时 container 撑满行内剩余宽(图标 Contain 居中画在
                    // 半宽处,同行文字被推到最远端——概要页 Uptime 行错乱形态)。
                    let mut svg_cont = container(svg_widget);
                    if let Some(w) = w {
                        svg_cont = svg_cont.width(w);
                    }
                    if let Some(h) = h {
                        svg_cont = svg_cont.height(h);
                    }
                    return svg_cont.into();
                }
                let bytes = load_image_bytes(&src);
                let is = style.as_ref().map(|s| IcedStyle::from_style(s));
                let eff_w = is.as_ref().and_then(|is| is.width.map(|w| iced_length(&w)));
                let eff_h = is.as_ref().and_then(|is| is.height.map(|h| iced_length(&h)));
                let px_w = is.as_ref().and_then(|is| is.width).and_then(|w| match w { IcedSize::Fixed(f) => Some(f), _ => None });
                let px_h = is.as_ref().and_then(|is| is.height).and_then(|h| match h { IcedSize::Fixed(f) => Some(f), _ => None });
                let border_radius = is.as_ref().and_then(|is| is.border_radius).unwrap_or(0.0);
                let border_width = is.as_ref().and_then(|is| is.border_width).unwrap_or(0.0);
                let border_color = is.as_ref().and_then(|is| is.border_color)
                    .unwrap_or(iced::Color::TRANSPARENT);
                let shadow = is.as_ref().map_or(false, |is| is.shadow);
                let bg = is.as_ref().and_then(|is| is.background_color).map(iced::Background::Color);

                let eff_img_w = match (px_w, border_width) {
                    (Some(w), bw) if bw > 0.0 => Some((w - 2.0 * bw).max(0.0)),
                    (Some(w), _) => Some(w),
                    _ => None,
                };
                let eff_img_h = match (px_h, border_width) {
                    (Some(h), bw) if bw > 0.0 => Some((h - 2.0 * bw).max(0.0)),
                    (Some(h), _) => Some(h),
                    _ => None,
                };
                let img_border_radius = if border_radius >= 9999.0 {
                    9999.0
                } else {
                    (border_radius - border_width).max(0.0)
                };

                if let Some(data) = bytes {
                    let data = if border_radius > 100.0 && (src.ends_with(".svg") || src.contains("/svg")) {
                        String::from_utf8(data)
                            .map(|mut s| { s = s.replace("rx=\"0\" ry=\"0\"", "rx=\"140\" ry=\"140\""); s.into_bytes() })
                            .unwrap_or_else(|e| e.into_bytes())
                    } else {
                        data
                    };
                    // Use cached handle to avoid flickering — same URL reuses the same Handle
                    let inner: iced::Element<'static, M> = if src.ends_with(".svg") || src.contains("/svg") {
                        let handle = get_or_create_svg_handle(&src, data);
                        let mut svg_widget = svg(handle);
                        if let Some(w) = eff_img_w { svg_widget = svg_widget.width(iced::Length::Fixed(w)); }
                        else if let Some(w) = eff_w { svg_widget = svg_widget.width(w); }
                        if let Some(h) = eff_img_h { svg_widget = svg_widget.height(iced::Length::Fixed(h)); }
                        else if let Some(h) = eff_h { svg_widget = svg_widget.height(h); }
                        svg_widget.into()
                    } else {
                        let handle = get_or_create_image_handle(&src, data, img_border_radius, eff_img_w, eff_img_h);
                        let mut img_widget = iced::widget::image(handle);
                        // Plan 527 T4: object-fit → ContentFit(缺失时 iced 默认 Contain)
                        if let Some(fit) = is.as_ref().and_then(|is| is.object_fit) {
                            img_widget = img_widget.content_fit(match fit {
                                crate::ui::style::ObjectFit::Contain => iced::ContentFit::Contain,
                                crate::ui::style::ObjectFit::Cover => iced::ContentFit::Cover,
                                crate::ui::style::ObjectFit::Fill => iced::ContentFit::Fill,
                                crate::ui::style::ObjectFit::None => iced::ContentFit::None,
                                crate::ui::style::ObjectFit::ScaleDown => iced::ContentFit::ScaleDown,
                            });
                        }
                        if let Some(w) = eff_img_w { img_widget = img_widget.width(iced::Length::Fixed(w)); }
                        else if let Some(w) = eff_w { img_widget = img_widget.width(w); }
                        if let Some(h) = eff_img_h { img_widget = img_widget.height(iced::Length::Fixed(h)); }
                        else if let Some(h) = eff_h { img_widget = img_widget.height(h); }
                        img_widget.into()
                    };

                    let mut cont = container(inner)
                        .center_x(eff_w.unwrap_or(iced::Length::Shrink))
                        .center_y(eff_h.unwrap_or(iced::Length::Shrink))
                        .clip(true);
                    if let Some(w) = eff_w { cont = cont.width(w); }
                    if let Some(h) = eff_h { cont = cont.height(h); }
                    if border_radius > 0.0 || border_width > 0.0 || shadow || bg.is_some() {
                        let br = if border_radius >= 9999.0 {
                            match (px_w, px_h) {
                                (Some(w), Some(h)) => w.min(h) / 2.0,
                                (Some(w), None) => w / 2.0,
                                (None, Some(h)) => h / 2.0,
                                _ => 9999.0,
                            }
                        } else {
                            border_radius
                        };
                        let bw = border_width;
                        let bc = border_color;
                        cont = cont.style(move |_| container::Style {
                            background: bg,
                            border: iced::Border::default().rounded(br).width(bw).color(bc),
                            shadow: if shadow {
                                iced::Shadow { offset: iced::Vector::new(0.0, 2.0), blur_radius: 8.0, color: iced::Color::from_rgba(0.0, 0.0, 0.0, 0.15) }
                            } else {
                                iced::Shadow::default()
                            },
                            ..Default::default()
                        });
                    }
                    cont.into()
                } else {
                    // Fallback: show a colored placeholder with initials
                    let initials = extract_initials(&src);
                    let child = text(initials).size(14).color(iced::Color::WHITE);
                    let mut cont = container(child)
                        .center_x(iced::Length::Fill)
                        .center_y(iced::Length::Fill);
                    let placeholder_bg = is.as_ref().and_then(|is| is.background_color)
                        .unwrap_or_else(|| iced::Color::from_rgb(0.24, 0.47, 0.85));
                    let br = border_radius.max(9999.0);
                    let bw = border_width;
                    let bc = border_color;
                    if let Some(w) = eff_w { cont = cont.width(w); }
                    if let Some(h) = eff_h { cont = cont.height(h); }
                    cont = cont.style(move |_| container::Style {
                        background: Some(iced::Background::Color(placeholder_bg)),
                        border: iced::Border::default().rounded(br).width(bw).color(bc),
                        ..Default::default()
                    });
                    cont.into()
                }
            }
        }
    }
}

/// Download image bytes from a URL using blocking HTTP.
/// Results are cached in memory so each URL is only fetched once.
/// Returns None on failure.
fn load_image_bytes(url: &str) -> Option<Vec<u8>> {
    use std::collections::HashMap;
    use std::sync::Mutex;

    static CACHE: std::sync::OnceLock<Mutex<HashMap<String, Option<Vec<u8>>>>> = std::sync::OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashMap::new()));

    // Check cache first
    {
        let lock = cache.lock().unwrap();
        if let Some(cached) = lock.get(url) {
            return cached.clone();
        }
    }

    // Fetch and cache
    let result = if let Some(name) = url.strip_prefix("builtin:") {
        // Plan 518：内嵌壁纸虚拟方案(builtin:ricepaper / builtin:inkwash)。
        match name {
            "ricepaper" => Some(WALLPAPER_RICEPAPER.to_vec()),
            "inkwash" => Some(WALLPAPER_INKWASH.to_vec()),
            _ => None,
        }
    } else if url.starts_with("http://") || url.starts_with("https://") {
        reqwest::blocking::get(url).ok()?.bytes().ok().map(|b| b.to_vec())
    } else {
        // Try loading from local file path
        std::fs::read(url).ok()
    };

    cache.lock().unwrap().insert(url.to_string(), result.clone());
    result
}

/// Cache image::Handle by URL and radius to avoid flickering.
/// Creating a new Handle each frame causes Iced to re-decode and re-upload the texture.
fn get_or_create_image_handle(
    url: &str,
    data: Vec<u8>,
    border_radius: f32,
    layout_w: Option<f32>,
    layout_h: Option<f32>,
) -> iced::widget::image::Handle {
    use std::collections::HashMap;
    use std::sync::Mutex;

    static CACHE: std::sync::OnceLock<Mutex<HashMap<String, iced::widget::image::Handle>>> = std::sync::OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashMap::new()));

    let cache_key = format!("{url}#r={border_radius}_{layout_w:?}_{layout_h:?}");
    let mut lock = cache.lock().unwrap();
    if let Some(handle) = lock.get(&cache_key) {
        return handle.clone();
    }

    let handle = if border_radius > 0.0 {
        if let Ok(dynamic_img) = image::load_from_memory(&data) {
            let mut rgba = dynamic_img.into_rgba8();
            let (w, h) = rgba.dimensions();
            if w > 0 && h > 0 {
                let r_px = if border_radius >= 9999.0 {
                    (w.min(h) as f32) / 2.0
                } else {
                    let scale_x = layout_w.map_or(1.0, |lw| if lw > 0.0 { w as f32 / lw } else { 1.0 });
                    let scale_y = layout_h.map_or(1.0, |lh| if lh > 0.0 { h as f32 / lh } else { 1.0 });
                    let scale = (scale_x + scale_y) / 2.0;
                    (border_radius * scale).min((w.min(h) as f32) / 2.0)
                };

                let cx = (w as f32) / 2.0;
                let cy = (h as f32) / 2.0;
                let half_w = cx;
                let half_h = cy;

                for y in 0..h {
                    for x in 0..w {
                        let px_val = ((x as f32 + 0.5) - cx).abs();
                        let py_val = ((y as f32 + 0.5) - cy).abs();
                        let qx = px_val - (half_w - r_px);
                        let qy = py_val - (half_h - r_px);
                        let dist = (qx.max(0.0).powi(2) + qy.max(0.0).powi(2)).sqrt() + qx.max(qy).min(0.0) - r_px;
                        if dist > 0.5 {
                            rgba.get_pixel_mut(x, y).0[3] = 0;
                        } else if dist > -0.5 {
                            let factor = (-dist + 0.5).clamp(0.0, 1.0);
                            let pixel = rgba.get_pixel_mut(x, y);
                            pixel.0[3] = (pixel.0[3] as f32 * factor) as u8;
                        }
                    }
                }
                iced::widget::image::Handle::from_rgba(w, h, rgba.into_raw())
            } else {
                iced::widget::image::Handle::from_bytes(data)
            }
        } else {
            iced::widget::image::Handle::from_bytes(data)
        }
    } else {
        iced::widget::image::Handle::from_bytes(data)
    };

    lock.insert(cache_key, handle.clone());
    handle
}

/// Plan 409 §8: recursively apply an inherited text color to every Text node
/// in the view that has no explicit `text-{color}` class. This gives the vue
/// equivalent of CSS text-color inheritance — a `link (to:) { text "Docs" }`
/// child inherits the button's theme color (text-primary) instead of falling
/// back to the body default (text-foreground). Only leaves that carry no
/// explicit color are touched; everything else (layout containers, images,
/// buttons) is preserved.
fn inherit_text_color<M: Clone + Debug>(view: &mut AbstractView<M>, color: Color) {
    match view {
        AbstractView::Text { style, .. } => {
            let has_explicit_color = style.as_ref().map_or(false, |s| {
                s.classes.iter().any(|c| matches!(c, StyleClass::TextColor(_)))
            });
            if !has_explicit_color {
                let mut inherited = style.take().unwrap_or_default();
                inherited.classes.push(StyleClass::TextColor(color));
                *style = Some(inherited);
            }
        }
        AbstractView::Button { content, .. } => {
            if let Some(c) = content {
                inherit_text_color(c, color);
            }
        }
        // PLAN-054 T5 (A10): Image 同样继承按钮文本色——发送钮
        // `bg-primary text-primary-foreground { Send{} }` 的图标此前落
        // OnBackground 回退,亮色主题下白钮白标不可见。
        AbstractView::Image { style, .. } => {
            let has_explicit_color = style.as_ref().map_or(false, |s| {
                s.classes.iter().any(|c| matches!(c, StyleClass::TextColor(_)))
            });
            if !has_explicit_color {
                let mut inherited = style.take().unwrap_or_default();
                inherited.classes.push(StyleClass::TextColor(color));
                *style = Some(inherited);
            }
        }
        AbstractView::Row { children, .. } | AbstractView::Column { children, .. } | AbstractView::List { items: children, .. } => {
            for child in children {
                inherit_text_color(child, color);
            }
        }
        AbstractView::Grid { cells, .. } => {
            for cell in cells {
                inherit_text_color(cell, color);
            }
        }
        AbstractView::Container { child, .. } | AbstractView::Scrollable { child, .. } => {
            inherit_text_color(child, color);
        }
        AbstractView::Table { headers, rows, .. } => {
            for h in headers {
                inherit_text_color(h, color);
            }
            for row in rows {
                for cell in row {
                    inherit_text_color(cell, color);
                }
            }
        }
        _ => {}
    }
}

/// Plan 408: Return a complete SVG string for a lucide icon name.
/// The SVG uses 16x16 viewport (scaled from lucide's 24x24), stroke-based
/// rendering matching lucide's visual style.
/// Plan 482: lucide_svg returns bare shape fragments (no <svg> root) —
/// resvg refuses to parse them, so every `lucide:` icon rendered EMPTY
/// (pre-existing gap hit by the nav search icon; also affects the PUA
/// button-icon path). Wrap into a full stroke-based document here.
/// Plan 518 G4②: stroke-width 参数化——默认 2（lucide 标准）,大尺寸
/// （渲染 ≥48px）用 1.5 细线对齐 stella 线性观感。
fn lucide_svg_doc(name: &str) -> Option<String> {
    lucide_svg_doc_with(name, 2.0)
}

fn lucide_svg_doc_with(name: &str, stroke_width: f32) -> Option<String> {
    let frag = lucide_svg(name)?;
    Some(format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"{stroke_width}\" stroke-linecap=\"round\" stroke-linejoin=\"round\">{frag}</svg>"
    ))
}

